const CHAPTER_INDEX=[{"number": 1, "title": "الخلية", "firstPage": 7, "lastPage": 47, "file": "الفصل-الأول-الخلية.html"}, {"number": 2, "title": "الأنسجة", "firstPage": 50, "lastPage": 85, "file": "الفصل-الثاني-الأنسجة.html"}, {"number": 3, "title": "التكاثر", "firstPage": 88, "lastPage": 138, "file": "الفصل-الثالث-التكاثر.html"}, {"number": 4, "title": "التكوين الجنيني", "firstPage": 141, "lastPage": 162, "file": "الفصل-الرابع-التكوين-الجنيني.html"}, {"number": 5, "title": "علم الوراثة", "firstPage": 165, "lastPage": 228, "file": "الفصل-الخامس-علم-الوراثة.html"}];
const META={"number": 5, "title": "علم الوراثة", "ordinal": "الخامس", "firstPage": 165, "lastPage": 228, "nodeCount": 117, "paragraphCount": 419, "questionCount": 40, "file": "الفصل-الخامس-علم-الوراثة.html"};
const CHAPTER=[{"id": "0", "title": "علم الوراثة ومصطلحاته", "code": "5–1", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p165s0", "page": 165, "title": "5–1. مقدمة ونبذة تاريخية", "paragraphs": ["يعرف علم الوراثة (Genetics) بأنه ذلك الفرع من علم الحياة الذي يهتم بدراسة التغايرات الموروثة لكائن حي أو لمجموعة من الكائنات وكذلك كيفية تعبير المورثات المسؤولة عن تلك التغايرات.", "ومن المجالات التي يهتم بها هذا العلم ما يأتي:", "أ. كيفية انتقال الصفات الوراثية من جيل إلى آخر.", "ب. معرفة التركيب الجزيئي للمادة الوراثية، والتغيرات التي تطرأ عليها وتطبيقاتها المختلفة.", "ج. معرفة كيفية حدوث عملية التعبير الوراثي على المستوى المظهري والجزيئي.", "إن أول من أطلق مصطلح (Genetics) على هذا العلم هو الباحث الإنكليزي بيتسون (Bateson) عام (1906م). وفيما يلي نبذة تاريخية مختصرة عن أهم الدراسات الوراثية التي ساعدت في تقدم هذا العلم:", "1. بداية تم انتخاب التغاير الوراثي للأنواع المفيدة، وذلك كطرز أو صفات مميزة تخدم الأجيال وتتلاءم مع متطلبات الحياة وخاصة في المجال الزراعي.", "2. وضع مندل أنظمة تحكم الوراثة بالصفات غير المرتبطة بالجنس، حيث نشر في عام (1866م) مقالة بعنوان «أبحاث حول بعض الهجائن النباتية» ولكن لسوء الحظ لم ينتبه إليها علماء عصره إلا بعد مرور 34 عاماً."]}, {"id": "c5p166s0", "page": 166, "title": "نبذة تاريخية — تتمة", "paragraphs": ["3. إن اكتشاف تجارب مندل عام (1900م) قد تخطى ما يسمى «بالعصر الذهبي» لعلم الخلية، وذلك عندما تم رؤية الكروموسومات والتي افترض بأنها حاملة للصفات الوراثية والتي لم تدرك آنذاك من قبل العالم مندل.", "4. لقد شهد الربع الثالث من القرن العشرين إيجاد حلول لكثير من الأسئلة وعلامات الاستفهام وذلك بحل اللغز الذي وصفه العالمان واطسن وكريك عام (1953م) حول تركيب جزيء الحامض النووي الرايبوزي منقوص الأوكسجين (DNA، Deoxyribonucleic acid) والذي توج في الستينات من القرن الماضي بحل الشفرة الوراثية (Genetic code).", "5. بدأ توجه علماء الوراثة في عقد الثمانينات نحو مجال التقنيات الأحيائية، حيث تمكنوا من تهجين الـ DNA لأنواع مختلفة بغية إيجاد عقار أو دواء ذو فعالية كبيرة وبكمية مناسبة وفي نفس الوقت تم اكتشاف المورثات التي تسبب أغلب التشوهات النادرة والتي ترجع إلى مورث مفرد (Single gene)، وبناء على ذلك تم تطوير طريقة التشخيص وحتى التوصل إلى اختبارات تسبق ظهور الأعراض، إضافة إلى ابتكار أنواع جديدة من المعالجات من خلال الهندسة الوراثية.", "6. لقد برزت في عام (1986) فكرة استخدام الـ DNA في المجالات التطبيقية وذلك لتميزه بعدد من الخصائص منها:", "قابليته على النقل من كائن إلى آخر بوساطة بعض النواقل كالرواشح (الفيروسات) والبلازميدات.", "قابليته على تحوير وظائف الخلية المستلمة له.", "قابليته على التضاعف داخل الخلية بصورة طبيعية وأيضاً خارجها وذلك من خلال استخدام تقنية التفاعل التضاعفي أو التسلسلي لشريط الـ DNA بوساطة الأنزيم المتعدد البوليمير (Polymerase Chain Reaction، PCR).", "7. في بداية القرن الحادي والعشرين وبالذات عام (2003م) تم كشف النقاب وبصورة كاملة عن إنجاز تسلسل أزواج القواعد النتروجينية والتي يتجاوز عددها 3.3 مليار (billion) وذلك لمورثات كروموسومات الإنسان في الحالة الأحادية والمسماة بالجينوم.", "8. حالياً تركز الأبحاث الجينية (Genomics) حول كيفية تعبير المورث في مختلف الخلايا سواء في المرضى أو في الأصحاء وكذلك في الكشف عن الاختلاف أو التمايز الوراثي الذي تكون له الأولوية في بناء الشخصية."]}, {"id": "c5p167s0", "page": 167, "title": "5–2. الوراثة ما قبل مندل — دور حضارة وادي الرافدين", "paragraphs": ["لقد صاحب نشأة هذه الحضارة في العراق القديم خلال الفترة الممتدة بين سنة (4000–800 ق.م.) الاهتمام في مجال الحصول على أنواع محسنة من الحنطة والرز والقطن والفول وكذلك الماشية والخيول.", "لقد أدرك سكان العراق آنذاك أهمية التكاثر الجنسي في الوراثة وتحسين المحصول وذلك من خلال ممارستهم تلقيح النخيل، وكذلك إجراء التزاوجات بين سلالات مختلفة من الماشية.", "وهذه موثقة من خلال الأختام التي وجدت هناك. فعلى سبيل المثال وجد بين تلك الوثائق رسالة فريدة من نوعها كتبت بالخط المسماري حوالي (1360 ق.م.) وقد أعطت وصف دقيق لكيفية تدريب الخيول وانتقاء أجودها للسباق."]}, {"id": "c5p167s1", "page": 167, "title": "5–2–2. دور حضارة وادي النيل", "paragraphs": ["لقد تلازمت بعض التطبيقات الرائدة لعلم الوراثة مع نشأة حضارة وادي النيل سنة (5000 ق.م.) حيث تم العثور من قبل فراعنة مصر القديمة على أنواع منتخبة من الحنطة تتسم بنوعية ووفرة الإنتاج."]}, {"id": "c5p167s2", "page": 167, "title": "5–2–3. دور الحضارة اليونانية", "paragraphs": ["لقد كان الفلاسفة اليونانيون مهتمين بتوضيح التشابه بين الأقارب. فأبقراط (Hippocrates، 460–370 ق.م.) قد أشار إلى تكرار صفات بشرية معينة مثل الحول في العين (Crossed eye)، والرأس ذو العلامة البيضاء (Bald headedness) في مجموعة معينة من العائلات.", "كما لاحظ أيضاً انتشار أمراض معينة مثل الصرع وبعض أنواع العمى في عوائل معينة. كما تعرف اليونانيون على أعراض بعض المتلازمات البشرية كمتلازمة داون (Down’s Syndrome). كما اهتموا كثيراً بفكرة البنية الطبيعية التي تمد الجسم بالمناعة."]}, {"id": "c5p168s0", "page": 168, "title": "5–2–4. دور الأوروبيين قبل مندل", "paragraphs": ["يعتبر عالم الأحياء موبرتويز (Maupertuis) من الذين سلطوا الضوء على أهمية وراثة الإنسان. لقد جمع سجلات نسب (Pedigrees)، شكل (5–1)، لبعض العوائل التي يحدث فيها صفة البرص (albinism)، شكل (5–2)، وقام بتحليلها وتنبأ باحتمال حدوثها في الأجيال القادمة، من خلال تطبيقه لنظرية الاحتمال.", "وفي منتصف القرن التاسع عشر تم تطبيق حالات انتقال بعض الصفات الوراثية في الإنسان كلون العيون (بني × أزرق) ولون شعر الجسم (أسود × أبيض) في القطط، وكذلك طبقت على الأبقار المعروفة بوفرة الشعر واللحم.", "سجل النسب: هو مخطط يستخدم لمتابعة توارث الصفة في العائلة، إذ إن المربع يشير إلى الذكر بينما الدائرة تشير إلى الأنثى والخط المتصل الواصل بينهما يشير إلى التزاوج أما التظليل الأسود فيشير إلى الفرد المصاب."]}]}, {"id": "1", "title": "الوراثة المندلية", "code": "5–2", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p169s0", "page": 169, "title": "الوراثة قبل مندل — تتمة", "paragraphs": ["وبعد منتصف القرن أعلاه طرح وايزمان (Weismann) الفكرة القائلة بأن الجبلة الجرثومية (germplasm) هي المادة الوراثية التي تنتقل من جيل إلى آخر. يتضح مما تقدم بأن حقائق التوارث تعتبر من الأمور المألوفة منذ زمن قديم لدرجة أنها كانت تؤخذ على علاتها كأمر مسلم به. لقد كان الاختلاف بين الأفراد معقداً ولم ينطبق عليه أي تحليل أو تفسير آنذاك. وعلى الرغم من ذلك فقد حاول بعض علماء الحياة وضع رؤى معينة لتفسير ظواهر التشابه والاختلاف، غير أنهم لسوء الحظ لم يتمكنوا من استنباط طريقة تجريبية ترتكز على أساس علمي لغاية مجيء الباحث النمساوي مندل (Mendel)، الذي قدم فرضياته الرئيسية حول انتقال الصفات الوراثية وذلك من خلال نتائج تجاربه على نبات البزاليا."]}, {"id": "c5p169s1", "page": 169, "title": "5–3. الوراثة المندلية", "paragraphs": ["يعتبر كريكر جوهان مندل (Gregor Johan Mendel)، الشكل (5–3)، أول من نجح في اكتشاف المبادئ الأساسية لعلم الوراثة. ولد في النمسا عام (1822م). شرع مندل بإجراء تجاربه على نبات البزاليا (Pisum sativum) عام (1856م) ولقد استغرقت تجاربه المتعددة زهاء ثمان سنوات بعدها قدم نتائج بحوثه إلى مجلة التاريخ الطبيعي عام (1865م) وتم نشرها بعد مرور سنة من التاريخ أعلاه ولكن للأسف بقيت نتائج أبحاثه طي الكتمان لمدة 34 عام من تاريخ نشرها، وذلك لانشغال علماء عصره بنظرية دارون (1809–1882م) في التطور العضوي. وفي مطلع القرن العشرين أعيد اكتشاف فرضيات مندل في الوراثة على أثر قيام ثلاثة علماء ببحوث متفردة أيدت نتائجها مبادئ مندل الرائدة في الوراثة وهم الهولندي دي فريز (De Vries) والألماني كورنز (Correns) النمساوي تشرماك (Tschermak) والذين كانوا مهتمين بدراسة وظيفة وسلوك الكروموسومات."]}, {"id": "c5p170s0", "page": 170, "title": "5–3–1. بعض خصائص الأحياء المستخدمة في تجارب الوراثة", "paragraphs": ["لقد أصبح من المعروف بأن المشتغلين في الوراثة يعتمدون على تصميم التجارب وتحليل نتائجها وذلك لغرض استخراج فرضية معينة منها حول كيفية انتقال الصفات المختلفة. وفيما يلي بعض الاعتبارات التي يتطلب مراعاتها عند استخدام كائن معين لغرض إجراء الدراسات الوراثية:", "1. قصر دورة حياته.", "2. إنتاجه أعداد كبيرة من النسل.", "3. امتلاكه إمكانية حصول تغايرات وطفرات وراثية عند تعرضه لظروف بيئية غير مناسبة كالإشعاع والمواد الكيميائية.", "4. إمكانية التحكم بالتلقيح أو التزاوج في ذلك الكائن.", "5. سهولة تربيته.", "6. إمكانية إنتاجه تراكيب جديدة نتيجة للتكاثر الجنسي أو الاقتران أو التوصيل (Transduction) والذي يحدث بوساطة الرواشح (Viruses).", "لقد أجري العديد من البحوث على الكائنات الأولية الدقيقة كالبكتيريا والفطريات وعلى بعض النباتات كالبزاليا والذرة الصفراء والشعير والحنطة والقرع والطماطة وحنك السبع وكذلك درست العديد من الصفات في الحيوانات كحشرة ذبابة الفاكهة والفأر والدجاج وخنزير غينيا والأبقار وكذلك في الإنسان."]}, {"id": "c5p170s1", "page": 170, "title": "جدول (5–1): عدد الكروموسومات في الخلايا الجسمية", "paragraphs": ["النباتات: البزاليا 14؛ الذرة 20؛ الفاصوليا 22؛ الرز 24؛ حنطة الخبز 28؛ زهرة الشمس 34.", "الحيوانات: البعوض 6؛ ذبابة الفاكهة 8؛ نحل العسل 32، 16؛ القطة 38؛ الفأر المنزلي 40؛ الإنسان 46.", "ذكور حشرة نحل العسل الاعتيادية تكون أحادية المجموعة الكروموسومية."]}, {"id": "c5p171s0", "page": 171, "title": "5–3–2. كيفية استخدام مندل نموذج الطريقة التجريبية لدراسة طرز التوارث", "paragraphs": ["إن نجاح مندل على الرغم من فشل الباحثين الآخرين من قبله قد يعزى إلى الأسباب الآتية:", "1. اختياره نموذج (Model) رائع في التصميم والتحليل لتجاربه الوراثية والتي أجريت على نبات البزاليا الذي يتسم بتغايره الوراثي وقدرته على النمو بسهولة وقابليته للتهجين بصورة اصطناعية (الشكل 5–4).", "2. لقد حدد فحوصاته على زوج واحد من الصفات أو عدد قليل جداً منها في كل تجربة (الشكل 5–5).", "3. حفظ سجلات مضبوطة والتي اعتمد عليها في التحليل الإحصائي لتجاربه."]}, {"id": "c5p172s0", "page": 172, "title": "التزاوجات التي أجراها مندل ونتائجها — شكل (5–5)", "paragraphs": ["الطرز المظهرية لسبعة أزواج من الصفات المتضادة التي درسها مندل في نبات البزاليا ونتائج تهجيناتها الأحادية. لاحظ أن كافة أفراد الجيل الأول F₁ كانت تحمل الطراز السائد، أما الطراز المتنحي فلقد عاود الظهور بنسبة 25% من أفراد الجيل الثاني F₂ (للاطلاع).", "موقع الزهرة: محوري × طرفي؛ أفراد الجيل الثاني 651 محوري، 207 طرفي؛ النسبة الفعلية 3.14:1 والتقريبية 3:1.", "طول النبات: طويل × قصير؛ 787 طويل، 277 قصير؛ النسبة الفعلية 2.84:1 والتقريبية 3:1.", "شكل القرن: منتفخ × متخصر؛ 882 منتفخ، 299 متخصر؛ النسبة الفعلية 2.95:1 والتقريبية 3:1.", "لون القرن: أخضر × أصفر؛ 428 أخضر، 152 أصفر؛ النسبة الفعلية 2.82:1 والتقريبية 3:1.", "ملمس البذرة: أملس × مجعد؛ 5474 أملس، 1850 مجعد؛ النسبة الفعلية 2.96:1 والتقريبية 3:1.", "لون البذرة: أصفر × أخضر؛ 6022 أصفر، 2001 أخضر؛ النسبة الفعلية 3.01:1 والتقريبية 3:1.", "لون الزهرة: أحمر × أبيض؛ 705 أحمر، 224 أبيض؛ النسبة الفعلية 3.15:1 والتقريبية 3:1."]}, {"id": "c5p173s0", "page": 173, "title": "5–3–3. بعض المصطلحات والرموز الوراثية", "paragraphs": ["لغرض فهم التهجين الأحادي (التضريب لصفة واحدة) والفرضيات التي تم اشتقاقها منه آنذاك، علينا أن نتعرف على عدد من المصطلحات الجديدة المستخدمة في هذا المجال وهي:"]}, {"id": "c5p173s1", "page": 173, "title": "الحليل (البديل) أو الأليل (Allele)", "paragraphs": ["هو إحدى حالات الطفرات المحتملة للعامل الوراثي (الجين) والذي يتميز عن الأليلات أو الحلائل الأخرى من خلال تأثيراته المظهرية. فإذن الأليل هو شكل آخر للجين أو متغاير الجين."]}, {"id": "c5p173s2", "page": 173, "title": "المورثات أو الجينات (Genes)", "paragraphs": ["هو تسلسل من الـ DNA التي تمتلك وظيفة معينة مثلاً قابليتها لأن تحول الشفرة الوراثية إلى بروتين أو تسيطر على التعبير عن الصفة وبالإمكان إثبات وجودها من خلال تغاير الأليلات."]}, {"id": "c5p173s3", "page": 173, "title": "التعبير الجيني (Gene expression)", "paragraphs": ["هي عملية استخدام معلومات الـ DNA من قبل الخلايا وذلك لتصنيع بروتين معين."]}, {"id": "c5p173s4", "page": 173, "title": "الطراز الوراثي أو الجيني (Genotype، G)", "paragraphs": ["هو يعكس التركيب أو البنية الوراثية للفرد ويعبر عنه برموز وراثية وذلك للإشارة إلى اتحاد الأليلات في فرد معين."]}, {"id": "c5p173s5", "page": 173, "title": "الطراز المظهري (Phenotype، P) أو الفئة المظهرية", "paragraphs": ["هو يشير إلى الخصائص أو العلامات المشاهدة للكائن الحي والمسيطر عليها وراثياً. فمثلاً صفتي طول الساق وقصره في نبات البزاليا يشار إليهما كتعبيرات طبيعية للمعلومات الموجودة في العوامل الوراثية.", "من خلال اتباع مبادئ الصفات السائدة والمتنحية يمكننا الإخبار عن الطراز المظهري للفرد من الطراز الوراثي فمثلاً (TT، Tt) طويلة الساق و(tt) قصيرة الساق. وعندما يحمل الفرد طراز وراثي متماثل العوامل مثل (TT، tt) فيقال لذلك الفرد بأنه متجانس أو نقي (Homozygous) وعندما يحمل الفرد طراز وراثي غير متماثل العوامل مثل (Tt) فيقال لذلك الفرد بأنه غير متجانس أو هجين (Heterozygous). لاحظ الشكل (5–6)، الذي يعطي مثال عن التضريب بين صفة سائدة نقية وصفة متنحية وكذلك المصطلحات الحديثة المستخدمة.", "أما بصدد رموز العامل الوراثي فعادة ما يستخدم الوراثيون طرق مختلفة بهذا الشأن، سنتطرق حالياً إلى ذكر رموز إحدى الصفات المندلية ولتكن صفة طول الساق في نبات البزاليا. حيث يعطى الحرف الكبير (T) ليشير إلى صفة الساق الطويل (Tall)، بينما يعطى الحرف (t) ليشير إلى صفة الساق القصير وهي صفة متنحية وفي مثل هذه الحالة تم اشتقاق هذا الرمز من المصطلح الخاص بالصفة السائدة، غير أنه غالباً ما يشتق ذلك الرمز من المصطلح الخاص بالصفة المتنحية (الشكل 5–6)."]}, {"id": "c5p174s0", "page": 174, "title": "كيفية استخدام الرموز وبعض المصطلحات الوراثية — شكل (5–6)", "paragraphs": ["يبين كيفية استخدام الرموز وبعض المصطلحات الوراثية في تهجين أحادي بين نبات بزاليا طويلة (TT) وقصيرة الساق (tt). تشير المستطيلات إلى الطرز الوراثية. أما الدوائر فتشير إلى الأمشاج.", "الآباء: TT × tt؛ أمشاج الآباء: T، t؛ الإخصاب؛ الجيل الأول F₁: Tt، طويلة هجينة.", "تهجين أفراد F₁: Tt × Tt؛ أمشاج F₁: T، t؛ الإخصاب؛ الجيل الثاني F₂: TT طويل، Tt طويل، Tt طويل، tt قصير."], "sourceFigure": "assets/figures/monohybrid-book.webp", "figurePage": 174}, {"id": "c5p175s0", "page": 175, "title": "بعض الرموز الوراثية المستخدمة في التضريبات وحل المسائل الوراثية", "paragraphs": ["F₁: الجيل الأول وهو مأخوذ من كلمة (Filial) اللاتينية وتعني ذرية وهكذا بالنسبة للجيل الثاني F₂ ... إلخ.", "G₁: يشير إلى أمشاج (Gametes) الآباء وهكذا G₂ بالنسبة لأمشاج الجيل الأول ... إلخ.", "P₁: يشير إلى الأبوين الأصليين (Parents) وهكذا بالنسبة إلى P₂ ... إلخ.", "×: علامة تزاوج أو تضريب أو تلقيح أو تهجين.", "♂: رمز لاتيني يشير إلى الأب أو الذكر.", "♀: رمز لاتيني يشير إلى الأم أو الأنثى."]}, {"id": "c5p175s1", "page": 175, "title": "5–3–4. التهجين الأحادي (Monohybrid Cross)", "paragraphs": ["هو تهجين وراثي بين فردين ويتضمن زوج من الصفات المتضادة التي ترجع إلى نفس الموقع الوراثي (مثل AA × aa). وبذلك فهو يكشف عن كيفية انتقال طرز هذه الصفات عبر الأجيال."]}, {"id": "c5p175s2", "page": 175, "title": "مثال عن التهجينات الأحادية لمندل", "paragraphs": ["تعتبر صفة طول الساق في نبات البزاليا مثال على ذلك. فعند التهجين بين بزاليا طويلة الساق نقية وبزاليا قصيرة الساق، كانت جميع أفراد الجيل الأول (F₁) طويلة الساق. وعند إجراء التلقيح الذاتي لأفراد الجيل الأول لاحظ مندل بأن 787 من 1064 لنباتات الجيل الثاني (F₂) كانت طويلة، بينما 277 من 1064 كانت قصيرة. إن هذه الأرقام تمثل النسبة التقريبية 2.84:1 أي حوالي 3:1. لذا فإن الصفة المتنحية التي لم تظهر في الجيل (F₁) عاودت للظهور في الجيل (F₂) وبنسبة 25%.", "يتضح من نتائج التهجينات المندلية بأنها لا تكون معتمدة على الجنس، أي أن مورثات (جينات) تلك الصفات تقع على كروموسومات جسمية وليست جنسية."]}, {"id": "c5p176s0", "page": 176, "title": "التهجين العكسي (Reciprocal Cross)", "paragraphs": ["وعادة يستخدم التهجين العكسي لغرض التأكد من أن صفة معينة يقع مورثها على كروموسوم جسمي أم جنسي، أو يقع في عضية سايتوبلازمية كالمايتوكوندريا.", "تضريب يحصل بين فردين أحدهما يحمل الطراز السائد والآخر يحمل الطراز المتنحي لصفة معينة وبالعكس ويتضمن تضريبين (أي استخدام الفرد الذي يحمل الطراز الجيني السائد كأب والفرد الذي يحمل الطراز الجيني المتنحي كأم في التضريب الأول وبالعكس في التضريب الثاني). فإذا كانت النتائج في الحالتين متشابهة فالمورثة لتلك الصفة تقع على كروموسوم جسمي وإذا كانت النتائج مختلفة عند عكس الطراز فهذا يعني أن مورثة الصفة تقع على كروموسوم جنسي أو في السايتوبلازم على إحدى العضيات وكما في المثال الآتي.", "مثال عن التهجين العكسي في نبات البزاليا: نبات إبطي الأزهار نقي AA × نبتة نهائية الأزهار نقية بالطبع aa؛ الأمشاج A، a؛ أفراد الجيل الأول Aa، 100% نباتات إبطية الأزهار هجينة. وبعكس الأبوين: نبتة إبطية الأزهار نقية AA × نبات نهائي الأزهار نقي aa؛ أفراد الجيل الأول Aa، 100% نباتات إبطية الأزهار هجينة."]}, {"id": "c5p177s0", "page": 177, "title": "5–3–5. فرضيات مندل (Mendel’s Postulates)", "paragraphs": ["إذن الصفة المدروسة هي صفة مندلية تقع على كروموسوم جسمي. ولغرض توضيح هذه النتائج افترض مندل وجود زوج من العوامل الوراثية لكل صفة، حيث أن هذه العوامل هي التي تتحكم بانتقال الصفة من جيل إلى آخر وهذا يؤكد نجاح مندل في تجاربه.", "لقد استخدم مندل توافق طرز النتائج التي حصل عليها في التهجين الأحادي لاشتقاق ثلاث فرضيات أو مبادئ في الوراثة وهي كالآتي:", "1. تكون العوامل زوجية (Unit Factors in Pairs) أي أن كل صفة يحملها الفرد مسيطر عليها من قبل زوج من العوامل. وعادة يحتوي الفرد الثنائي (Diploid) واحد من ثلاث طرز وراثية تعين الصفة وهي (AA أو Aa أو aa).", "2. الصفة السائدة والمتنحية (Dominant and recessive) عندما يوجد اثنين من العوامل غير المتماثلة (Aa) والمسؤولة عن صفة واحدة في فرد معين فإن أحد هذه العوامل (A) يكون سائد على الآخر المتنحي (a)، علماً بأن العامل المتنحي يكون مسؤول عن إظهار الصفة المتنحية وذلك عندما يكون بحالة زوجية (aa).", "3. الانعزال (Segregation) خلال عملية تكوين الأمشاج، تنفصل أو تنعزل أزواج العوامل غير المتماثلة (Aa) بصورة عشوائية ولهذا فإن كل مشيج سوف يستلم أحد هذين العاملين وباحتمالية متكافئة (شكل 5–7)."]}, {"id": "c5p178s0", "page": 178, "title": "قانون مندل الأول — قانون الانعزال", "paragraphs": ["أما إذا كان الفرد يحتوي على زوج متماثل من العوامل (aa) أو (AA) فيؤدي ذلك إلى أن جميع الأمشاج سوف تستلم عامل واحد، وبعد الإخصاب فإن أفراد الجيل (F₁) سوف تستلم عامل واحد من كل أب (Parent) وبذا تصبح الأفراد الناتجة مزدوجة العوامل، وعند التلقيح الذاتي لأفراد الجيل (F₁) فإن كل مشيج سوف يستلم بصورة عشوائية إما العامل السائد أو المتنحي، وبعد الإخصاب سوف تتكون أربع اتحادات لتكوين أفراد الجيل (F₂) وبنسبة سائد 3:1 متنحي.", "وعلى ضوء هذه الفرضية وضع مندل قانونه الأول المسمى بقانون الانعزال (Law of Segregation) والذي ينص على ما يأتي:", "«العوامل الوراثية المزدوجة في الفرد تنعزل عن بعضها عند تكوين الأمشاج ثم تعود لتزدوج بعملية الإخصاب عند تكوين أفراد النسل».", "أما بصدد الفرضية الرابعة لمندل والمسماة (بالتوزيع الحر) فسنتطرق إليها لاحقاً ضمن قانون مندل الثاني."]}, {"id": "c5p178s1", "page": 178, "title": "5–3–6. مربع بونيت (Punnett Square)", "paragraphs": ["إن الطرز الوراثية والمظهرية الناتجة من إعادة اتحاد الأمشاج خلال الإخصاب بالإمكان إظهارها للعيان وبسهولة من خلال (مربع بونيت).", "مربع بونيت: رسم هندسي يشبه رقعة الشطرنج توضع في يساره وبصورة عمودية الأمشاج الذكرية بينما توضع في أعلاه وبصورة أفقية الأمشاج الأنثوية أو بالعكس، الشكل (5–8).", "ويمكن من خلاله معرفة احتمالات كل اتحاد لهذه الأمشاج الذكرية أو الأنثوية وكذلك معرفة الطرز المظهرية والوراثية ونسب كل منها.", "لاحظ سهولة استخراج النسبة الوراثية (1:2:1) والنسبة المظهرية (3:1) لأفراد الجيل الثاني في التهجين الوارد في الشكل (5–8)."], "newFigure": "assets/figures/punnett-new.svg", "sourceFigure": "assets/figures/punnett-book.webp", "figurePage": 179}, {"id": "c5p179s0", "page": 179, "title": "5–3–7. التضريب الاختباري (Test Cross)", "paragraphs": ["إن الهدف من هذا التضريب هو التعرف على الطراز الوراثي للفرد الذي يحمل الصفة السائدة المجهولة النقاوة، حيث يتم تضريبه مع فرد آخر متنحي لتلك الصفة فإذا كان جميع أفراد النسل يحملون الطراز السائد فإن ذلك الفرد يكون نقياً في تلك الصفة، أما إذا كان 50% من أفراد النسل سائد و50% متنحي فيعني ذلك أن الفرد هجين في الصفة. ويمكن توضيح ذلك كالآتي:"]}, {"id": "c5p180s0", "page": 180, "title": "التضريب الاختباري — الاحتمالان", "paragraphs": ["الاحتمال الأول: عندما يكون الفرد نقي في الصفة السائدة لطول ساق نبات البزاليا؟ نبات طويل الساق نقي TT × نبات قصير الساق tt؛ الأمشاج T، t؛ أفراد الجيل الأول Tt، 100% نباتات طويلة الساق هجينة.", "الاحتمال الثاني: عندما يكون الفرد هجين في الصفة السائدة؟ نبات طويل الساق هجين Tt × نبات قصير الساق tt؛ الأمشاج T وt، t؛ أفراد الجيل الأول Tt وtt، 50% طويل الساق هجين، 50% قصير الساق.", "يعتبر التضريب الاختباري جزء من التضريب الرجعي."]}, {"id": "c5p180s1", "page": 180, "title": "التضريب الرجعي (Back Cross)", "paragraphs": ["هو تضريب يجرى بين أفراد هجينة من الجيل الأول مع أحد الأبوين أو مع فرد يماثل أحدهما. ويمكن الرجوع إلى الفقرة السابقة (5.3.7) لملاحظة نتائج التضريب مع الأب المتنحي في الصفة. أما نتائج التضريب الرجعي مع الأب السائد النقي في الصفة فيمكن مشاهدته في هذا المثال:"]}, {"id": "c5p181s0", "page": 181, "title": "التضريب الرجعي — مثال", "paragraphs": ["نبات طويل الساق هجين Tt × نبتة طويلة الساق نقية TT؛ الأمشاج T وt، T؛ أفراد الجيل الأول TT وTt، 100% طويل الساق."]}, {"id": "c5p181s1", "page": 181, "title": "5–3–8. التهجين الثنائي وقانون التوزيع الحر لمندل", "paragraphs": ["التهجين (التضريب أو التزاوج الثنائي) (Dihybrid Cross) هو تهجين يتضمن زوجين من الصفات المتضادة (GGWW × ggww). على سبيل المثال إذا لقح نبات بزاليا ذو بذور صفراء مستديرة نقية مع نبات بذور خضراء مجعدة فإن جميع أفراد F₁ ستكون صفراء مستديرة، وذلك لأن اللون الأصفر سائد على الأخضر والبذور المستديرة سائدة على المجعدة. وعند السماح لأفراد (F₁) الهجينة في الصفتين (GgWw) لتلقح ذاتياً فسنجد أن بذور أفراد (F₂) ستظهر وفقاً للنسبة التقريبية 9/16 صفراء مستديرة و3/16 صفراء مجعدة و3/16 خضراء مستديرة و1/16 خضراء مجعدة.", "أما قانون التوزيع الحر (Law of independent assortment) والذي يعرف أيضاً بقانون مندل الثاني، لقد تم وضعه من قبل مندل وذلك ترصيناً لفرضيته الرابعة وهي التوزيع الحر. ينص هذا القانون على: «إن أزواج العوامل الوراثية المنعزلة تتوزع بصورة مستقلة عن بعضها البعض وذلك خلال عملية تكوين الأمشاج».", "يشترط هذا القانون بأن أزواج العوامل الوراثية تنعزل بصورة مستقلة عن جميع أزواج العوامل الوراثية الأخرى. وكما نعلم فإنه نتيجة لعملية الانعزال يستلم كل مشيج عامل أو أليل (allele) واحد من كل زوج من العوامل الوراثية. إذ أن أي من العاملين أو الأليلين المنفصلين بالنسبة لزوج واحد لا يؤثر على حصيلة الانعزال لأي زوج آخر. لذا فتبعا لهذا القانون سوف تتشكل جميع الاتحادات المحتملة للأمشاج بتكرار متكافئ يبين الشكل (5–9) توضيح للتوزيع الحر خلال تكوين أفراد الجيل الثاني، حيث أن عملية تكوين الأمشاج من قبل نباتات الجيل الأول يشير الانعزال بأن يستلم كل مشيج إما الأليل G أو g وأليل W أو w بينما يفترض التوزيع الحر بأن جميع أنواع الاتحادات الأربعة للأليلات (GW، Gw، gW، gw) سوف تتشكل باحتمالات متساوية."], "sourceFigure": "assets/figures/dihybrid-book.webp", "figurePage": 182}]}, {"id": "2", "title": "الوراثة اللامندلية", "code": "5–3", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p182s0", "page": 182, "title": "التهجين الثنائي — تتمة", "paragraphs": ["إن في كل حالة إخصاب ما بين أفراد الجيل الأول (F₁ × F₁) تمتلك كل بيضة احتمالية متكافئة لاستلام واحد من الاتحادات الأربع من كل أب. وفي حالة إنتاج عدد كبير من أفراد النسل فسوف يتم الحصول على النسبة 9/16 صفر مستديرة، 3/16 صفر مجعدة، 3/16 خضر مستديرة، 1/16 خضر مجعدة البذور. وتعتبر هذه النسبة مثالية، وذلك لأنها مبنية على الجوانب الاحتمالية الصحيحة للانعزال والتوزيع الحر والإخصاب العشوائي. وقد يحصل انحراف عن هذه النسب وهذا خاضع للصدفة أو لنحو صارم وخاصة في الأعداد الصغيرة المنتجة من النسل لذا فإن النتائج الحقيقية نادراً ما تكون متطابقة مع النسبة المثالية. وراجع الفقرة (5.3.11).", "شكل (5–9): مخطط للتهجينات الثنائية في نبات البزاليا. لاحظ أن نباتات الجيل F₁ الهجينة تم تلقيحها ذاتياً وذلك لحساب النسبة المظهرية والنسبة الوراثية لأفراد الجيل الثاني F₂ (للاطلاع)."], "sourceFigure": "assets/figures/dihybrid-book.webp", "figurePage": 182}, {"id": "c5p182s1", "page": 182, "title": "5–3–9. التضريب الاختباري لصفتين", "paragraphs": ["يمكن أن يطبق التضريب الاختباري على الأفراد التي تحمل زوجين من الصفات السائدة المتضادة ولكن طرزها الوراثية غير معروفة (مجهولة النقاوة)، على سبيل المثال الطراز المظهري لنبات ذي بذور صفر مستديرة سائدة بالإمكان أن ينتج من الطرز الوراثية (GGWW، GGWw، GgWW، GgWw)، وفي حالة تهجينه مع نبات ذي بذور مستديرة مع نبات نقي ذي بذور خضر مجعدة ggww (متنحي) فإن تحليل النسب المظهرية والوراثية موضحة في الشكل (5–10)."]}, {"id": "c5p183s0", "page": 183, "title": "التضريب الاختباري لصفتين — شكل (5–10)", "paragraphs": ["نتائج التلقيح الاختباري لثلاثة أفراد متشابهة مظهرياً (ذات بذور صفراء مستديرة) ولكنها مختلفة وراثياً علماً بأن صفة لون البذور مستقلة عن صفة شكلها في نبات البزاليا (للاطلاع).", "أ. GgWW × ggww: النسب المظهرية 1/2 مستديرة صفراء، 1/2 مستديرة خضراء.", "ب. GgWw × ggww: النسب المظهرية 1/4 مستديرة صفراء، 1/4 مجعدة صفراء، 1/4 مستديرة خضراء، 1/4 مجعدة خضراء.", "ج. GGWw × ggww: النسب المظهرية 1/2 مستديرة صفراء، 1/2 مجعدة صفراء."]}, {"id": "c5p183s1", "page": 183, "title": "5–3–10. تفسير نتائج مندل في ضوء معرفة وظائف الكروموسومات والجينات", "paragraphs": ["الكروموسوم: هو تركيب خيطي الشكل مركب من جزيء الـ DNA المدعم بالحامض النووي الرايبوزي (RNA، Ribonucleic acid) والبروتين، والذي يحتوي على المعلومات الوراثية المرتبة بتسلسل شريطي وبالإمكان مشاهدته خلال عملية انقسام الخلية. أما الجين (المورث) فهو جزء من DNA الكروموسوم الذي يتحكم على الأقل في صفة وراثية محددة. وبما أن الكروموسومات موجودة على صورة أزواج متماثلة (الشكل 5–11) فالمورثات أيضاً موجودة على صورة أزواج كأن تكون (Aa) لصفة معينة و(Bb) لصفة أخرى وذلك فيما إذا كان الفرد هجيناً في هاتين الصفتين وهذا بالطبع يدعم الفرضية الأولى لمندل.", "وتتضح العلاقة بين سلوك الكروموسومات والجينات (المورثات) أيضاً من خلال الانقسام الاختزالي إذ يستلم كل مشيج كروموسوماً واحداً من كل زوج من الكروموسومات المتماثلة وبذلك فإنه أثناء ذلك الانقسام وأثناء عملية الإخصاب سوف يستلم الأبناء مورثاً واحداً لصفة معينة من الأب والآخر من الأم.", "كما أن التوزيع المستقل للكروموسومات على الأمشاج خلال الانقسام الاختزالي يدعم قانون التوزيع الحر لمندل، وذلك لأن المورثات في حالة كونها غير مرتبطة (أي لا تقع في نفس الكروموسوم) سوف تتوزع أيضاً بصورة مستقلة."]}, {"id": "c5p184s0", "page": 184, "title": "مثال 1: تطبيق على قانون مندل الثاني", "paragraphs": ["ذبابة فاكهة أبنوسية اللون طويلة الجناح لقحت بذكر رمادي اللون وأثري الجناح (vestigial) فكان جميع أفراد الجيل الأول (F₁) رمادية اللون وطويلة الجناح، علماً بأن العاملين الوراثيين لهاتين الصفتين يقعان على كروموسومين مختلفين.", "أ. ما الطرز الوراثية للأبوين ولأفراد الجيلين الأول والثاني؟", "ب. ما النسبة المظهرية لأفراد F₂؟", "ج. ما النسبة الوراثية لأفراد F₂؟", "د. بين نوعية وعدد الاتحادات الممكنة بين الأمشاج، وضح ذلك على مربع بونيت؟", "الاستنتاج والحل: بما أن جميع أفراد الجيل الأول كانت طويلة الجناح ورمادية اللون، إذن الجناح الطويل (L) سائد على الجناح الأثري (l)، واللون الرمادي (E) سائد على اللون الأبنوسي (e) وكذلك فإن الذبابة طويلة الجناح والذكر الرمادي اللون يجب أن يكون كل منهما نقياً لهاتين الصفتين. وبناءً على ذلك تكون الطرز الوراثية (للأبوين) ولأفراد الجيلين الأول والثاني كما يأتي:"]}, {"id": "c5p185s0", "page": 185, "title": "حل مثال قانون مندل الثاني", "paragraphs": ["P₁: ذكر رمادي أثري الجناح llEE × ذبابة فاكهة أبنوسية الجسم طويلة الجناح LLee.", "G₁: lE، Le؛ أفراد الجيل الأول F₁: LlEe، 100% رمادية اللون طويلة الجناح (هجينة).", "بعد ذلك يجرى تلقيحاً لأفراد F₁ كالآتي: ذكر رمادي طويل الجناح هجين LlEe × رمادية طويلة الجناح هجينة LlEe؛ الأمشاج الممكنة لكل أب: LE، Le، lE، le.", "وعند جمع الطرز الوراثية الواردة في مربع بونيت والتي تشترك بطراز مظهري معين فإننا سنحصل على النسبة المظهرية المتوقعة الآتية: 9 رمادية طويلة:3 أبنوسية طويلة:3 رمادية أثرية:1 أبنوسية أثرية.", "النسبة الوراثية: 1 LLEE؛ 2 LLEe؛ 2 LlEE؛ 4 LlEe؛ 1 LLee؛ 2 Llee؛ 1 llEE؛ 2 llEe؛ 1 llee.", "نوعية وعدد الاتحادات الممكنة بين الأمشاج: 16."]}, {"id": "c5p186s0", "page": 186, "title": "5–3–11. الاحتمالات الوراثية في تجارب مندل", "paragraphs": ["الاحتمالية: هي ترجيح وقوع حدث معين بنسبة تقديرية، ويمكن التعبير عنها بعدد عشري أو نسبة مئوية أو عدد كسري وتتحدد بالمعادلة الآتية:", "الاحتمالية = عدد المرات التي يمكن أن يتكرر فيها وقوع الحدث ÷ عدد المرات التي يقع فيها الحدث.", "إن نسب الطرز المظهرية والطرز الوراثية في الجيل F₂ تمثل النسب المتوقعة النظرية لتلك الطرز، ولكن نسبة تلك الطرز والتي يتم الحصول عليها فعلاً من تزاوج ما قد تكون مختلفة عن النسب المختلفة ويمكننا توضيح ذلك من إحدى التجارب المندلية حول صفة لون البذور (الشكل 5–5).", "لقد كان عدد البذور الصفر السائدة في الجيل (6022) بذرة، بينما كان عدد البذور الخضر المتنحية (2001) بذرة لذا يكون العدد الإجمالي للبذور (8023).", "وباستخدام معادلة الاحتمالية يمكننا تحديد النسبة الحقيقية للبذور الصفر في مثل هذا التهجين كالآتي: 6022/8023 = 0.7506، بينما تكون النسبة الحقيقية للبذور الخضر 2001/8023 = 0.2494.", "وللتعبير عن ذلك بالنسبة المئوية تكون نسبة الاحتمال المتوقع للبذور الصفر 75%، أما التعبير عنه على صورة عدد كسري فيكون 3/4، بينما تكون نسبة الاحتمال المتوقع للبذور الخضر 25% أما التعبير عنه على صورة عدد كسري فيكون 1/4. كذلك يمكن التعبير عن الأعداد الكسرية بصورة نسب مثلاً النسبة 3:1 تمثل الاحتمال النسبي الذي يمثله العدد الكسري 3/4 و1/4 على التوالي، إذ هذا يعني وجود ثلاث فرص من أصل أربع، أي أنه في كل مرة يعطى أبوان هجينان فرداً، يكون احتمال حمله للصفة السائدة، 3/4، ويعد احتمال حمله للصفة المتنحية 1/4. وعند الرجوع إلى النسب الحقيقية المحصل عليها في هذا المثال، وكذلك في التجارب الأخرى لمندل والواردة في (الشكل 5–5)."]}, {"id": "c5p187s0", "page": 187, "title": "الاحتمالات الوراثية — تتمة", "paragraphs": ["غالباً ما نشاهد وجود اختلاف بين النسبة الحقيقية المتحصل عليها في الحقل والنسبة المتوقعة وهذا قد يعزى إلى التجربة كأن تكون متعلقة بعدم توفر فرص متساوية للأمشاج عند عملية التلقيح وكذلك عدم توفر فرص متساوية لعاملي الفرد الهجين (Gg) من الانعزال بصورة متكافئة على الأمشاج.", "أما عندما نتعامل مع صفتين أو أكثر والتي تتوارث بصورة مستقلة عن بعضها (راجع الفقرة 5.3.8)، فيمكننا التنبؤ بجميع التكرارات المحتملة للطرز المظهرية في الجيل الثاني من خلال تطبيق قانون حاصل الضرب للاحتمالات والذي يشير إلى أنه عندما يوجد حدثان مستقلان بصورة تلقائية فإن الاحتمالية المركبة لحصيلة الاثنين تساوي حاصل ضرب حدوث احتمالات أفرادها."]}, {"id": "c5p187s1", "page": 187, "title": "5–4. الوراثة ما بعد مندل", "paragraphs": ["بعد إعادة اكتشاف تجارب مندل عام (1900م)، حصل توسع في دراسة العديد من الصفات الأخرى وفي أنواع مختلفة من الكائنات الحية، وذلك لمعرفة مدى انطباق قوانين مندل على وراثة تلك الصفات وهل توجد استثناءات عن ذلك؟", "لقد تبين فعلاً بأن المعلومات الوراثية المشاهدة لبعض الصفات لا تتفق بالضبط مع النسب المندلية المتوقعة. ولذا تم إعطاء فرضيات لتفسير تلك التحورات، آخذين بنظر الاعتبار كون أن الطرز المظهرية لبعض الصفات قابلة للتغير بطرق مختلفة حسب نوعية عواملها الوراثية والبيئية وفيما يلي بعض الأمثلة عن نوعية هذه الصفات. والتي قد يطلق عليها في بعض المصادر بالصفات اللامندلية."]}, {"id": "c5p187s2", "page": 187, "title": "5–4–1. الصفات التي تتحور عن النسبة المندلية 3:1 — السيادة غير التامة", "paragraphs": ["السيادة غير التامة (Incomplete dominance) وفيها يكون الطراز المظهري للفرد الهجين مختلفاً عن طرز الأبوين حيث يتخذ طرازاً وسطاً بينهما، أي بين الطرازين المظهريين لصفتين متضادتين نقيتين بسبب اختلاط تعبير الأليلين لهاتين الصفتين. وهذه الحالة تعتبر مختلفة عن حالة السيادة التامة للصفات التي درسها مندل.", "ومثال على ذلك ما يحدث عند تلقيح نبات حنك السبع أحمر الأزهار RR مع نبات أبيض الأزهار R′R′ فظهرت نباتات الجيل الأول وردية الأزهار RR′. وعند إجراء التلقيح الذاتي لأفراد الجيل الأول (F₁) كانت نباتات الجيل الثاني بالنسبة المظهرية 1 RR:2 RR′:1 R′R′ بيضاء، وردية، حمراء الأزهار على التوالي وهي مماثلة للنسبة الوراثية وكما موضح أدناه."]}, {"id": "c5p188s0", "page": 188, "title": "السيادة غير التامة — مخطط التهجين", "paragraphs": ["P₁: نبات حنك السبع أحمر الأزهار RR × نبات حنك السبع أبيض الأزهار R′R′؛ الأمشاج R، R′؛ F₁: RR′، 100% وردي الأزهار.", "P₂: نبات حنك السبع وردي الأزهار RR′ × نبات حنك السبع وردي الأزهار RR′؛ F₂: 1 RR أحمر:2 RR′ وردي:1 R′R′ أبيض."]}, {"id": "c5p188s1", "page": 188, "title": "السيادة المشاركة (المراكبة) (Codominance)", "paragraphs": ["هي الحالة التي يتم فيها التعبير عن الأليلين معاً في الطراز المظهري للفرد الهجين. ففي هذا النوع من السيادة لا يحدث أي اختلاط بين الأليلين في الطراز المظهري، كما أن أياً منهما لا يكون سائد أو متنحياً.", "مثال (1): عن مجاميع الدم A، B، AB في الإنسان: إن هذه المجاميع يحددها العاملان Iᴬ وIᴮ وهما يمثلان مستضدين (Antigens) يوجدان ضمن غشاء خلايا الدم الحمر. إن الطراز الوراثي لفرد ينتمي إلى مجموعة الدم AB هو IᴬIᴮ إذ لا يسود أي من الأليلين Iᴬ وIᴮ على الآخر، وبالطبع فإن خلايا الدم AB تحمل كلا المستضدين A وB في أغشيتها. وعند زواج آباء يحمل كل منهما الطراز الوراثي IᴬIᴮ فمن المحتمل الحصول على أطفال بالنسبة المظهرية والوراثية الآتية: 1 IᴬIᴬ، A:2 IᴬIᴮ، AB:1 IᴮIᴮ، B."]}, {"id": "c5p189s0", "page": 189, "title": "السيادة المشاركة — نظام الدم MN", "paragraphs": ["مثال (2): عن نظام الدم MN في الإنسان: إن الفرد ذو مجموعة الدم MM يمتلك المستضد M في حين أن الفرد ذا مجموعة N يمتلك المستضد N أما الفرد ذو مجموعة الدم MN فيمتلك كلا المستضدين M وN في غشاء خلايا الدم الحمر لذا فعند زواج آباء ذي تركيب وراثي LᴹLᴺ، فمن المحتمل حصولهم على أولاد بالنسبة الوراثية الآتية: 1/4 LᴹLᴹ:1/2 LᴹLᴺ:1/4 LᴺLᴺ.", "لقد استخدم الرمز L نسبة للعالم لاندشتاينر (Landsteiner) مكتشف مستضدي هاتين المجموعتين واللتين هما نوعان من جزيئات الكلايكوبروتين (Glycoprotein)."]}, {"id": "c5p189s1", "page": 189, "title": "السيادة المشاركة — لون الشعر في الماشية", "paragraphs": ["مثال (3): عن لون الشعر في بعض سلالات الماشية ذات القرون القصيرة (Short horns): يوجد أليلان (حليلان) يتحكمان بلون الشعر أحدهما مسؤول عن ظهور اللون الأحمر Cᴿ والآخر مسؤول عن ظهور اللون الأبيض Cᵂ، حيث إن C من Color أي لون وR من Red أي أحمر وW من White أي أبيض. وعند تضريب فردين أحدهما أحمر والآخر أبيض الشعر فإن جميع أفراد الجيل الأول تكون «غبارية» أي ذات شعر أحمر مبيض وبالفحص الدقيق وجد أن هذا اللون هو خليط من شعر بعضه أحمر والبعض الآخر أبيض.", "وعند إجراء تزاوج ما بين أفراد الجيل الأول، تم الحصول على النسبة المظهرية والوراثية الآتية في الجيل الثاني: 1 CᴿCᴿ أحمر:2 CᴿCᵂ غباري:1 CᵂCᵂ أبيض."]}, {"id": "c5p189s2", "page": 189, "title": "الأليلات المميتة (Lethal alleles)", "paragraphs": ["الأليل المميت هو الذي يؤدي تعبيره إلى هلاك الفرد الذي يرثه بصورة نقية سائدة في بعض الحالات أو بصورة متنحية في حالات أخرى ومن الأمثلة على هذه الأليلات ما يأتي:", "مثال (1): أليل فقر الدم المنجلي (Sickle-cell anaemia) يرجع هذا المرض الوراثي إلى أليل طافر متنحي Hbˢ يؤثر على نوعية خضاب الدم Hb (الهيموكلوبين) فيصبح من النوع الشاذ (هيموكلوبين S)، وكذلك يؤثر على شكل خلايا الدم الحمر حيث تصبح منجلية الشكل."]}, {"id": "c5p190s0", "page": 190, "title": "فقر الدم المنجلي — الطرز الوراثية والمظهرية", "paragraphs": ["يتضح مما تقدم بأن هذا الأليل المميت يكون ذو تأثير متعدد (Pleiotropic)، وفيما يلي جدول يبين الطراز الوراثي والمظهري للنسل الناتج من التزاوج بين أبوين كلايهما هجين لأليل فقر الدم المنجلي.", "HbᴬHbᴬ: سليم.", "HbᴬHbˢ: حامل للمورثة (الأليل).", "HbˢHbˢ: يموت بعد عمر المراهقة."]}, {"id": "c5p190s1", "page": 190, "title": "الأليل السائد للدجاج الزاحف", "paragraphs": ["مثال (2): الأليل السائد للدجاج الزاحف: يظهر هذا النوع من الدجاج في حالة وجود الأليل السائد المميت (C) مع الأليل العادي (c). وهي لا تستطيع السير بصورة اعتيادية بسبب قصر والتواء الأرجل. أما الأفراد النقية في هذا الجين (CC) فهي عادة تموت. وفيما يلي مثال عن تزاوج آباء زاحفة:", "Cc دجاجة زاحفة × Cc ديك زاحف؛ الأمشاج C، c؛ الأفراد CC مميت، Cc زاحف، Cc زاحف، cc اعتيادي."]}, {"id": "c5p191s0", "page": 191, "title": "الأليل السائد للفئران الصفراء", "paragraphs": ["مثال (3): الأليل السائد للفئران الصفراء: وهذه تشبه الحالة السابقة، فعند تضريب فئران صفراء هجينة مع بعضها ينتج موت ربع الأجنة الصفراء والتي هي نقية في الأليل المميت YY مما يؤدي إلى تحور النسبة المظهرية 3:1 إلى 2/3 صفراء هجينة:1/3 رمادية. إذن الفئران الصفراء تكون دائماً هجينة أي حاملة للجين المميت ولكنها غير متأثرة به. وللجين المميت أهمية في تصميم بعض التجارب الوراثية وفيما يلي تضريب لفردين هجينين لهذا الأليل المميت:", "Yy فأرة صفراء هجينة × Yy فأر أصفر هجين؛ الأفراد YY أصفر يموت، Yy أصفر، Yy أصفر، yy رمادي.", "ومن الأمثلة الأخرى عن الجينات المميتة ذات التأثير المظهري السائد هي صفة مقرض الجناحين في حشرة ذبابة الفاكهة وصفة انعدام الشعر في الكلاب المكسيكية."]}, {"id": "c5p191s1", "page": 191, "title": "5–4–2. النفاذ الجيني (Penetrance and Expressivity)", "paragraphs": ["النفاذ الجيني: هو احتمالية فرد يرث أليل ما ويمتلك الطراز المظهري الذي له علاقة بذلك الأليل.", "على سبيل المثال الأليل المتنحي الذي يسبب التليف الحوصلي (Cystic fibrosis) ذو نفاذية تامة حيث إن (100%) من الأفراد النقيين (cc) يتكون لديهم هذا المرض. وكذلك إن الأليل السائد لامتلاك أصابع إضافية (Polydactyl) في اليدين أو القدمين هو ذو نفاذية غير تامة وذلك لأن بعض الأفراد الذين يرثون هذا الأليل يمتلكون عشرة أصابع اعتيادية بينما آخرين يمتلكون أكثر من ذلك.", "أما التعبيرية: فهي تعني وجود أليل بإمكانه إنتاج مدى متغاير من الطرز المظهرية.", "ومثال على ذلك الحشرات النقية للجين المتنحي لطفرة انعدام العين (eyeless) تعطي طرز مظهرية يتراوح مداها ما بين وجود العيون الاعتيادية إلى اختزال جزئي في حجم العيون إلى انعدام إحدى أو كلا العينين."]}, {"id": "c5p192s0", "page": 192, "title": "5–4–3. الوراثة والبيئة (Genetics and Environment)", "paragraphs": ["للكائن الحي صفاته الخاصة به والتي ورثها من أبويه حيث يمكن تحديد صفاته المظهرية من خلال دراسة صفات أبويه وتحليل مورثاتها، ولكن هذا التحديد لا يمكن أن يكون دقيقاً وذلك لأن المورثات تحدد ما يمكن أن يكون عليه الكائن وليس ما سيكونه فعلاً لأن بعض الصفات المظهرية تعتمد على العوامل الوراثية والبيئية والتآزر (التداخل) بينهما. وهناك عدد من الحالات تبين أن تأثير المورثات يتحدد بالعوامل البيئية المختلفة سواء أكانت هذه العوامل محيطة بالكائن الحي أم داخله ولتوضيح ذلك نورد الأمثلة الآتية:", "مثال (1): تتأثر المورثات المسؤولة عن شكل الجسم في الإنسان بنوعية طعامه، فالسمنة والنحافة لهما أسس وراثية ولكن السيطرة على وزن الجسم تتأثر إلى حد كبير بكمية الطعام وعوامل أخرى.", "مثال (2): تأثير نوعية الغذاء كعامل بيئي على المورث المسؤول عن بناء لون الشحم في الأرانب: يرجع بناء الشحم الأصفر في الأرانب إلى مورث متنحي (y) علماً بأن الأرانب الحاوية على الطراز الوراثي (yy) تعاني من نقص أنزيمي وبذلك تصبح غير قادرة على هدم الصبغة الصفراء الموجودة في الجزر وفي نباتات أخرى، لذا حين تتغذى تلك الأرانب على نباتات حاوية على الصبغة الصفراء فإن تلك الصبغة سوف تظهر في شحومها. أما إذا تغذت الأرانب على نباتات خالية من الصبغة الصفراء فإن شحومها ستكون بالطبع بيضاء على الرغم من أن الطراز الوراثي (yy) يعبر عن تعبير الصبغة فقط. للأرانب الأخرى التي لا تحمل مورث الشحم الأصفر بحالتها النقية (YY) أو الهجينة (Yy) القدرة على تجزئة الصبغة الصفراء وبذا ستكون شحومها بيضاء على الرغم من أنها اقتاتت على طعام غني بالصبغة الصفراء."]}, {"id": "c5p192s1", "page": 192, "title": "5–4–4. تداخل الفعل الجيني (Gene Interaction)", "paragraphs": ["هو إنتاج طرز مظهرية جديدة بوساطة تداخل الأليلات لجينات مختلفة. وهناك نوعان من التداخل:", "أولاً: التداخل الجيني الذي يؤدي إلى حصول تغير في النسبة المظهرية المتوقعة ومثال على ذلك التفوق (Epistasis) والذي هو تداخل غير عكسي بين الجينات كوجود جين معين يتداخل في أو يمنع تعبير جين آخر. إن جين اللون الأبيض W للثمرة في نبات القرع (Squash) (شكل 5–13) متفوق على جين اللون الأصفر للثمرة Y."], "sourceFigure": "assets/figures/interaction-book.webp", "figurePage": 193}, {"id": "c5p193s0", "page": 193, "title": "تداخل الفعل الجيني — التفوق في القرع", "paragraphs": ["وعند تهجين سلالة بيضاء WWYY بأخرى خضراء wwyy الثمرة كان أفراد الجيل الأول أبيض الثمار، أما في الجيل الثاني فظهرت النسبة 12 بيضاء:3 صفراء:1 خضراء، تبين هذه النسبة بأن الأبوين مختلفان في زوجين من الجينات وأن الأب ذو الثمرة البيضاء يحمل جين اللون الأصفر الذي لم يظهر أثره لوجود جين اللون الأبيض المتفوق عليه. ويمكن توضيح كيفية الحصول على النسبة المظهرية والنسبة الوراثية من خلال استخدام مربع بونيت وكالآتي:", "P₁: WWYY نبات ذو ثمار بيضاء × wwyy نبات ذو ثمار خضراء؛ G₁: WY، wy؛ F₁: WwYy؛ P₂: WwYy × WwYy؛ الأمشاج WY، Wy، wY، wy."], "sourceFigure": "assets/figures/interaction-book.webp", "figurePage": 193}, {"id": "c5p193s1", "page": 193, "title": "تداخل الفعل الجيني في شكل العرف بالدجاج", "paragraphs": ["ثانياً: التداخل الجيني الذي لا يؤدي إلى حصول تغير في النسبة المظهرية المتوقعة غير أن أفراد الجيل الأول تمتلك صفة جديدة لا تشابه بها أي من الأبوين، أما أفراد الجيل الثاني فتمتلك صفتين جديدتين غير موجودة في الأجداد. ومثال على هذه الحالة هي شكل العرف (Comb) في الدجاج، فالشكل الوردي (Rose) للعرف يرجع إلى الجين R والذي يسود على أليله r للعرف المفرد (single)."], "sourceFigure": "assets/figures/interaction-book.webp", "figurePage": 193}, {"id": "c5p194s0", "page": 194, "title": "تداخل الفعل الجيني في شكل العرف — تتمة", "paragraphs": ["والشكل البازلائي (Pea) للعرف يرجع إلى جين P والذي يسود على أليله p للعرف المفرد أيضاً. وعند تضريب آباء وردية مع بازلائية والذين كليهما نقيين ظهر طراز جديد في الجيل الأول وهو العرف الجوزي (Walnut). وعند تضريب أفراد F₁ مع بعضها ظهر في F₂ الطرازين الجديدين (الجوزي والمفرد)، إضافة إلى طرازي الأجداد، وكالآتي:", "P₁: RRpp الشكل الوردي للعرف × rrPP الشكل البازلائي للعرف؛ الأمشاج Rp، rP؛ F₁: RrPp الشكل الجوزي للعرف؛ P₂: RrPp جوزي × RrPp جوزي.", "وبالطبع تكون النسبة المظهرية لأفراد الجيل الثاني كالآتي: 9 R–P– جوزي:3 R–pp وردي:3 rrP– بازلائي:1 rrpp مفرد."], "sourceFigure": "assets/figures/interaction-book.webp", "figurePage": 193}, {"id": "c5p194s1", "page": 194, "title": "5–4–5. الأليلات المتعددة (Multiple alleles)", "paragraphs": ["هي وجود بدائل أو حلائل أو أليلات مختلفة لنفس المورثة تحدث نتيجة لعملية الطفرة الحاصلة في جزيء المادة الوراثية DNA والتي تؤدي إلى حصول تغاير في المظهر، علماً بأنها تحتل نفس الموقع الوراثي على الكروموسوم المعين. ومن الأمثلة على الصفات متعددة الأليلات ما يأتي:"]}, {"id": "c5p195s0", "page": 195, "title": "نظام ABO في الإنسان", "paragraphs": ["تتحكم بهذا النظام ثلاثة أليلات على الأقل وهي Iᴬ، Iᴮ، i، فكما نعلم بأن الأليلين Iᴬ وIᴮ ذات سيادة مراكبة فيما بينهما ولكن كل منهما سائد على الأليل المتنحي i. يتحكم الأليلان Iᴬ، Iᴮ في تكوين شكلين مختلفين من أنزيم معين يتسببان في ظهور جزيئين مختلفين من المستضد (أنتجين) Antigen على سطح خلايا الدم الحمر. أما الأليل i فإنه لا يؤدي إلى تنشيط أي من شكلي الأنزيم ولهذا لن يظهر أي من المستضدين كما في الجدول (5–2). لاحظ أن الفرد الذي يرث أليلين من i تكون فصيلة دمه O.", "الجدول (5–2) يبين كيف أن الأليلات الثلاثة يمكن أن تتقابل على شكل أزواج وذلك لإنتاج أربع طرز من مجاميع الدم:", "A: المستضد A؛ الطراز الوراثي IᴬIᴬ أو Iᴬi.", "B: المستضد B؛ الطراز الوراثي IᴮIᴮ أو Iᴮi.", "AB: المستضدان A، B؛ الطراز الوراثي IᴬIᴮ.", "O: لا مستضد؛ الطراز الوراثي ii."]}, {"id": "c5p195s1", "page": 195, "title": "نقل الدم (Blood Transfusion)", "paragraphs": ["بداية يجب تعيين فصيلة الدم ABO والعامل الريسي Rh لكل من الواهب (Donor) والمستلم (Recipient) وذلك لأن خلايا الدم الحمر لبعض الأشخاص قد تتكتل بصورة واضحة وذلك عند خلطها بمصل دم أشخاص آخرين. هذا ما لاحظه لاندشتاينر (Landsteiner) عام 1900م.", "وإن أساس هذا التجمع هو التفاعل الناتج بين ما تحمله خلايا الدم الحمراء على سطحها من مستضدات (Antigens) وما يحويه مصل الدم (Serum) من أجسام مضادة (Antibodies)، علماً بأن العلاقة بينهما موضحة في الجدول (5–3).", "لقد تم الإشارة إلى المستضدات في هذا الجدول بالحرفين الكبيرين A، B وتمت الإشارة إلى الأجسام المضادة بالحرفين الصغيرين a، b."]}, {"id": "c5p196s0", "page": 196, "title": "جدول (5–3): مجاميع الدم والمستضدات والأجسام المضادة", "paragraphs": ["A: المستضدات على سطح خلايا الدم الحمر A؛ الجسم المضاد في المصل جسم مضاد b للمستضد B.", "B: المستضدات B؛ جسم مضاد a للمستضد A.", "AB: المستضدات A، B؛ لا جسم مضاد في المصل.", "O: لا مستضد؛ جسم مضاد a للمستضد A، جسم مضاد b للمستضد B.", "وعلى ضوء المعلومات الواردة في الجدول أعلاه يمكن تبيان التوافق أو عدم التكتل (التجلط) بين الواهب والمستلم في نقل مجاميع الدم ABO وكذلك عدم التوافق (حدوث التجلط) بينهما في (الشكل 5–14).", "توافق في مجاميع الدم (عدم التجلط): الواهب O والمستلم O، A، B، AB؛ الواهب A والمستلم A، AB؛ الواهب B والمستلم B، AB؛ الواهب AB والمستلم AB.", "عدم توافق في مجاميع الدم (تجلط): الواهب A والمستلم B، O؛ الواهب B والمستلم A، O؛ الواهب AB والمستلم A، B، O.", "الشكل (5–14) يبين كيف أن الوراثة قد وضحت التوافق وعدم التوافق في نقل مجاميع الدم ABO (للاطلاع)."]}, {"id": "c5p197s0", "page": 197, "title": "مستضدات العامل الريسي (Rh Antigens)", "paragraphs": ["وهي من المستضدات الأخرى التي توضح الأليلات المتعددة. لقد تم اكتشافها من قبل العالمين لاندشتاينر وواينر (Weiner) عام 1940م وأعطيت قدر كبير من الاهتمام وذلك لعلاقتها المباشرة بظهور حالة فقر الدم (اليرقان) لبعض الأطفال المولودين حديثاً والمسماة (Erythroblastosis fetalis). ولهذا السبب يتم فحص مجاميع الدم ABO والـ Rh للمقبلين على الزواج وذلك لاستبعاد ظهور هذا المرض في أطفالهم، وأخذ الاحتياطات اللازمة لذلك.", "قد يصاب بهذا المرض الأجنة ذو (Rh⁺) الموجبة واللذين أمهاتهم ذات (Rh⁻) سالبة وآبائهم ذا (Rh⁺) وبالطبع قد منح الأب هذا الأليل إلى الجنين وذلك لأن (Rh) هو سائد على (rh) وقد أصبح الجنين ذا طراز وراثي هجين (Rhrh). إن هذا الاتحاد الوراثي ينتج عدم توافق مناعي كامن بين الأم وجنينها. وإذا صادف جريان دم الطفل خلال مشيمة معابة (لعيب المشيمة أساس وراثي) ودخل إلى الدورة الدموية للأم فإن النظام المناعي لتلك الأم سوف يشخص مستضدات Rh كأجسام غريبة ويبدأ يقوم ببناء أجسام مضادة تجاهها.", "أما في الحمل الثاني فسوف يرتفع تركيز هذه الأجسام المضادة داخل الأم وعندما تمر تلك الأجسام خلال المشيمة فإنها بالطبع تدخل الدورة الدموية للجنين وتبدأ بتفتيت خلايا الدم الحمر للجنين والتي تسبب فقداً للهيموكلوبين ثم الإصابة بفقر الدم المسمى محلياً (أبو صفار). إن حوالي 10% من مجموع حالات الحمل البشرية تشير إلى عدم التوافق في الـ Rh، وعلى كل حال ولأسباب عديدة فإن أقل من 0.5% في الحقيقة تنتج فقر الدم. وعادة ما تعطى الأمهات غير المتوافقة وبعد الولادة مباشرة مادة مضادة لـ Rh (Anti-Rh) وذلك حال وضعها لطفل ذي Rh⁺. إن هذا المضاد يحطم أي خلايا من نوع (Rh⁺) والتي تسربت إلى الدورة الدموية للأم ولهذا سوف لا يكون بمقدورها إنتاج الأجسام المضادة للمستضد Rh الخاص بها."]}, {"id": "c5p197s1", "page": 197, "title": "وراثة نظام Rh", "paragraphs": ["إن الأبحاث الوراثية الأولية قادت إلى الاعتقاد بأنه في سكان البشر يوجد فقط حليلان أو أليلان تسيطر على وجود أو غياب المستضد. لقد افترضوا بأن أليل Rh يعني وجود المستضد على سطح الكرية الحمراء ويسلك كمورث سائد. وأن الأليل rh يؤدي إلى غياب المستضد.", "في مدينة البصرة لقد وجد عام 1976م بأن 93% من العينة المدروسة ذي (Rh⁺) و7% ذي (Rh⁻) وتبين بأن الطراز السالب يقل في المجتمعات الشرقية ربما بسبب الانتخاب ضد الأليل السالب. ونتيجة لإدخال تحسينات على الفحوصات اللازمة لتعيين وجود المستضد، أصبح واضحاً بأن هناك سلسلة من الأليلات المتعددة في موقع مفرد للـ Rh والتي يجب أن تؤخذ بعين الاعتبار لهذه التغايرات."]}, {"id": "c5p198s0", "page": 198, "title": "وراثة نظام Rh — تتمة", "paragraphs": ["لقد افترض العالم واينر لاحقاً بأن هناك سلسلة من الأليلات المتعددة في موقع مفرد للـ Rh والتي يجب أن تؤخذ بعين الاعتبار لهذه التغايرات.", "من جهة أخرى افترض العالمان فيشر (Fisher) وريس (Race) بأن هناك نوعاً بديلاً من التوريث يتضمن ثلاثة من المورثات المتقاربة والمرتبطة وهي C، D، E وكل واحد منها يضم أليلين تكون مسؤولة عن وراثة عوامل الـ Rh. إن المصطلح ارتباط (Linkage) يستخدم لوصف الجينات الواقعة على نفس الكروموسوم والذي هو الزوج الأول من الكروموسومات الجسمية بالنسبة لهذه المجموعة ويمكن للطالب اتباع الجدول الآتي والمبسط في حل المسائل الوراثية والمتعلقة بـ Rh.", "الطراز المظهري Rh⁺: الطراز الوراثي RhRh أو Rhrh.", "الطراز المظهري Rh⁻: الطراز الوراثي rhrh."]}, {"id": "c5p198s1", "page": 198, "title": "مثال عن مجموعة الدم Rh", "paragraphs": ["رجل تسلسل ولادته الأول في العائلة ذو مجموعة (Rh⁺) كان والده ذو (Rh⁺) أيضاً ولكن والدته كانت ذات (Rh⁻). تزوج هذا الرجل من امرأة ذات (Rh⁺) ولكن والدها كان ذا (Rh⁻). تنبأ بمجموعة الدم Rh لأولاده الناتجين. مع بيان عدد أولاده الذين سوف لا يصابون بمرض اليرقان.", "الاستنتاج: 1. بما أن والد الرجل ذو (Rh⁺) ووالدته (Rh⁻)، إذن الرجل هجين Rhrh. 2. بما أن المرأة ذات (Rh⁺) ووالدها (Rh⁻)، إذن هي أيضاً هجينة Rhrh.", "P₁: Rhrh × Rhrh؛ G₁: Rh، rh؛ F₁: RhRh، Rhrh، Rhrh، rhrh؛ النسبة 3 Rh⁺:1 Rh⁻. علماً أن جميع الأولاد سوف لا يصابون بهذا المرض."]}, {"id": "c5p198s2", "page": 198, "title": "سلسلة أليلات لون الفراء في الأرانب", "paragraphs": ["يعتبر لون الفراء مثال تقليدي عن الأليلات المتعددة أو المتضاعفة، حيث يمكن ملاحظة تأثير الأليل على الطراز المظهري بصورة مباشرة وبالعين المجردة، وبدون الحاجة إلى استخدام أي تقنية لتوضيح ذلك حيث يتحكم بلون الفراء أربعة أليلات مختلفة على الأقل وهي (C، cᶜʰ، cʰ، cᵃ)، علماً بأن الأليل (C) هو المسؤول عن اللون الرمادي (agouti) أو البري (wild) ويسود هذا الأليل سيادة تامة على كافة الأليلات الثلاثة المتبقية (cᶜʰ، cʰ، cᵃ). أما الأليل cᶜʰ فيسود بدوره على كل من الأليلين cʰ، cᵃ، في حين أن الأليل cʰ يسود على الأليل cᵃ."]}]}, {"id": "3", "title": "الطفرات", "code": "5–4", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p199s0", "page": 199, "title": "الطرز المظهرية والوراثية لألوان الفراء — جدول (5–4)", "paragraphs": ["لذا فإن ترتيب السيادة بالنسبة لهذه الأليلات يكون كالآتي: C > cᶜʰ > cʰ > cᵃ.", "الرمادي agouti: CC، Ccᶜʰ، Ccʰ، Ccᵃ.", "الفضي chinchilla: cᶜʰcᶜʰ، cᶜʰcʰ، cᶜʰcᵃ.", "الهمالايا Himalayan: cʰcʰ، cʰcᵃ.", "الأمهق albino: cᵃcᵃ.", "تدعي بعض المصادر بأن هناك سيادة غير تامة بين الأليلين، فإنه سيكون رمادي فاتح (Light Gray) من هذين الأليلين في نفس الفرد: cᶜʰcᵃ أو cᶜʰcʰ."]}, {"id": "c5p199s1", "page": 199, "title": "5–4–10. الطفرات (Mutations)", "paragraphs": ["الطفرة هي تغير مفاجئ في تتابع القواعد النتروجينية لجين أو لجزء من الـ DNA، علماً بأن هذا التغير قد يكون مصحوباً بظهور طراز وراثي ومظهري جديد (شكل 5–27) وعلى مستوى نوعية الخلايا هناك طفرات تحدث في الخلايا التناسلية (Germ cells) والمتمثلة بأمشاج الكائن الحي، علماً أن طفرات الخلايا التناسلية لا تؤثر في الكائن الحي نفسه، إلا أنها يمكن أن تنتقل إلى أولاده. وهناك طفرات تحدث في الخلايا الجسمية (Somatic Cells) للكائن وبذلك تؤثر فيه، مثلاً بعض أنواع سرطان الجلد وسرطان الدم لدى الإنسان علماً أن هذا النوع من الطفرات لا يورث."]}, {"id": "c5p200s0", "page": 200, "title": "آثار الطفرات وأنواعها", "paragraphs": ["قد تكون الطفرات ضارة كما في حالة اختزال الأجنحة في ذبابة الفاكهة وقصر الأطراف في الأغنام والعديد من الأمراض والمتلازمات (Syndromes) في الإنسان، كما قد تكون مميتة (Lethal) تؤدي غالباً إلى موت الجنين قبل الولادة.", "إلا أن بعض الطفرات قد تؤدي إلى طرز مظهرية مفيدة للفرد وقد تملك الكائنات الحية ذات الطفرات المفيدة فرصاً أفضل للتكيف والتكاثر والبقاء وبالتالي قد تكون مثل هذه الأفراد أكثر أهمية من الناحية الاقتصادية كالطفرات التي تؤدي إلى زيادة الإنتاج الحيواني والنباتي وتحسين نوعيته.", "يمكن للطفرات أن تتمثل في تغيرات على مستوى كروموسوم معين وتسمى (طفرات كروموسومية) أو على مستوى نيوكليوتيد معين وتسمى (طفرات جينية)."]}, {"id": "c5p200s1", "page": 200, "title": "أولاً: الطفرات الكروموسومية (Chromosomal mutations)", "paragraphs": ["تقسم الطفرات الكروموسومية إلى نوعين رئيسين هما:", "1. طفرات ترجع إلى تغيرات في عدد الكروموسومات ومنها ما يأتي:", "أ. التعدد الكروموسومي غير الحقيقي (Aneuploidy) وفي هذه الحالة يوجد كروموسوم واحد مفقود (ثنائي المجموعة الكروموسومية – كروموسوم واحد) أو كروموسوم واحد زائد (ثنائي المجموعة الكروموسومية + كروموسوم واحد).", "ب. تعدد كروموسومي تام (Polyploidy) وهو زيادة مجموعة كروموسومية كاملة فيكون الفرد ثلاثي المجموعة الكروموسومية.", "2. طفرات ترجع إلى تغيرات تركيبية في الكروموسومات ومنها ما يأتي:", "أ. تغير في عدد الجينات وتتضمن الفقد (Deletion) ويعني فقد جزء من الكروموسوم والتضاعف أي إن هناك قطعة من الكروموسوم قابلة للتكرار (الإعادة).", "ب. تغير في ترتيب الجينات وتتضمن الانقلاب (Inversion) والذي فيه يتكسر جزء من كروموسوم معين وينعكس ثم يتحد مجدداً مع الكروموسوم نفسه. والانتقال الذي فيه ينكسر جزء من كروموسوم معين ويتحد بكروموسوم غير متماثل له (الشكل 5–28). إن الطفرة التي تزود شخصاً معيناً بكروموسوم مضاف على الزوج الكروموسومي رقم 21 (الشكل 5–29) ناتجة عن حالة عدم الانفصال (Nondisjunction) إذ لا ينفصل هذا الكروموسوم عن نظيره أثناء الانقسام الاختزالي ويؤدي ذلك إلى احتواء أحد الأمشاج كروموسوماً إضافياً فيما ينقص الآخر هذا الكروموسوم وتسمى هذه الحالة متلازمة داون."]}, {"id": "c5p201s0", "page": 201, "title": "ثانياً: الطفرات الجينية (المورثية)", "paragraphs": ["تقسم نوعين:", "1. الطفرات النقطية (الموضعية) (Point mutations): هي الطفرة الناتجة من حذف أو إضافة أو استبدال نيوكليوتيدة واحدة بأخرى والتي تعود إلى موقع وراثي واحد (Locus).", "طفرة الحذف: وفيها يتم فقد نيوكليوتيدة واحدة من جين معين. وقد يؤدي هذا الفقد إلى تشكيل غير صحيح للكودونات (Codons) المتبقية ويسمى هذا بطفرة الإزاحة (Frame shift mutation) وهي التي تؤدي إلى تغير جميع الأحماض الأمينية التي تقع بعدها (شكل 5–30). هذه الطفرة يمكن أن تؤدي إلى تأثيرات خطيرة في وظيفة البروتين.", "الكودون (Codon): هي ثلاث قواعد نتروجينية متسلسلة (ثلاث نيوكليوتيدات في جزيء DNA أو RNA) وهي تحمل أو تشفر المعلومات لحامض أميني واحد."]}, {"id": "c5p202s0", "page": 202, "title": "الطفرات النقطية — الإضافة والاستبدال", "paragraphs": ["2. طفرة الإضافة (Insertion Mutation): ويتم فيها إدخال نيوكليوتيد واحد إلى جين معين مما قد يؤدي إلى طفرة الإزاحة أيضاً.", "3. طفرة الاستبدال (Substitution): وفيها يحل نيوكليوتيد واحد محل نيوكليوتيد آخر (شكل 5–30ب). وإذا حدث هذا الاستبدال في كودون معين فقد يتغير الحامض الأميني. وتكون طفرات الاستبدال على عدة أنواع ومنها ما يأتي:", "أ. الطفرة الاستبدالية المؤثرة (Missense Mutation).", "ب. الطفرة الاستبدالية الكامنة (المحايدة) (Neutral Mutation).", "ج. الطفرة الاستبدالية الصامتة (Silent Mutation).", "د. الطفرة الاستبدالية المثبطة (Nonsense Mutation)."]}, {"id": "c5p202s1", "page": 202, "title": "الطفرات المضاعفة (Duplicate Mutations)", "paragraphs": ["وتتضمن تأثر أكثر من زوج من القواعد النتروجينية للجين، حيث تحصل من خلال تكرار استنساخ جزء من المورث."]}, {"id": "c5p202s2", "page": 202, "title": "معدل حدوث الطفرة الذاتية", "paragraphs": ["تمتلك أغلب الكائنات الحية مورثات عديدة جداً ولذا فإن احتمال حدوث الطفرة في إحدى هذه المورثات بشكل كبير نسبياً. لقد تبين بأن معدل حدوث الطفرة الذاتية للمورث الواحد في حشرة ذبابة الفاكهة يتراوح بين (10⁻⁵–10⁻⁶) أي مرة واحدة لكل (100000–مليون مورث) في الجيل الواحد."]}, {"id": "c5p203s0", "page": 203, "title": "العوامل المطفرة (Mutagens)", "paragraphs": ["بينما يتراوح المعدل الكلي للطفرة في نفس الحشرات ما بين 1%–3%، علماً أن معدل الطفرة يختلف من مورث إلى آخر في نفس الفرد.", "إن هذا المعدل يمكن أن يزداد عند التعرض لبعض العوامل المطفرة (Mutagens) ومنها الإشعاعات ذات الطاقة العالية مثل الأشعة فوق البنفسجية والإشعاعات المؤينة مثل الأشعة السينية أو بعض الكيميائيات مثل حامض النتروز وأملاح الحديد والفورمالدهايد. لقد تبين بأن عدد من المواد الكيميائية المعروفة تكون مسرطنة (Carcinogenic) لذا يجب الحذر."]}, {"id": "c5p203s1", "page": 203, "title": "مضادات الطفرات (Antimutagens)", "paragraphs": ["بسبب المشاكل التي تحدثها بعض الطفرات اتجه العلماء حديثاً إلى إيجاد مواد مثبطة لبعض هذه الطفرات ومنها ما يأتي:", "1. المثبطات الحيوية (Bioantimutagens): وهذه تكون على هيئة عوامل معطلة أو مثبطة وعوامل لها دور ضمن عملية تضاعف الـ DNA أو عوامل أخرى لها دور ضمن عملية إصلاح الضرر فيه.", "2. المثبطات المباشرة (Desmutagens): كإيجاد مضادات تعمل بشكل مباشر على المطفرات مثل مضادات الأكسدة أو إيجاد عوامل عالقة (Blocking Agents)."]}, {"id": "c5p203s2", "page": 203, "title": "5–4–11. الوراثة البشرية (الوراثة في الإنسان) (Human genetics)", "paragraphs": ["على الرغم من أن وراثة الإنسان تعتبر من أقدم فروع الوراثة التطبيقية، وأن جنس الإنسان العاقل (Homo sapiens) هو أهم هدف لدراسة الوراثة، إلا أن هذا الفرع قد تطور ببطء مقارنة بفروع علم الوراثة الأخرى وذلك لوجود العديد من الصعوبات التي تواجه الباحثين في هذا المجال ومن هذه الصعوبات ما يأتي:", "1. إن صغر حجم العوائل البشرية لا يؤدي إلى ظهور جميع الاحتمالات وبذلك يصعب التأكد من نقاوة صفات الوالدين، لذا يعتبر حجم العوائل الكبيرة من المزايا المرغوب بها في الدراسات الوراثية، ولكن يقل عدد أكثر العائلات البشرية كثيراً عن العدد اللازم لوضع نسب وراثية قابلة للاختبار بصورة إحصائية.", "2. يستغرق عمر الجيل الواحد ولادته إلى أن يصل سن الرشد (البلوغ) سنوات طويلة، مما يجعل تتبع الصفات المدروسة في الجيل اللاحق يستغرق أيضاً وقت أطول."]}]}, {"id": "4", "title": "وراثة الإنسان", "code": "5–5", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p204s0", "page": 204, "title": "صعوبات دراسة الوراثة البشرية — تتمة", "paragraphs": ["3. يعتبر الزواج في الإنسان من الأمور الشخصية والتي لا يمكن التحكم فيها أو توجيهها وفق تزاوجات مسيطر عليها تجريبياً.", "4. إن العديد من الصفات البشرية لا يخضع للوراثة المندلية ولكنها تخضع للوراثة اللامندلية كالسيادة المراكبة والنفاذ غير التام وتداخل الفعل الجيني وتعدد المورثات ذات التأثير التراكمي والتي لا يمكن دراسة تأثير كل منها على انفراد.", "5. كثرة عدد الكروموسومات (الصبغيات) في الإنسان مقارنة بالكائنات الأخرى.", "لذا تعتمد دراسة الوراثة في البشر على ما يأتي:", "أ. ملاحظة ظهور أو اختفاء الصفات في الأفراد والأقارب عبر الأجيال وذلك من خلال رسم شجرة النسب وتجميع البيانات الإحصائية على مستوى عائلة واحدة وكذلك العديد من العوائل ذات الصلة بالصفة المدروسة.", "ب. دراسة التغيرات في التكرارات الجينية والتداخلات مع البيئة والتي تعتبر قاعدة معلومات مهمة للطب السريري.", "ج. الاستعانة بالتقنيات الجزيئية الحديثة من خلال معرفة تتابع القواعد النتروجينية للمورث وربطها بوظيفة ذلك المورث (راجع الجزء 5.5)."]}, {"id": "c5p204s1", "page": 204, "title": "5–4–11–1. سجلات النسب (Pedigrees)", "paragraphs": ["سجل النسب هو مخطط يظهر كيفية وراثة صفة معينة على مدى عدة أجيال (شكل 5–31) تشير المربعات في هذا السجل إلى الذكور، بينما تشير الدوائر إلى الإناث. المربع أو الدائرة القاتمة يعني وجود الصفة أو الحالة لدى الشخص في جيل معين وبالعكس بالنسبة للرمز الفاتح. الخط الأفقي الذي يصل بين ذكر وأنثى يشير إلى الزواج. الخط العمودي يشير إلى الأولاد الذين تم ترتيبهم من اليسار إلى اليمين وفقاً لتسلسل الولادة وبغض النظر عن الجنس. الأرقام الرومانية تشير إلى توالي الأجيال.", "يسمى الأفراد الأربعة في الجيل الخامس لسجل النسب أعلاه بالحاملين (Carriers) للمورث وذلك لأن لديهم أليلاً واحداً متنحياً فقط ولكنهم غير مصابين بالمرض، غير أنه لدى كل عائلة منهم قابلية على نقله إلى ابنه وبنته وعلى التوالي (من اليسار إلى اليمين)."], "sourceFigure": "assets/figures/pedigree-book.webp", "figurePage": 205}, {"id": "c5p205s0", "page": 205, "title": "5–4–11–2. توارث بعض الصفات الجسمية والاختلالات المرضية في الإنسان", "paragraphs": ["يمكن للمهتمين بالوراثة معرفة وراثة بعض الصفات والاختلالات الوراثية من خلال تحليل أنماط التوارث (Patterns of inheritance) أي تحليل التعبير عن الجينات على مدى الأجيال بوساطة سجلات النسب وفيما يأتي معايير الصفات السائدة الجسمية (الشكل 5–32) أي التي يقع الجين المسؤول عن كل واحدة منها على كروموسوم جسمي (جدول 5–5).", "1. تنتقل الصفة في الذكور والإناث وبتكرار متكافئ.", "2. إصابة الأجيال المتتابعة.", "3. توقف الانتقال بعد الجيل الذي لا يوجد فيه فرد مصاب.", "أما بالنسبة لمعايير الصفات المتنحية الجسمية (الشكل 5–32) فهي كالآتي:", "1. إصابة الذكور والإناث بتكرار متكافئ والأفراد المصابة بإمكانها نقل الجين إلا إذا سببت الموت قبل العمر التكاثري (قبل البلوغ).", "2. بإمكان الصفة أن تختفي لعدد من الأجيال.", "3. إن والدي الفرد المصاب يكونان طبيعيي الرؤية أو يمتلكان الصفة (جدول 5–5)."]}, {"id": "c5p206s0", "page": 206, "title": "توارث الصفات الجسمية — تتمة", "paragraphs": ["لا يقتصر أثر الوراثة على إظهار أو اختفاء بعض الصفات الجسمية فحسب ولكن يمتد إلى وظائف بعض الأعضاء واستعدادها للإصابة باختلالات أو تشوهات (Abnormalities) معينة تنتقل من الآباء إلى الأبناء بصورة مماثلة للصفات الأخرى، ومثال على ذلك تعدد الأكياس في الكلية بالنسبة للجين الجسمي السائد المسبب لها ومرض التليف الحوصلي بالنسبة للجين المتنحي المسبب لها (جدول 5–5).", "شكل (5–32): وراثة بعض الصفات الشائعة في الإنسان. الصفات السائدة: خط شعر ناتئ؛ وجود النمش؛ ذقن مشقوق؛ وجود الشعر؛ القابلية على طي اللسان؛ حني الإبهام إلى الخلف. الصفات المتنحية: خط شعر مستقيم؛ عدم وجود النمش؛ عدم وجود الغمازة؛ عدم وجود الشعر؛ عدم طي اللسان؛ حني الإبهام إلى الأمام."]}, {"id": "c5p207s0", "page": 207, "title": "الجدول (5–5): بعض الصفات الجسمية والاختلالات السائدة والمتنحية في الإنسان", "paragraphs": ["1. السائدة: القزمية وقصر الأطراف (Achondroplasia)؛ المتنحية: الحالة الطبيعية.", "2. السائدة: قصر الأصابع (Brachydactyly)؛ المتنحية: الحالة الطبيعية.", "3. السائدة: سرطان الثدي (Breast Cancer)؛ المتنحية: الحالة الطبيعية (غير مصابة).", "4. السائدة: الذقن المشقوق (Cleft)؛ المتنحية: مستدير (عدم وجود الشق).", "5. السائدة: وجود النمش (Freckles)؛ المتنحية: عدم وجود النمش (Clear).", "6. السائدة: حلمة الأذن الحرة (Free ear lobe)؛ المتنحية: حلمة الأذن الملتصقة.", "7. السائدة: وجود النقرة (الغمازة) في الذقن أو الخد (Dimples)؛ المتنحية: عدم وجود النقرة.", "8. السائدة: خط الشعر الناتئ (Widow’s peak)؛ المتنحية: مستقيم.", "9. السائدة: مرض الرقص (داء الرقص) (Huntington disease)؛ المتنحية: الحالة الطبيعية (غير مصاب).", "10. السائدة: زيادة الكولسترول في مصل الدم (Hypercholesterolemia)؛ المتنحية: الحالة الطبيعية.", "11. السائدة: تذوق مادة فينيل ثايوكاربامايد (Phenyl thiocarbamide)؛ المتنحية: غير متذوق.", "12. السائدة: تعدد الأكياس في الكلية (Polycystic Kidney disease)؛ المتنحية: الحالة الطبيعية.", "13. السائدة: زيادة الأصابع (Polydactyly)؛ المتنحية: وجود خمسة أصابع في الكف أو القدم.", "14. السائدة: الحالة الطبيعية؛ المتنحية: حالة اسوداد الإدرار (Alkaptonuria).", "15. السائدة: الحالة الطبيعية؛ المتنحية: حالة عدم القدرة على تنسيق الحركات الإرادية (التخلج) (Ataxia).", "16. السائدة: الحالة الطبيعية؛ المتنحية: مرض التليف الحوصلي (Cystic Fibrosis).", "17. السائدة: الحالة الطبيعية؛ المتنحية: مرض تاي ساكس (Tay–sachs).", "18. السائدة: الحالة الطبيعية؛ المتنحية: تجمع سكر الحليب في الدم (Galactosemia).", "19. السائدة: الحالة الطبيعية؛ المتنحية: إدرار الفينيل كيتون الحامضي (Phenylketonuria).", "20. السائدة: الحالة الطبيعية؛ المتنحية: فقر دم البحر الأبيض المتوسط (الثلاسيميا الكبرى) (Thalassemia major)."]}, {"id": "c5p208s0", "page": 208, "title": "5–4–11–3. كروموسومات الإنسان", "paragraphs": ["يطلق على الكروموسومات التي ليس لها علاقة مباشرة بتعيين الجنس في الإنسان بالكروموسومات الجسمية (الجسدية) (Autosomes) وعددها 22 زوجاً أما الزوج المتبقي فهو كما نعلم يمثل كروموسومي الجنس (أي زوج واحد يعين الجنس).", "يمكن تمييز كروموسومات الإنسان حسب موضع السنترومير (الجزء المركزي) فيها، شكل (5–33)، إلى الأنواع الآتية:", "أ. الكروموسوم وسطي السنترومير (Metacentric chromosome).", "ب. الكروموسومات ذات السنتروميرات القريبة من الوسط (Submetacentric Chromosomes).", "ج. الكروموسومات ذات السنتروميرات القريبة من الطرف (Acrocentric chromosomes).", "د. كروموسومات طرفية السنترومير (Telocentric Chromosomes).", "وعلى أساس طول الكروموسوم وموضع السنترومير فإن كروموسومات الإنسان العادية قد رتبت في 7 مجاميع من الكروموسومات الجسمية من A إلى G، وزوج واحد من كروموسومات الجنس إما XY (شكل 5–34) أو XX. وعلى هذا الأساس فإن 23 زوج من الكروموسومات في الخلايا الجسمية تقسم كالآتي:"]}, {"id": "c5p209s0", "page": 209, "title": "مجاميع كروموسومات الإنسان — شكل (5–34)", "paragraphs": ["المجموعة A: الكروموسومات 1–3؛ B: 4، 5؛ C: 6–12؛ D: 13–15؛ E: 16–18؛ F: 19–20؛ G: 21–22؛ X: XY أو XX.", "من خلال ملاحظة حجم الكروموسوم X وموضع السنترومير فيه نجد أن هذا الكروموسوم يشابه كروموسومات المجموعة C من الكروموسومات الجسمية، بينما كروموسوم Y يشابه كروموسومات المجموعة G الجسمية."]}, {"id": "c5p209s1", "page": 209, "title": "5–4–11–4. تشخيص الأمراض الوراثية", "paragraphs": ["إن الأفراد الذين لديهم تاريخ عائلي للإصابة بمرض وراثي يخضعون عادة لتحري وراثي وخاصة قبل إنجاب الأولاد. ويوجد حالياً طريقتين لإجراء هذا التشخيص:", "أ. طريقة بزل السائل الأمنيوتي أو السلوي (الرهلي) (Amniocentesis).", "ب. طريقة فحص الخملات الكوريونية (Chorionic villi) الواقعة في بطانة الرحم."]}, {"id": "c5p209s2", "page": 209, "title": "5–4–11–5. تخفيف أعراض بعض الأمراض الوراثية", "paragraphs": ["ويتم ذلك بعدة طرق منها ما يأتي:", "1. الحمية الغذائية: وتوصف بالنسبة لبعض أمراض الأيض الغذائي الوراثية كمرض فينيل كيتون يوريا.", "2. العلاج الطبيعي: ويوصف لمرضى التليف الحوصلي، حيث يخضع المرضى لعدد من الجلسات التي يستخدم فيها عملية الطرق على الظهر والصدر وذلك لطرد المواد المخاطية اللزجة من الرئتين."]}, {"id": "c5p210s0", "page": 210, "title": "تخفيف أعراض الأمراض الوراثية — تتمة", "paragraphs": ["3. استخدام حقن معينة بالنسبة لبعض الأمراض كما هو الحال بالنسبة لحقن الأنسولين المستخدمة في معالجة البول السكري وحقن بروتين تجلط الدم لمعالجة مرضى نزف الدم الوراثي.", "4. إجراء بعض العمليات الجراحية للجنين (في حالات محدودة) وذلك لغرض إصلاح بعض الاختلالات الوراثية.", "5. المعالجة بالمورثات (الجينات): وتهدف إلى استبدال الجين الذي يعاني من قصور في وظيفته وذلك لتخفيف أعراض المرض المسؤول عنه الجين الأصلي (راجع الجزء 5.5.7)."]}, {"id": "c5p210s1", "page": 210, "title": "5–4–11–6. الاستشارات الوراثية (Genetic counsellings)", "paragraphs": ["هي تحليل للمصير الوراثي في العائلة وتقديم الاختيارات الممكنة لتجنب الخطورة المحتملة. يقوم المستشار الوراثي المختص بحساب خطر تكرار الاختلالات الوراثية في العوائل من خلال تطبيقه لقوانين الوراثة وعلى ضوء ذلك يقوم بتوجيه الآباء حول المشكلات التي قد يتعرض لها أولادهم وما يتخذونه من اختيارات.", "أما بالنسبة للأمراض التي تتأثر بعوامل وراثية وبيئية معاً فيمكن للمستشار تقديم النصح للعائلة حول كيفية خفض عوامل الإصابة المحتملة.", "الحالات التي يمكن الاستشارة فيها:", "1. معرفة مدى إصابة بعض أفراد العائلة بأحد الأمراض الوراثية.", "2. معرفة ما يؤول إليه زواج أبناء العمومة من أمراض وراثية محتملة.", "3. معرفة سبب عدم انتظام التكوين الجنسي أو تأخر النضج الجنسي.", "4. تقديم الاستشارة في حالة الإجهاضات المتكررة.", "5. في حالة الرغبة في تعيين الأبوة.", "6. في حالة الرغبة بمعرفة مخاطر الأدوية والإشعاع."]}, {"id": "c5p210s2", "page": 210, "title": "5–4–11–7. الجينوم البشري (Human Genome)", "paragraphs": ["بعد نصف قرن من اكتشاف تركيب الـ DNA توصل علماء الوراثة إلى معرفة التتابع الجيني للجينوم البشري والذي يضم ترتيب نحو 3.3 مليار من أزواج القواعد النتروجينية في كروموسومات الإنسان.", "ويتطلع العلماء نحو معرفة المعلومات التي يحددها تتابع نيوكليوتيدات الـ DNA بصورة فعالة، وذلك من خلال تطوير حقلاً جديداً ومهماً من حقول علم الحياة ألا وهو المعلوماتية الأحيائية (Bioinformatics) الذي يسعى نحو برمجة الحاسوب للمساعدة في تحليل وتفسير معظم تتابعات نيوكليوتيدات الـ DNA وتوقع أماكن وجود الجينات والوظائف التي تتحكم بها وكذلك المقارنة بين تتابعات نيوكليوتيدات الـ DNA المختلفة."]}]}, {"id": "5", "title": "الوراثة الجزيئية", "code": "5–6", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p211s0", "page": 211, "title": "5–5. الأساس الجزيئي للوراثة", "paragraphs": ["لقد استنتج مندل من خلال دراسته للعديد من الصفات في نبات البزاليا بأن هناك عوامل وراثية تتحكم بنقل الصفات في الكائن الحي ولكن ما هي تلك العوامل وكيفية خزنها للمعلومات الوراثية وقابليتها على حل المعلومات الغامضة بقيت لغزاً محيراً للعلماء، ولقد تم فيما بعد من خلال البحوث والدراسات إزاحة الستار عن بعض جوانب ذلك اللغز على أثر إصرار العلماء لإيجاد صيغة حل لمشكلة تفشي أحد أمراض الجهاز التنفسي في المجتمع وذلك في عام (1928م)."]}, {"id": "c5p211s1", "page": 211, "title": "5–5–1. الكشف عن الحامض النووي DNA", "paragraphs": ["لقد استدل العلماء على ثلاث دراسات تثبت بأن الـ DNA هو المادة الوراثية:", "1. تجارب كريفيث على البكتيريا حيث بيّنت بأن هناك عاملاً وراثياً كان معنياً بالتحول (Transformation)، حيث استطاع من نقل قابلية القتل بين أنواع من الخلايا البكتيرية.", "2. تجارب أفري (Avery)، لقد بينت هذه التجارب بأن الـ DNA وليس البروتين هو المسؤول عن التحول في البكتيريا.", "3. تجارب هيرشي وجيس (Hershey and Chase)، لقد أجرى هذان الباحثان عام (1952م) اختباراً وذلك لمعرفة ما إذا كان الـ DNA أم البروتين هو المادة الوراثية التي تنقلها الرواشح أو ملتهمة الجراثيم (بلعم البكتيريا) (Bacteriophages)، يمكن توضيح هذه التجربة (بالشكل 5–35) كما يمكن اختصارها بثلاث خطوات:", "تم استخدام نظائر مشعة وذلك لتمييز الـ DNA عن البروتين في الراشح، فالفوسفور المشع P³² استخدم للـ DNA بينما الكبريت المشع S³⁵ استخدم للبروتين. بعدها ترك الباحثان كل من الرواشح التي تحتوي على الفوسفور المشع وتلك التي تحتوي على الكبريت المشع كل على انفراد لتصيب بكتيريا القولون (Escherischia coli).", "تم إزالة أغلفة الرواشح عن الخلايا بوساطة خلاط معين.", "فصلت الرواشح عن البكتيريا باستخدام آلة الطرد المركزي (Centrifuge). لقد كانت النتيجة بأن جميع DNA الرواشح والقليل من البروتين قد دخلا إلى البكتيريا. وبناء على ذلك فقد تم الاستنتاج بأن جزء الراشح الذي أصاب الخلية البكتيرية وتضاعف فيها هو حامضه النووي وليس بروتينه."]}, {"id": "c5p212s0", "page": 212, "title": "5–5–2. تركيب الـ DNA", "paragraphs": ["لغاية عام (1953م) كان علماء الحياة يؤيدون فكرة كون أن الـ DNA هو المادة الوراثية ولكنهم قبل ذلك الوقت كانوا يجهلون تركيبه. عندئذ توصل العالمان واطسن (Watson) وكريك (Crick) إلى وضع نموذج لتركيبه، حيث إنه مركب بصورة مبسطة من سلسلتين متعاكستين (Antiparallelism) تلتف أحدهما حول الأخرى على شكل حلزون مزدوج وترتبط القواعد النتروجينية لإحدى السلسلتين مع القواعد ذات العلاقة (المتممة) في السلسلة المقابلة بوساطة أواصر هيدروجينية، كما ترتبط حلقات السكر ومجاميع الفوسفات في كل من السلسلتين بأواصر تساهمية، شكل (5–36).", "الشكل (5–36) يبين اتجاه سلسلتي الـ DNA. إن التعاكس في هاتين السلسلتين يرجع إلى اتجاه سكر الرايبوز منقوص الأوكسجين. لاحظ أن نصف الحلزون المزدوج يتجه من 5 إلى ذرة الكاربون رقم 3 بينما يتجه النصف الآخر بالعكس (للاطلاع)."], "sourceFigure": "assets/figures/dna-book.webp", "figurePage": 212}, {"id": "c5p213s0", "page": 213, "title": "الحامض النووي DNA ووحداته البنائية", "paragraphs": ["يعتبر الحامض النووي الرايبوزي منقوص الأوكسجين (DNA، Deoxyribonucleic acid) مركب كيميائي معقد التركيب، يوجد في جميع الأحياء ويعتبر ذا أهمية كبيرة لها. ويوجد بصورة رئيسية في النواة ضمن الكروموسومات التي تنشأ من الشبكة الكروماتينية، ومادة الكروماتين تتشكل من وحدات من النيوكليوسوم (Nucleosome)، والتي تتركب بدورها من أربع جزيئات هستونية توجد كل منها بحالة مزدوجة علماً بأن جزيء الـ DNA يحتضن هذا التركيب، شكل (5–37أ).", "يوجد الـ DNA أيضاً في بعض العضيات السايتوبلازمية كالمايتوكوندريا والبلاستيدات.", "تعد جزيئات هذا الحامض أكبر الجزيئات الحياتية المعروفة، فكما أن السكريات المتعددة مؤلفة من عدد من الوحدات أو الجزيئات الصغيرة وهي السكريات الأحادية، وأن البروتينات مؤلفة من عدد من الوحدات أو الجزيئات الأصغر وهي الأحماض الأمينية، فإن الأحماض النووية مؤلفة من عدد كبير من الوحدات البنائية المتكررة تعرف بالنيوكليوتيدات (Nucleotides). يتألف كل نيوكليوتيد من ثلاث جزيئات أبسط مرتبطة ببعضها بصورة مباشرة (شكل 5–37ب) وهي من الخارج إلى الداخل كالآتي:"]}, {"id": "c5p214s0", "page": 214, "title": "مكونات النيوكليوتيد", "paragraphs": ["1. سكر خماسي الكاربون والمسمى بالرايبوز منقوص الأوكسجين (Deoxyribose)، والذي صيغته الجزيئية (C₅H₁₀O₄).", "2. مجموعة فوسفاتية: وتتكون من ذرة فسفور (P) مرتبطة بأربع ذرات أوكسجين (O). وتشكل الجزيئات المتعاقبة للفسفات والسكر جانبي سلسلة الـ DNA إذ ترتبط النيوكليوتيدات الموجودة على طول كل سلسلة بروابط تساهمية (Covalent Bonds) تجمع بين سكر أحد النيوكليوتيدات والمجموعة الفوسفاتية للنيوكليوتيد المجاور. والرابطة التساهمية هي اتحاد ذرتين نتيجة مساهمة كل منهما بالإلكترون. إن السكر والفوسفات يكونان متطابقين في كل نيوكليوتيد.", "3. قاعدة نتروجينية (Nitrogenous Base) وهي مركب حلقي يحتوي على النتروجين بالإضافة إلى الكاربون والهيدروجين والأوكسجين عدا الأدنين لا يحتوي على الأوكسجين. تعتبر المسافة بين كل قاعدة والأخرى المجاورة لها ثابتة (3.4 أنكستروم). ويوجد منها نوعان، شكل (5–38)."]}, {"id": "c5p214s1", "page": 214, "title": "أنواع القواعد النتروجينية", "paragraphs": ["أ. البيريميدينات (Pyrimidines) وتشمل القواعد الأحادية الآتية:", "1. الثايمين (Thymine، T) ويوجد في الـ DNA فقط.", "2. السايتوسين (Cytosine، C) ويوجد في كلا الحامضين.", "3. اليوراسيل (Uracil، U) يوجد في الـ RNA فقط.", "ب. البيورينات (Purines) وتشمل القاعدتين:", "1. الأدنين (Adenine، A).", "2. الكوانين (Guanine، G).", "يوجدان في كل من الحامضين DNA وRNA."]}, {"id": "c5p215s0", "page": 215, "title": "أزواج القواعد المتممة (Complementary base pairs)", "paragraphs": ["إن ارتباط القواعد بين السلسلتين لا يكون عشوائياً، بل مقيداً، فالأدنين في إحدى السلسلتين يرتبط دائماً مع الثايمين في السلسلة الأخرى بآصرتين هيدروجينيتين ويرتبط السايتوسين في إحدى السلسلتين مع الكوانين في السلسلة الأخرى بثلاث أواصر هيدروجينية (Hydrogen Bonds).", "مع العلم أنه تم التوصل عام (1949م) من قبل العالم شارغاف بأن النسبة المئوية للأدنين تساوي النسبة المئوية للثايمين، كما أن النسبة المئوية للكوانين تساوي النسبة المئوية للسايتوسين في الـ DNA لمجموعة متنوعة من الكائنات الحية وتسمى أزواج القواعد هذه بأزواج القواعد المتممة (Complementary base pairs). أي أن ترتيب القواعد في سلسلة واحدة من جزيء الـ DNA أو الـ RNA يكون متمماً لتركيب القواعد في السلسلة المقابلة. مثلاً إذا كانت سلسلة DNA ذات الترتيب AGAC فإن السلسلة المقابلة يجب أن تكون بالتتابع المتمم TCTG.", "إن أزواج القواعد المتممة ذات أهمية كبيرة في تركيب ووظيفة الـ DNA وذلك لسببين:", "1. لأن الأواصر بين أزواج القواعد تساعد على تماسك سلسلتي الـ DNA.", "2. لأن الطبيعة المتكاملة للـ DNA تساهم في تفسير كيفية تضاعفه قبل عملية انقسام الخلية.", "مثال: إذا علمت بأن تتابع القواعد في إحدى سلسلتي الـ DNA هي: TCT GTG GAC فكيف تكون القواعد المتممة لها في السلسلة المقابلة؟ الحل: تتابع القواعد المعطاة (في السؤال) TCT GTG GAC؛ التتابع المكمل في الجواب AGA CAC CTG.", "يتضح مما سبق بأن الـ DNA يعتبر في غاية الأهمية لأنه المادة المكونة للمورثات، حيث إن تسلسل القواعد النتروجينية فيه هو الذي يحدد صفات الأحياء."], "newFigure": "assets/figures/dna-pairs-new.svg"}, {"id": "c5p215s1", "page": 215, "title": "5–5–3. تركيب الـ RNA ووظائفه", "paragraphs": ["يوجد الحامض النووي الرايبوزي (RNA، Ribonucleic acid) في النواة وفي السايتوبلازم كما هو الحال في النوية وفي الرايبوسومات وفي تراكيب أخرى. قد يكون هذا الحامض المادة الوراثية لبعض الرواشح (الفيروسات)، كما أنه يعتبر ذو أهمية كبيرة في عملية بناء البروتين بما في ذلك الأنزيمات. يشبه هذا الحامض قرينه حامض الـ DNA من حيث وحدات البناء الكيميائي إلا في جوانب محدودة يمكن إيجازها كالآتي:"]}, {"id": "c5p216s0", "page": 216, "title": "مقارنة RNA مع DNA", "paragraphs": ["1. يحتوي الـ RNA على سكر الرايبوز C₅H₁₀O₅ بدلاً من سكر الرايبوز منقوص الأوكسجين C₅H₁₀O₄ الموجود في الـ DNA.", "2. يحتوي على القاعدة النتروجينية يوراسيل بدلاً من القاعدة ثايمين الموجودة في الـ DNA.", "3. يتكون عادة من سلسلة واحدة وليس من سلسلتين كما في الـ DNA. إلا أن بعض أجزاء الـ RNA قد تنثني ليصبح ثنائية السلسلة وفيها يرتبط اليوراسيل مع الأدنين والسايتوسين مع الكوانين.", "4. إن الـ RNA قصير (يعادل طول مورث واحد) تقريباً، في حين يعتبر الـ DNA جزيء عملاق يحتوي على المئات أو الآلاف من المورثات.", "5. يحمل الـ RNA تعليمات بناء البروتين بينما يقتصر الـ DNA على إعطاء المعلومات فقط.", "6. بإمكان الـ RNA أن يتصرف كأنزيم، بينما لا يمكن للـ DNA أن يقوم بوظيفة أنزيمية."]}, {"id": "c5p216s1", "page": 216, "title": "أنواع RNA", "paragraphs": ["سنتطرق إلى ذكر ثلاثة أنواع من الـ RNA وجميعها تصنع في نواة الخلية وتنقل إلى السايتوبلازم حيث إن لها دور في بناء البروتين وهي:", "1. mRNA المراسل (Messenger RNA): وهو جزيء ينقل رسالة وراثية من الـ DNA الموجود في النواة إلى الرايبوسومات الموجودة في السايتوبلازم وذلك في خلايا حقيقية النواة.", "2. rRNA الرايبي الرايبوسومي (Ribosomal RNA): وهو جزء من تركيب الرايبوسومات حيث يشترك مع البروتين في تكوينها.", "3. tRNA الناقل (Transfer RNA): ويقوم بنقل الأحماض الأمينية إلى الرايبوسوم لبناء البروتين. حيث لوحظ أن الأحماض الأمينية ترتبط بهذا الحامض tRNA قبل أن يوصلها إلى الرايبوسوم."]}, {"id": "c5p216s2", "page": 216, "title": "الشفرة الوراثية والـ mRNA", "paragraphs": ["الشفرة الوراثية (Genetic code): تشير إلى تتابع القواعد النتروجينية في الـ mRNA، حيث إن ثلاث نيوكليوتيدات متجاورة تمثل كودون وتحدد حامضاً أمينياً أو تشير إلى بداية (Initiation) أو إيقاف (Stop) الترجمة."]}, {"id": "c5p217s0", "page": 217, "title": "5–5–4. تضاعف الـ DNA", "paragraphs": ["إن الميزة الرئيسية للمادة الوراثية DNA هي قابليتها على التضاعف في بداية كل انقسام خلوي وذلك لضمان انتقاله إلى الخلايا الجديدة.", "خطوات التضاعف:", "1. تفصل إنزيمات الهيليكيز (Helicase) سلسلتي الـ DNA حيث تنتقل هذه الإنزيمات على طول هذا الجزيء لغرض فك الأواصر الهيدروجينية بين القواعد المتممة. تنتج عن انفصال هاتين السلسلتين منطقة تشبه شكل الحرف Y والتي يطلق عليها شوكة التضاعف (Replication fork)، شكل (5–39).", "2. تقوم إنزيمات بلمرة الـ DNA (DNA Polymerase) بإضافة نيوكليوتيدات متممة موجودة داخل النواة إلى كل من السلسلتين الأصليتين، وبالطبع تكون أواصر تساهمية بين النيوكليوتيدات الجديدة المتجاورة كما تكون الأواصر الهيدروجينية بين القواعد المتممة الموجودة على السلسلتين الأصلية والجديدة (شكل 5–39).", "لاحظ من اتجاه السهمين في هذا الشكل وعند شوكة التضاعف بأن بناء الـ DNA يكون باتجاه معاكس في كل سلسلة مما يؤدي ذلك إلى إحداث ثغرات في السلسلة التي يتم بناؤها حديثاً غير أن هذه الثغرات تربط فيما بينها بوساطة أنزيم لاحم يطلق عليه (DNA Ligase).", "3. تقوم إنزيمات بلمرة الـ DNA بإنهاء عملية التضاعف ثم تنفصل عنه وينتج عن ذلك جزيئتان منفصلتان في كل سلسلة أحدهما أصلي والآخر جديداً لذا يطلق على هذا النوع من التضاعف بالتضاعف شبه المحافظ (Semi-conservative Replication)، شكل (5–39ج).", "تتم عملية التضاعف بشكل دقيق بحيث قد تحدث طفرة واحدة لكل مليار من أزواج القواعد المتممة والسبب هو لوجود إنزيمات بلمرة الـ DNA والتي تقوم غالباً بترميم الخطأ."], "sourceFigure": "assets/figures/replication-book.webp", "figurePage": 218}, {"id": "c5p218s0", "page": 218, "title": "5–5–5. الحامض DNA وقابليته على نسخ الـ RNA", "paragraphs": ["النسخ (Transcription): هي عملية بناء RNA باستخدام سلسلة واحدة من الـ DNA كقالب (Template)، شكل (5–40). ويعتبر النسخ المرحلة الأولى من عملية بناء البروتين وفيما يلي خطوات النسخ:", "1. يرتبط إنزيم المتعدد البوليمير للـ RNA (RNA Polymerase) وهو إنزيم يحفز إنتاج RNA من قالب الـ DNA في موقع الابتداء (Promoter) ويؤدي ذلك إلى حل التفاف سلسلتي الـ DNA وانفصالهما.", "2. يضيف إنزيم المتعدد البوليمير للـ RNA نيوكليوتيدات RNA الحرة إلى جانب النيوكليوتيدات الموجودة في إحدى سلسلتي الـ DNA وينتج عن ذلك سلسلة جزيء الـ RNA الجديد. وكما هو الحال في تضاعف الـ DNA إذ تحدد أزواج القواعد المتممة تتابع النيوكليوتيدات في الـ RNA الذي تم إنجازه حديثاً. على سبيل المثال إذا كان تتابع القواعد في سلسلة الـ DNA هي CAG CTA فإن تتابع القواعد في سلسلة الـ RNA سيكون كالآتي: DNA: CAG CTA؛ RNA: GUC GAU.", "موقع الابتداء (Promoter): هو تسلسل أساسي معين من النيوكليوتيدات يوجد قرب بداية المورث ويمتلك وظيفة متخصصة بوساطة إنزيم بلمرة الـ RNA وذلك لغرض البدء بعملية النسخ."]}, {"id": "c5p219s0", "page": 219, "title": "نسخ RNA — تتمة", "paragraphs": ["وبعد مغادرة إنزيم بلمرة الـ RNA منطقة المورث الذي تم استنساخه تلتف سلسلتا الـ DNA من جديد.", "3. بعد وصول إنزيم بلمرة الـ RNA إلى إشارة انتهاء فإنه يحرر RNA جديد بمختلف أنواعه. يمكن للـ RNA الناتج أن يقوم بوظيفته في الخلية (شكل 5–40). أما بالنسبة للأنزيم فبإمكانه أن ينسخ مورثاً آخر.", "شكل (5–40) يبين الخطوات من المورثات إلى تكوين الأحماض الأمينية. (أ) النسخ يبين أن شريط DNA يكون غير ملفوف. (ب) يبين أن كل ثلاث قواعد نيوكليوتيدية تساوي شفرة واحدة (Codon)، وكل كودون يستدعي حامض أميني واحد في سلسلة عديد الببتيد (للاطلاع)."]}, {"id": "c5p219s1", "page": 219, "title": "5–5–6. ترجمة الـ DNA لبناء البروتين", "paragraphs": ["تعتبر الترجمة (Translation) الخطوة الأخيرة في عملية بناء البروتينات وتحدث في الرايبوسومات ويتخللها استخدام الشفرات (Codons) في جزيئات الـ mRNA لتحديد تتابع الأحماض الأمينية في سلسلة متعدد الببتيد وتتضمن ثلاث خطوات رئيسية:"]}, {"id": "c5p220s0", "page": 220, "title": "أطوار الترجمة", "paragraphs": ["1. طور البدء (Initiation): يرتبط الـ tRNA مع mRNA والوحدتين البنائيتين للرايبوسوم بعضها مع البعض الآخر. وترتبط جزيئات معينة لحامض أميني ميثيونين عند إحدى طرفي الـ tRNA وذلك وفقاً لكودون البدء AUG في الـ mRNA والذي يزدوج بالكودون المضاد UAC في الطرف الآخر للـ tRNA، شكل (5–41). يعتبر الميثيونين الحامض الأميني الأول في جميع عديد الببتيد تقريباً غير أنه قد يزال لاحقاً.", "2. طور الاستطالة (Elongation): وفي هذا الطور يتم تشكيل سلسلة عديد الببتيد، إذ يزدوج الكودون المضاد في tRNA الذي يحمل الحامض الأميني المناسب مع الكودون الثاني في mRNA. يلي ذلك انفصال الميثيونين عن الـ tRNA الأول بفعل الرايبوسوم، ثم تتشكل آصرة ببتيدية بين الميثيونين والحامض الأميني الثاني، كذلك يغادر tRNA الأول الرايبوسوم ويتقدم الآخر (الرايبوسوم) على طول جزيء mRNA لمسافة كودون واحد.", "3. طور الانتهاء (Termination): عند وصول الرايبوسوم إلى كودون إيقاف (مثل UAA أو UAG أو UGA) على الـ mRNA فيؤدي ذلك إلى انفصال سلسلة عديد الببتيد المكونة عن آخر tRNA وحدوث تحرر في السايتوبلازم مع مغادرة آخر tRNA للرايبوسوم، كما تنفصل الوحدتان البنائيتان للرايبوسوم عن بعضهما ويبتعد الرايبوسوم عن mRNA.", "يتكون الرايبوسوم من وحدتين إحداهما صغيرة والأخرى كبيرة وتحتوي كل منهما على حامض RNA وبروتين وتحتوي مواقع لارتباط كل من الحامض mRNA وسلسلة عديد الببتيد الجديدة وكذلك أماكن لرسو جزيئات tRNA."]}]}, {"id": "6", "title": "الهندسة الوراثية", "code": "5–7", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p221s0", "page": 221, "title": "متعدد الرايبوسومات (Polysome)", "paragraphs": ["إن ترجمة الـ mRNA لا تتم إلا بعد انتهاء عملية النسخ السالفة الذكر وذلك في الكائنات الحقيقية النواة. أما في الكائنات البدائية النواة والتي لا تمتلك غلاف نووي يفصل حامضها النووي DNA عن الرايبوسومات الموجودة في السايتوبلازم فيمكن أن تبدأ الترجمة قبل انتهاء النسخ.", "بما أن رايبوسوماً جديداً يباشر ترجمة الـ mRNA وذلك حال تقدمه السابق، لذلك يمكن لعدة رايبوسومات أن تترجم نفس النسخة من mRNA ويطلق على هذا النوع من الترجمة اسم متعدد الرايبوسومات (Polysome)."]}, {"id": "c5p221s1", "page": 221, "title": "تركيب ووظيفة البروتين", "paragraphs": ["لشكل البروتين تأثير كبير على الوظيفة التي يقوم بها. فكل بروتين يتكون من عديد ببتيدات واحد أو أكثر والتي هي سلاسل من الأحماض الأمينية وترتبط بروابط ببتيدية. يوجد في بروتينات الكائنات الحية (20) حامضاً أمينياً مختلفاً. إن سلسلة عديد الببتيد مكونة من المئات بل الآلاف من الأحماض الأمينية العشرين المختلفة والمرتبة وفق تتابع خاص يعطي التركيب الثلاثي الأبعاد للبروتين."]}, {"id": "c5p221s2", "page": 221, "title": "5–5–7. الهندسة الوراثية (Genetic Engineering)", "paragraphs": ["هي تقنية لتغيير التركيب الوراثي للخلايا الحية أو الأفراد من خلال إزالة بعض الجينات أو تهجين جزيئات DNA جديدة منها أو تحويرها بغية تمكين الخلية أو الكائن من اكتساب الصفة المرغوبة وفيما يلي المستلزمات الأساسية لتقنية الهندسة الوراثية:", "1. طريقة لتقطيع جزيئات الـ DNA الذي يحمل المورث المراد نقله وذلك بوساطة إحدى الإنزيمات القاطعة (Restriction Enzymes).", "2. ناقل مناسب يحمل القطعة الجديدة من الـ DNA ويتم ذلك من خلال اتحادها مع DNA الناقل بمساعدة إنزيم لاحم (DNA Ligase) بحيث تمتاز القطعة المهجنة (rDNA) بقابليتها على التضاعف داخل خلية المضيف.", "3. وسيلة لإدخال القطعة المهجنة (rDNA) (وبضمنها القطعة الحاملة للمورث المراد نقله) إلى خلية المضيف.", "4. طريقة للكشف عن خلية المضيف وأجيالها الحاملة للقطعة المهجنة المرغوبة وعزلها عن بقية أفراد المستعمرة أو العشيرة والتي لا تحتوي على تلك القطعة.", "الأنزيم اللاحم: هو الأنزيم الذي يحفز تكوين الأواصر التساهمية (Covalent bonds) في الهيكل السكري الفوسفاتي للحامض النووي.", "rDNA: هو حامض DNA مستنسخ من الحامض RNA بعمل إنزيم المستنسخ العكسي ويطلق عادة على جزيئات الـ DNA المستحدث خارج جسم الكائن الحي وذلك من خلال ربط جزيئات الـ DNA لكائنين مختلفين."]}, {"id": "c5p222s0", "page": 222, "title": "الإنزيمات القاطعة (Restriction Enzymes)", "paragraphs": ["هي بروتينات بكتيرية تستخدم للتعرف على تتابعات معينة من القواعد النتروجينية لجزيء الـ DNA وتقطعها (شكل 5–42)، كما تعمل هذه الإنزيمات على كسر الآصرة الفوسفاتية الداخلية للـ DNA.", "الشكل (5–42) يبين فعل الإنزيم القاطع Eco RI، إذ يتعرف على التتابع السداسي GAATTC الموجودة في شريطي الـ DNA المتكاملين ويقطع كل تتابع بين القاعدتين G، A والموضح باللون الأحمر (للاطلاع)."]}, {"id": "c5p222s1", "page": 222, "title": "النواقل — البلعم البكتيري والبلازميد", "paragraphs": ["للنواقل دور رئيسي في هذه التقنية ومن أهمها ما يأتي:", "أولاً: البلعم البكتيري (العاثي أو اللاقم): العاثيات (Phages)، وهي أشباه بسيطة التركيب تصيب البكتيريا وتحللها أو تبقى خاملة. تحتوي على أشرطة DNA مزدوجة أو مفردة وقد تحتوي على RNA مفرد. مثال على ذلك التبغ موزائيك.", "ثانياً: البلازميد (Plasmid): وهو جزيء دائري صغير من الـ DNA الإضافي الذي يوجد في العديد من البكتيريا (شكل 5–43) ومن أهم ميزاته ما يأتي:"]}, {"id": "c5p223s0", "page": 223, "title": "ميزات البلازميد", "paragraphs": ["يحمل عدد قليل من الجينات المسؤولة عن بعض الصفات كصفة مقاومة البكتيريا للمضادات الحياتية.", "يتضاعف ذاتياً وبصورة مستقلة عن كروموسوم البكتيريا.", "يمكن نقله من بكتيريا إلى أخرى وللعديد من الكائنات كالفطائر والفقريات والحشرات."]}, {"id": "c5p223s1", "page": 223, "title": "المجس (المسبار) (Probe) والكشف عن الجين المرغوب", "paragraphs": ["المجس هو جزيئة DNA أو RNA أحادية السلسلة ومعلمة بنظير الفسفور المشع وبإمكانه لتتابع DNA المرغوب والمطلوب الكشف عنه تكملته. ونتيجة لارتباط المجس مع قطعة الـ DNA المكملة سيكون حلزون مزدوج مشع. وبالنسبة لجين الأنسولين المعطى في (شكل 5–43) يعتبر المجس تتابع الـ RNA لهذا الجين، وعادة يقوم المختصون بنقل DNA من البكتيريا معادة التركيب إلى ورق ترشيح وذلك لغرض معرفة فيما إذا كانت تلك البكتيريا تحتوي على الجين المرغوب، وعند النظر إلى تلك البكتيريا وهي تحت الأشعة فوق البنفسجية أو عند تعريضها لفيلم فوتوغرافي فإن الخلايا المستنسلة (Clones) التي تحمل الـ DNA المرغوب والمعلم بالمجس المختص به ستصبح مضاءة وبراقة.", "الشكل (5–43) يبين إمكانية جعل خلايا البكتيريا لإنتاج أنسولين الإنسان عن طريق إكسابها بلازميد معاد التركيب (للاطلاع)."], "sourceFigure": "assets/figures/engineering-book.webp", "figurePage": 223}, {"id": "c5p224s0", "page": 224, "title": "5–5–7–1. التطبيقات الوراثية", "paragraphs": ["1. تحديد تتابع نيوكليوتيدات الجينوم البشري الكامل لمعرفة الخارطة الوراثية.", "2. استخدامها في الميدان القضائي.", "3. استخدامها في مجال تعقب هجرة الإنسان وبعض الكائنات الأخرى من بيئاتها ولاسيما تلك المهددة بالانقراض.", "4. إنتاج هورمون الأنسولين البشري ومادة الأنترفيرون البروتينية وعامل التخثر رقم (8) وبروتينات الدم واللقاحات المختلفة.", "5. نقل صفة تثبيت النتروجين إلى أنواع أخرى من البكتيريا.", "6. نقل صفة تكوين العقد الجذرية في البقوليات إلى محاصيل أخرى مهمة اقتصادياً.", "7. تطوير أبحاث استخدام البكتيريا في مجال البحث عن نواحي وتنقية وتركيز المعادن في التربة.", "8. تطوير مقدرة الكائنات المجهرية في الحد من بعض مخاطر التلوث.", "9. تطبيق أنظمة الانتخاب في تزاوج سلالات الأبقار والأغنام والخيول والدواجن والأسماك وغيرها.", "10. تطبيق مفاهيم الوراثة كالانتخاب الاصطناعي والتهجين والتوالد المنظم وذلك لإنتاج نباتات نافعة للإنسان بكميات وفيرة، وكذلك استغلال ظاهرة التوائم في الأبقار والأغنام لإنتاج حيوانات نافعة."]}]}, {"id": "7", "title": "أسئلة الفصل الخامس", "code": "5–8", "hint": "نص الكتاب · الفصل الخامس", "nodes": [{"id": "c5p225s0", "page": 225, "title": "أسئلة الفصل الخامس — س1 إلى س4", "paragraphs": ["س1/ عرف كلاً مما يأتي: علم الوراثة، التهجين الأحادي، الهجين، قانون مندل الأول، الإنزيمات القاطعة، المجس، rDNA، الجينات المميتة.", "س2/ عدد السمات التي اتصف بها العالم مندل والتي جعلته رائداً في علم الوراثة؟", "س3/ عدد بعض العلماء الذين ساهموا في تقدم علم الوراثة مع الإشارة إلى أهم إنجازاتهم؟", "س4/ ما المقصود بالطراز المظهري والطراز الوراثي مع إعطاء مثال؟"]}, {"id": "c5p225s1", "page": 225, "title": "أسئلة الفصل الخامس — س5 إلى س8", "paragraphs": ["س5/ ضرب نبات بزاليا أحمر الأزهار بآخر أبيض الأزهار فكانت جميع النباتات الناتجة حمراء الأزهار ولو أجري تلقيح لأحد أفراد الجيل الأول مع أحد الأبوين فما هي الطراز الوراثية والمظهرية لأفراد الجيل الثاني وما نوع التضريب في هذه الحالة؟", "س6/ ضرب خنزير غيني خشن الشعر أسود اللون بأنثى خشنة الشعر بيضاء اللون فأنجبا عدد من الولادات موزعة كالآتي: 3/8 خشن أسود، 3/8 خشن أبيض، 1/8 ناعم أسود، 1/8 ناعم أبيض، فما هي الطرز الوراثية للأبوين والأفراد الناتجة؟ علماً أن صفتي خشونة الشعر واللون الأسود سائدتان.", "س7/ في الفئران الصفراء (Yy) يكون الأليل (Y) مميتاً، وعند إجراء تزاوج داخلي بينها تموت جميع الأفراد الصفر النقية. بيّن النسبة المظهرية لجميع الأفراد الأحياء فقط.", "س8/ أجري تزاوج بين كلاب مكسيكية ذات شعر اعتيادي بأخرى عديمة الشعر فكان نصف أفراد الجيل الأول ذات شعر اعتيادي والنصف الآخر عديمة الشعر وعند إجراء تزاوج بين كلاب عديمة الشعر كان أفراد الجيل الناتج بالنسب المظهرية الآتية: 1/4 شعر اعتيادي:1/2 عديمة الشعر:1/4 عديمة الشعر ميتة. المطلوب تفسير هذه النتيجة مع إجراء التضريبات اللازمة."]}, {"id": "c5p226s0", "page": 226, "title": "أسئلة الفصل الخامس — س9 إلى س12", "paragraphs": ["س9/ عدد ميزات أو خصائص الأحياء المستخدمة في تجارب الوراثة؟", "س10/ ما الطرز المظهرية والوراثية لمجاميع الدم لذرية (أبناء) كل من الزوجين الآتيين: أ. IᴬIᴮ × Iᴮi. ب. Iᴮi × Iᴮi. ج. رجل A هجين × امرأة B. د. رجل Rh⁻ × امرأة Rh⁻ سليمين.", "س11/ تزوج رجل فصيلة دمه A من امرأة فصيلة دمها B والعامل الريسي Rh لكل منهما موجب فأنجبا طفلين أحدهما فصيلة O سالبة والآخر فصيلة A موجبة فما هي الطرز الوراثية للأبوين والأبناء.", "س12/ في أي الحالتين تكون حياة الجنين مهددة بالخطر موضحاً السبب عندما يكون الجنين Rh⁺؟ أ. عندما يكون الرجل Rh⁺ والمرأة Rh⁻. ب. Iᴮi × Iᴮi. ج. عندما يكون الرجل Rh⁻ والمرأة Rh⁺. د. رجل Rh⁻ × امرأة Rh⁻."]}, {"id": "c5p227s0", "page": 227, "title": "أسئلة الفصل الخامس — س13 إلى س19", "paragraphs": ["س13/ اذكر باختصار أسباب فشل عمليات نقل الدم في بعض الحالات؟", "س14/ فسر (علل) ما يأتي: 1. يوصف الأفراد ذو مجموعة الدم O بأنهم واهبون عامون. 2. عند تضريب ديك زاحف مع دجاجة زاحفة كان ربع الناتج ميت. 3. ظهور أفراد غبارية عند تضريب أنثى ماشية قصيرة القرون حمراء الشعر مع ذكر أبيض الشعر. 4. اعتبار متلازمة داون طفرة كروموسومية.", "س15/ لديك نبات طويل الساق كيف يمكنك التأكد من نقاوة هذه الصفة السائدة فيه؟", "س16/ هل بالإمكان ولماذا؟ 1. إنجاب طفل يحمل فصيلة O من أم فصيلة B وأب فصيلة AB. 2. نقل الدم من أي شخص إلى شخص آخر يحمل نفس المجموعة الدموية. 3. إيجاد عدد غير محدود من الحليلات لكل مورثة.", "س17/ اذكر المعضلات التي يواجهها الباحث عند إجراء دراساته الوراثية على الإنسان؟", "س18/ عدد الخطوات التي تتضمنها تقنية الهندسة الوراثية.", "س19/ هل تتأثر وظيفة بعض المورثات بالظروف البيئية؟ وضح ذلك بمثال."]}, {"id": "c5p228s0", "page": 228, "title": "أسئلة الفصل الخامس — س20 إلى س22", "paragraphs": ["س20/ ما العلاقة بين البلازميد والـ rDNA؟", "س21/ تمثل الرموز الآتية تتابع النيوكليوتيدات في جزيئة الـ DNA: TAC GGT CTC AGC. 1. ما تتابع نسخة الـ mRNA الناتجة من التتابع أعلاه؟ 2. ما هي الكودونات المضادة في tRNA التي ترتبط بنسخة الـ mRNA أعلاه؟", "س22/ يعتبر المسبار Probe سلسلة DNA أو RNA أحادية ثم تمييزها بمادة مشعة أو بصبغ فلوريسنت، كيف يستخدمه علماء الوراثة لتحديد موقع rDNA؟"]}, {"id": "c5p228s1", "page": 228, "title": "أسئلة الفصل الخامس — س23: اختر الجواب الصحيح", "paragraphs": ["1. الوحدة البنائية الأساسية في الـ DNA هي: أ. السكر. ب. النيوكليوتيدة. ج. الفوسفات. د. الآصرة الهيدروجينية.", "2. يعتبر الـ DNA مسؤول عن: أ. توجيه RNA لبناء الدهون. ب. توجيه RNA لإنتاج الكلوكوز. ج. تحديد المعلومات لبناء البروتين. د. تغيير الشفرة الوراثية.", "3. أين يوجد الـ RNA؟ أ. في البروتينات فقط. ب. في النواة فقط. ج. في السايتوبلازم فقط. د. في السايتوبلازم والنواة.", "4. أي الأحماض النووية الآتية تسهم في عملية الترجمة؟ أ. DNA فقط. ب. mRNA فقط. ج. RNA وDNA. د. mRNA وtRNA.", "5. ماذا يسمى البلازميد البكتيري بعد إدخال DNA من واهب إلى DNA البكتيريا؟ أ. DNA الناقل. ب. DNA المستنسخ. ج. DNA البلازميدي. د. DNA معاد التركيب."]}]}];
const QUESTIONS=[{"id": "c1-b0", "type": "blank", "prompt": "هو أول شخص استخدم كلمة خلية .......... .", "terms": ["روبرت هوك"], "answer": "ب. توصل العالم الإنكليزي روبرت هوك (Robert Hooke 1635–1703) إلى نفس ملاحظات ليفنهوك، وهو أول شخص استخدم كلمة خلية (Cell) بعد أن قام بفحص تركيب قشرة شجر البلوط، ووصف الوحدات الفلينية في نسيج الفلين (شكل 1–1)، وعرف الخلية بأنها ردهة هوائية تشبه تجويف خلية شمع العسل.", "page": 7, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c0", "type": "choice", "prompt": "هو أول شخص استخدم كلمة خلية؟", "options": ["روبرت هوك", "روبرت براون", "ثيودور شوان", "ماثياس شلايدن"], "correctIndex": 0, "answer": "ب. توصل العالم الإنكليزي روبرت هوك (Robert Hooke 1635–1703) إلى نفس ملاحظات ليفنهوك، وهو أول شخص استخدم كلمة خلية (Cell) بعد أن قام بفحص تركيب قشرة شجر البلوط، ووصف الوحدات الفلينية في نسيج الفلين (شكل 1–1)، وعرف الخلية بأنها ردهة هوائية تشبه تجويف خلية شمع العسل.", "page": 7, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b1", "type": "blank", "prompt": "يطلق على جهاز كولجي في الخلية النباتية اسم .......... .", "terms": ["الدكتوسوم"], "answer": "يطلق على جهاز كولجي في الخلية النباتية اسم الدكتوسوم (Dictyosome)، وهو يقوم ببناء السيليلوز وبعض مكونات الجدار الخلوي في الخلية النباتية.", "page": 17, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c1", "type": "choice", "prompt": "يطلق على جهاز كولجي في الخلية النباتية اسم؟", "options": ["الكرانوم", "الدكتوسوم", "القطعة المركزية", "البلازم النووي"], "correctIndex": 1, "answer": "يطلق على جهاز كولجي في الخلية النباتية اسم الدكتوسوم (Dictyosome)، وهو يقوم ببناء السيليلوز وبعض مكونات الجدار الخلوي في الخلية النباتية.", "page": 17, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b2", "type": "blank", "prompt": "تعرف انثناءات الطبقة الداخلية لغشاء المايتوكوندريا باسم .......... .", "terms": ["الأعراف"], "answer": "المايتوكوندريا تراكيب كروية أو خيطية عرضها (0.5–1) مايكرومتر وطولها قد يصل (10) مايكرومتر ويختلف توزيعها ضمن الخلايا المختلفة. توجد المايتوكوندريا في جميع الخلايا حقيقية النواة، وهي تتباين في حجمها بحسب الخلايا التي توجد فيها. تحاط المايتوكوندريا بغشاء مزدوج (ثنائي الطبقات)، والطبقة الداخلية منه تظهر عدة انثناءات وانطواءات تتخذ أشكالاً واتجاهات مختلفة، وتعرف هذه التراكيب بالأعراف (Cristae) وهي تزيد المساحة السطحية للطبقة الداخلية لغشاء المايتوكوندريا (شكل 1–10).", "page": 17, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c2", "type": "choice", "prompt": "تعرف انثناءات الطبقة الداخلية لغشاء المايتوكوندريا باسم؟", "options": ["الكرانا", "النوية", "الأعراف", "الصهاريج"], "correctIndex": 2, "answer": "المايتوكوندريا تراكيب كروية أو خيطية عرضها (0.5–1) مايكرومتر وطولها قد يصل (10) مايكرومتر ويختلف توزيعها ضمن الخلايا المختلفة. توجد المايتوكوندريا في جميع الخلايا حقيقية النواة، وهي تتباين في حجمها بحسب الخلايا التي توجد فيها. تحاط المايتوكوندريا بغشاء مزدوج (ثنائي الطبقات)، والطبقة الداخلية منه تظهر عدة انثناءات وانطواءات تتخذ أشكالاً واتجاهات مختلفة، وتعرف هذه التراكيب بالأعراف (Cristae) وهي تزيد المساحة السطحية للطبقة الداخلية لغشاء المايتوكوندريا (شكل 1–10).", "page": 17, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b3", "type": "blank", "prompt": "المادة السائلة الشفافة التي تملأ الفسحة الداخلية للبلاستيدة هي .......... .", "terms": ["السدى"], "answer": "تحاط البلاستيدة الخضراء بغشاء مزدوج، ويوجد داخل الغشاء تركيبان مهمان هما البذيرة أو الكرانوم (Granum) وجمعها كرانا (Grana)، والسدى أو الحشوة (Stroma) (شكل 1–11)، السدى هو المادة السائلة الشفافة التي تملأ الفسحة الداخلية للبلاستيدة، وتحوي داخلها الكرانا التي تحوي الكلوروفيل.", "page": 18, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c3", "type": "choice", "prompt": "المادة السائلة الشفافة التي تملأ الفسحة الداخلية للبلاستيدة هي؟", "options": ["الأعراف", "القطعة المركزية", "الرايبوسوم", "السدى"], "correctIndex": 3, "answer": "تحاط البلاستيدة الخضراء بغشاء مزدوج، ويوجد داخل الغشاء تركيبان مهمان هما البذيرة أو الكرانوم (Granum) وجمعها كرانا (Grana)، والسدى أو الحشوة (Stroma) (شكل 1–11)، السدى هو المادة السائلة الشفافة التي تملأ الفسحة الداخلية للبلاستيدة، وتحوي داخلها الكرانا التي تحوي الكلوروفيل.", "page": 18, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b4", "type": "blank", "prompt": "يمتاز سطح الشبكة البلازمية الداخلية الخشنة بوجود .......... .", "terms": ["الرايبوسومات"], "answer": "يمتاز هذا النوع من الشبكة البلازمية الداخلية بوجود الرايبوسومات على سطوح نبيباتها مما يعطيها مظهراً خشناً أو حبيبياً، ولهذا النوع دور فعال في بناء البروتينات، وهي تعمل على نقل المواد داخل الخلية، وبشكل خاص إلى أجسام كولجي، كما تعمل كشبكة هيكلية للمادة البينية السايتوبلازمية.", "page": 16, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c4", "type": "choice", "prompt": "يمتاز سطح الشبكة البلازمية الداخلية الخشنة بوجود؟", "options": ["الرايبوسومات", "البلاستيدات", "المريكزات", "الفجوات"], "correctIndex": 0, "answer": "يمتاز هذا النوع من الشبكة البلازمية الداخلية بوجود الرايبوسومات على سطوح نبيباتها مما يعطيها مظهراً خشناً أو حبيبياً، ولهذا النوع دور فعال في بناء البروتينات، وهي تعمل على نقل المواد داخل الخلية، وبشكل خاص إلى أجسام كولجي، كما تعمل كشبكة هيكلية للمادة البينية السايتوبلازمية.", "page": 16, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b5", "type": "blank", "prompt": "تتكون خيوط الأكتين من بروتين .......... .", "terms": ["الأكتين"], "answer": "هي تراكيب رقيقة ومستقيمة لوحظت لأول مرة بوضوح في الخلايا العضلية، وهي تتمثل بخيوط الأكتين المكونة من بروتين الأكتين وخيوط المايوسين وهي الأخرى مكونة من بروتين المايوسين وكلا النوعين مسؤول عن قدرة الخلية في التقلص والانبساط.", "page": 20, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c5", "type": "choice", "prompt": "تتكون خيوط الأكتين من بروتين؟", "options": ["التيوبيولين", "الأكتين", "السيليلوز", "اللكنين"], "correctIndex": 1, "answer": "هي تراكيب رقيقة ومستقيمة لوحظت لأول مرة بوضوح في الخلايا العضلية، وهي تتمثل بخيوط الأكتين المكونة من بروتين الأكتين وخيوط المايوسين وهي الأخرى مكونة من بروتين المايوسين وكلا النوعين مسؤول عن قدرة الخلية في التقلص والانبساط.", "page": 20, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b6", "type": "blank", "prompt": "تتكون النبيبات الدقيقة من بروتين يدعى .......... .", "terms": ["تيوبيولين"], "answer": "هي أكبر من الخيوط الدقيقة وتتمثل بتراكيب أنبوبية مكونة من بروتين يدعى تيوبيولين (Tubulin) وللنبيبات الدقيقة دوراً حيوياً في حركة الكروموسومات أثناء انقسام الخلية وتعد مهمة بالنسبة للهيكل الخلوي، والتنظيم وانتقال المواد، فضلاً عن كونها تكون أجزاء أساسية في تركيب الأهداب والأسواط. والنبيبات الدقيقة التي توجد في سايتوبلازم الخلايا الحيوانية عادة وفي بعض الأحياء الواطئة مثل الطحالب والفطريات، تقع بالقرب من النواة، وتشكل الجسيمات المركزية (Centrosomes).", "page": 20, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c6", "type": "choice", "prompt": "تتكون النبيبات الدقيقة من بروتين يدعى؟", "options": ["الأكتين", "المايوسين", "تيوبيولين", "الكولاجين"], "correctIndex": 2, "answer": "هي أكبر من الخيوط الدقيقة وتتمثل بتراكيب أنبوبية مكونة من بروتين يدعى تيوبيولين (Tubulin) وللنبيبات الدقيقة دوراً حيوياً في حركة الكروموسومات أثناء انقسام الخلية وتعد مهمة بالنسبة للهيكل الخلوي، والتنظيم وانتقال المواد، فضلاً عن كونها تكون أجزاء أساسية في تركيب الأهداب والأسواط. والنبيبات الدقيقة التي توجد في سايتوبلازم الخلايا الحيوانية عادة وفي بعض الأحياء الواطئة مثل الطحالب والفطريات، تقع بالقرب من النواة، وتشكل الجسيمات المركزية (Centrosomes).", "page": 20, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b7", "type": "blank", "prompt": "يتركب جدار الخلية في الخلايا الفتية من .......... .", "terms": ["السيليلوز"], "answer": "وكيميائياً يتركب جدار الخلية من مادة السيليلوز (Cellulose) في الخلايا الفتية ويتثخن بإضافة الخشبين (اللكنين – lignin) في الخلايا المتقدمة في العمر.", "page": 14, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c7", "type": "choice", "prompt": "يتركب جدار الخلية في الخلايا الفتية من؟", "options": ["المايوسين", "التيوبيولين", "الكلوروفيل", "السيليلوز"], "correctIndex": 3, "answer": "وكيميائياً يتركب جدار الخلية من مادة السيليلوز (Cellulose) في الخلايا الفتية ويتثخن بإضافة الخشبين (اللكنين – lignin) في الخلايا المتقدمة في العمر.", "page": 14, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b8", "type": "blank", "prompt": "المحلول الذي تحويه فجوات الخلايا النباتية يعرف بـ .......... .", "terms": ["العصير الخلوي"], "answer": "هي أكياس غشائية (Memberanous Sacs) توجد ضمن سايتوبلازم الخلية والفجوات في بعض الطليعيات (Protists) تكون متخصصة، فهي تمثل بفجوات متقلصة (Contractile Vacuoles) تعمل على تخليص الخلية من الماء الزائد عن الحاجة مع بعض المواد الإبرازية الذائبة كما هو الحال في الأميبا والبراميسيوم، كما توجد فجوات غذائية تتكون وقتياً من خلال إحاطة المواد الغذائية بغشاء من الكائن الحي، ويهضم الغذاء داخل هذه الفجوات من خلال أنزيمات تفرزها الجسيمات الحالة إلى داخل الفجوة. أما في الخلايا النباتية فإن الفجوات تكون أكثر وضوحاً مما في الخلايا الحيوانية، وهي صغيرة في الخلايا الفتية وواسعة في الخلايا الناضجة، وتحتوي على عصير لمواد مختلفة بصورة ذائبة يشكل محلول يعرف بالعصير الخلوي (Cell Sap).", "page": 22, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c8", "type": "choice", "prompt": "المحلول الذي تحويه فجوات الخلايا النباتية يعرف بـ؟", "options": ["العصير الخلوي", "البلازم النووي", "السائل البيني", "السايتوبلازم"], "correctIndex": 0, "answer": "هي أكياس غشائية (Memberanous Sacs) توجد ضمن سايتوبلازم الخلية والفجوات في بعض الطليعيات (Protists) تكون متخصصة، فهي تمثل بفجوات متقلصة (Contractile Vacuoles) تعمل على تخليص الخلية من الماء الزائد عن الحاجة مع بعض المواد الإبرازية الذائبة كما هو الحال في الأميبا والبراميسيوم، كما توجد فجوات غذائية تتكون وقتياً من خلال إحاطة المواد الغذائية بغشاء من الكائن الحي، ويهضم الغذاء داخل هذه الفجوات من خلال أنزيمات تفرزها الجسيمات الحالة إلى داخل الفجوة. أما في الخلايا النباتية فإن الفجوات تكون أكثر وضوحاً مما في الخلايا الحيوانية، وهي صغيرة في الخلايا الفتية وواسعة في الخلايا الناضجة، وتحتوي على عصير لمواد مختلفة بصورة ذائبة يشكل محلول يعرف بالعصير الخلوي (Cell Sap).", "page": 22, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-b9", "type": "blank", "prompt": "يتركب الغشاء البلازمي من طبقتين رقيقتين من جزيئات .......... .", "terms": ["الدهون المفسفرة"], "answer": "وهو غشاء خلوي يحيط بالسايتوبلازم في الخلايا بدائية النوى وحقيقية النوى ويتمثل بغشاء رقيق مرن ونصف ناضح وهو لا يرى بالمجهر الضوئي إلا أنه يمكن رؤيته بالمجهر الإلكتروني يتركب الغشاء البلازمي كيميائياً من طبقتين رقيقتين من جزيئات الدهون المفسفرة (Phospholipids) ذات طرف أليف (محب) للماء وطرف نافر للماء وتتخلل الطبقتين جزيئات بروتينية تسمح أو تتحكم بمرور المواد (شكل 1–7).", "page": 14, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-c9", "type": "choice", "prompt": "يتركب الغشاء البلازمي من طبقتين رقيقتين من جزيئات؟", "options": ["السيليلوز", "الدهون المفسفرة", "النشاء", "المايوسين"], "correctIndex": 1, "answer": "وهو غشاء خلوي يحيط بالسايتوبلازم في الخلايا بدائية النوى وحقيقية النوى ويتمثل بغشاء رقيق مرن ونصف ناضح وهو لا يرى بالمجهر الضوئي إلا أنه يمكن رؤيته بالمجهر الإلكتروني يتركب الغشاء البلازمي كيميائياً من طبقتين رقيقتين من جزيئات الدهون المفسفرة (Phospholipids) ذات طرف أليف (محب) للماء وطرف نافر للماء وتتخلل الطبقتين جزيئات بروتينية تسمح أو تتحكم بمرور المواد (شكل 1–7).", "page": 14, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d0", "type": "definition", "prompt": "عرّف الخلية.", "answer": "تعد الخلية الوحدة التركيبية لجميع الكائنات الحية، وبشكل عام هناك نوعين من الخلايا من حيث التركيب:", "page": 7, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d1", "type": "definition", "prompt": "عرّف الخلية بدائية النواة.", "answer": "تعد الخلية بدائية النواة أقل الخلايا تطوراً، كونها أكثرها بدائية من حيث الشكل والتركيب وتتميز بالآتي (شكل 1–4):", "page": 11, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d2", "type": "definition", "prompt": "عرّف الخلية حقيقية النواة.", "answer": "وهي الخلية التي تمتلك نواة حقيقية، وتوجد في ممالك (عوالم) الطليعيات (Protesta) والفطريات (Fungi) والنباتات (Plantae) والحيوانات (Animalia).", "page": 12, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d3", "type": "definition", "prompt": "عرّف جدار الخلية.", "answer": "يقتصر وجود جدار الخلية على الخلايا النباتية فقط وهو يتمثل بجدار خارجي سميك يحيط بمكونات الخلية ويغطي الغشاء البلازمي الذي يقع إلى الداخل منه، وجدار الخلية يحقق حماية وإسناد للغشاء البلازمي والسايتوبلازم (شكل 1–5).", "page": 13, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d4", "type": "definition", "prompt": "عرّف الغشاء البلازمي.", "answer": "وهو غشاء خلوي يحيط بالسايتوبلازم في الخلايا بدائية النوى وحقيقية النوى ويتمثل بغشاء رقيق مرن ونصف ناضح وهو لا يرى بالمجهر الضوئي إلا أنه يمكن رؤيته بالمجهر الإلكتروني يتركب الغشاء البلازمي كيميائياً من طبقتين رقيقتين من جزيئات الدهون المفسفرة (Phospholipids) ذات طرف أليف (محب) للماء وطرف نافر للماء وتتخلل الطبقتين جزيئات بروتينية تسمح أو تتحكم بمرور المواد (شكل 1–7).", "page": 14, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d5", "type": "definition", "prompt": "عرّف السايتوبلازم.", "answer": "يمثل السايتوبلازم جزء الخلية الذي يقع بين الغشاء البلازمي والنواة. وهو مادة معقدة يشكل الماء (80%) من مكوناته، والبروتينات (15%) وما تبقى (5%) يتمثل بالشحوم والسكريات وأملاح متنوعة.", "page": 15, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d6", "type": "definition", "prompt": "عرّف الجسيمات الحالة.", "answer": "هي حويصلات محاطة بغشاء أحادي الطبقة، وتحتوي أعداداً كبيرة من الأنزيمات المحللة (أكثر من 40 أنزيم) تكون مسؤولة عن عملية الهضم داخل الخلية. وتوجد الجسيمات الحالة في جميع الخلايا تقريباً وبشكل خاص الخلايا التي تتميز بقابلية البلعمة (Phagocytosis)، مثل خلايا الدم البيض العدلة (Neutrophils) (شكل 1–12).", "page": 19, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d7", "type": "definition", "prompt": "عرّف الجسيم الحركي.", "answer": "هو يشابه المريكزات (Centrioles) في تركيبه، ويتمثل بتركيب يتخذ موقعاً عند قاعدة الهدب أو السوط في الخلايا التي تحوي أهداباً أو أسواطاً وللجسيم الحركي دوراً مهماً في حركة الأهداب والأسواط ويطلق عليه أيضاً بالجسيم القاعدي (Basal Body) (شكل 1–14).", "page": 21, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d8", "type": "definition", "prompt": "عرّف الفجوات.", "answer": "هي أكياس غشائية (Memberanous Sacs) توجد ضمن سايتوبلازم الخلية والفجوات في بعض الطليعيات (Protists) تكون متخصصة، فهي تمثل بفجوات متقلصة (Contractile Vacuoles) تعمل على تخليص الخلية من الماء الزائد عن الحاجة مع بعض المواد الإبرازية الذائبة كما هو الحال في الأميبا والبراميسيوم، كما توجد فجوات غذائية تتكون وقتياً من خلال إحاطة المواد الغذائية بغشاء من الكائن الحي، ويهضم الغذاء داخل هذه الفجوات من خلال أنزيمات تفرزها الجسيمات الحالة إلى داخل الفجوة. أما في الخلايا النباتية فإن الفجوات تكون أكثر وضوحاً مما في الخلايا الحيوانية، وهي صغيرة في الخلايا الفتية وواسعة في الخلايا الناضجة، وتحتوي على عصير لمواد مختلفة بصورة ذائبة يشكل محلول يعرف بالعصير الخلوي (Cell Sap).", "page": 22, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-d9", "type": "definition", "prompt": "عرّف 2. البلازم النووي.", "answer": "هو سائل هلامي عديم اللون يملأ النواة وتتوزع فيه المحتويات النووية والمتمثلة بالنوية والشبكة الكروماتينية.", "page": 23, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p0", "type": "comparison", "prompt": "قارن بين الشبكة البلازمية الداخلية الخشنة (Rough Endoplasmic Reticulum) والشبكة البلازمية الداخلية الملساء (Smooth Endoplasmic Reticulum).", "answer": "الشبكة البلازمية الداخلية الخشنة (Rough Endoplasmic Reticulum):\nيمتاز هذا النوع من الشبكة البلازمية الداخلية بوجود الرايبوسومات على سطوح نبيباتها مما يعطيها مظهراً خشناً أو حبيبياً، ولهذا النوع دور فعال في بناء البروتينات، وهي تعمل على نقل المواد داخل الخلية، وبشكل خاص إلى أجسام كولجي، كما تعمل كشبكة هيكلية للمادة البينية السايتوبلازمية.\n\nالشبكة البلازمية الداخلية الملساء (Smooth Endoplasmic Reticulum):\nتختلف الشبكة البلازمية الداخلية الملساء عن الخشنة بخلوها من الرايبوسومات ولذا تكون أغشيتها ملساء وهي كما هو الحال في الشبكة البلازمية الداخلية الخشنة تعمل على نقل المواد داخل الخلية وكشبكة هيكلية للمادة البينية السايتوبلازمية، وتقوم الشبكة الملساء بدور مهم في إزالة التأثير السمي لبعض السموم والأدوية المخدرة، وهي تمثل مواضع لبناء وتجمع الشحوم لغرض خزنها ولذلك فهي تكثر في خلايا المبايض والخصى والغدتين الكظريتين حيث تقوم بإفراز الهورمونات السترويدية.", "page": 16, "pages": [16, 16], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p1", "type": "comparison", "prompt": "قارن بين الخلية بدائية النواة (Prokaryotic Cell) والخلية حقيقية النواة (Eukaryotic Cell).", "answer": "الخلية بدائية النواة (Prokaryotic Cell):\nتعد الخلية بدائية النواة أقل الخلايا تطوراً، كونها أكثرها بدائية من حيث الشكل والتركيب وتتميز بالآتي (شكل 1–4):\nأ. لهذه الخلية نواة بدون غشاء نووي وتدعى بمنطقة النواة أو المنطقة النووية (Nucleoid).\nب. لا يحوي سايتوبلازم الخلية بدائية النواة عضيات غشائية كأجسام كولجي (Golgi Bodies) والمايتوكوندريا (Mitochondria)، إلا أنه يحوي رايبوسومات تظهر بهيئة حبيبات صغيرة كثيرة العدد تقوم ببناء البروتينات.\nج. تتمثل الخلية بدائية النواة بالطحالب الخضر المزرقة (Blue Green Algae)، والبكتيريا (Bacteria) والمايكوبلازما (Mycoplasma)، وجميعها تتبع مملكة الأوليات (Monera).\n\nالخلية حقيقية النواة (Eukaryotic Cell):\nوهي الخلية التي تمتلك نواة حقيقية، وتوجد في ممالك (عوالم) الطليعيات (Protesta) والفطريات (Fungi) والنباتات (Plantae) والحيوانات (Animalia).\nتختلف الخلايا حقيقية النوى من حيث الشكل فلبعضها أشكال ثابتة منها الكروية والهرمية والأنبوبية والمكعبة والعمودية والبيضوية والمسطحة والنجمية والمغزلية ... إلخ.\nوللبعض الآخر شكل غير ثابت حيث يتغير من حين لآخر كالأميبا مثلاً، ويمكن أن يعزى التغير في الشكل إلى الوظيفة التي تقوم بها الخلايا فغالباً ما يكون للخلايا شكل يلائم الوظيفة التي تؤديها وأغلب الخلايا حقيقية النوى صغيرة، وتحتاج إلى استخدام مجهر لرؤيتها إلا أنها من دون شك أكبر حجماً من الخلايا بدائية النوى وعموماً تحتاج الخلية إلى مساحة سطحية (الغشاء البلازمي) لتستطيع من خلالها القيام بعملية تبادل المواد مع محيطها بشكل ملائم.", "page": 11, "pages": [11, 12], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p2", "type": "comparison", "prompt": "قارن بين جدار الخلية (Cell Wall) والغشاء البلازمي (Plasma Membrane).", "answer": "جدار الخلية (Cell Wall):\nيقتصر وجود جدار الخلية على الخلايا النباتية فقط وهو يتمثل بجدار خارجي سميك يحيط بمكونات الخلية ويغطي الغشاء البلازمي الذي يقع إلى الداخل منه، وجدار الخلية يحقق حماية وإسناد للغشاء البلازمي والسايتوبلازم (شكل 1–5).\nيتركب جدار الخلية من ثلاث طبقات هي:\nالصفيحة الوسطى (Middle Lamella).\nالجدار الابتدائي (Primary Wall).\nالجدار الثانوي (Secondary Wall).\n\nالغشاء البلازمي (Plasma Membrane):\nوهو غشاء خلوي يحيط بالسايتوبلازم في الخلايا بدائية النوى وحقيقية النوى ويتمثل بغشاء رقيق مرن ونصف ناضح وهو لا يرى بالمجهر الضوئي إلا أنه يمكن رؤيته بالمجهر الإلكتروني يتركب الغشاء البلازمي كيميائياً من طبقتين رقيقتين من جزيئات الدهون المفسفرة (Phospholipids) ذات طرف أليف (محب) للماء وطرف نافر للماء وتتخلل الطبقتين جزيئات بروتينية تسمح أو تتحكم بمرور المواد (شكل 1–7).", "page": 13, "pages": [13, 14], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p3", "type": "comparison", "prompt": "قارن بين الخيوط الدقيقة (Microfilaments) والنبيبات الدقيقة (Microtubules).", "answer": "الخيوط الدقيقة (Microfilaments):\nهي تراكيب رقيقة ومستقيمة لوحظت لأول مرة بوضوح في الخلايا العضلية، وهي تتمثل بخيوط الأكتين المكونة من بروتين الأكتين وخيوط المايوسين وهي الأخرى مكونة من بروتين المايوسين وكلا النوعين مسؤول عن قدرة الخلية في التقلص والانبساط.\n\nالنبيبات الدقيقة (Microtubules):\nهي أكبر من الخيوط الدقيقة وتتمثل بتراكيب أنبوبية مكونة من بروتين يدعى تيوبيولين (Tubulin) وللنبيبات الدقيقة دوراً حيوياً في حركة الكروموسومات أثناء انقسام الخلية وتعد مهمة بالنسبة للهيكل الخلوي، والتنظيم وانتقال المواد، فضلاً عن كونها تكون أجزاء أساسية في تركيب الأهداب والأسواط. والنبيبات الدقيقة التي توجد في سايتوبلازم الخلايا الحيوانية عادة وفي بعض الأحياء الواطئة مثل الطحالب والفطريات، تقع بالقرب من النواة، وتشكل الجسيمات المركزية (Centrosomes).", "page": 20, "pages": [20, 20], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p4", "type": "comparison", "prompt": "قارن بين الجسيمات المركزية (Centrosomes) والجسيم الحركي (Kinetosome).", "answer": "الجسيمات المركزية (Centrosomes):\nيحتوي الجسيم المركزي على زوج من المريكزات (Centrioles) عادة (شكل 1–13) وكل منهما يمثل أسطوانة مكونة من تسع مجاميع وتحتوي المجموعة الواحدة على ثلاثة نبيبات دقيقة.\n\nالجسيم الحركي (Kinetosome):\nهو يشابه المريكزات (Centrioles) في تركيبه، ويتمثل بتركيب يتخذ موقعاً عند قاعدة الهدب أو السوط في الخلايا التي تحوي أهداباً أو أسواطاً وللجسيم الحركي دوراً مهماً في حركة الأهداب والأسواط ويطلق عليه أيضاً بالجسيم القاعدي (Basal Body) (شكل 1–14).", "page": 20, "pages": [20, 21], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p5", "type": "comparison", "prompt": "قارن بين 2. البلازم النووي (Nucleoplasm) و3. النوية (Nucleolus).", "answer": "2. البلازم النووي (Nucleoplasm):\nهو سائل هلامي عديم اللون يملأ النواة وتتوزع فيه المحتويات النووية والمتمثلة بالنوية والشبكة الكروماتينية.\n\n3. النوية (Nucleolus):\nتحوي النواة نوية واحدة او اكثر، وعلى سبيل المثال تحوي نواة خلية البصل اربع نويات. وتبدو النوية بشكل تركيب كروي داخل النواة كبيرة الحجم نسبيا، وهي تتكون من البروتين والحامض النووي الرايبي (RNA). وللنوية دورا هام في تكوين الرايبوسومات التي يتم فيها تكوين البروتينات.", "page": 23, "pages": [23, 24], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p6", "type": "comparison", "prompt": "قارن بين ب. المحلول واطئ التركيز (Hypotonic Solution) وج. المحلول عالي التركيز (Hypertonic Solution).", "answer": "ب. المحلول واطئ التركيز (Hypotonic Solution):\nيتميز هذا المحلول بتركيز منخفض من المواد الذائبة غير النافذة اذا ماقورنت بالمواد الذائبة في سايتوبلازم الخلية الموجودة فيه والخلية تكتسب الماء وقد يؤدي دخول الماء الى انتفاخ الخلية الحيوانية وتمزقها (شكل 1-19).\n\nج. المحلول عالي التركيز (Hypertonic Solution):\nيتميز هذا المحلول بتركيز عال من المواد الذائبة بالمقارنة مع السايتوبلازم، ولذلك فان حركة الماء تكون من السايتوبلازم الى المحلول الخارجي مما يترتب عليه انكماش الخلايا (شكل 1-19). ونظرا لوجود جدار في الخلايا النباتية فأن حجم الخلية لايتغير كثيرا بالمقارنة مع الخلايا الحيوانية عندما توضع في محلول عال التركيز. وان مايحدث هو ابتعاد الغشاء الخلوي عن جدار الخلية (شكل 1-19) وهذا مايعرف بالبلزمة (Plasmolysis) وهو بالطبع ناتج عن خروج الماء من الخلية ولكن عند اضافة الماء للمحلول تعود الخلية الى حالتها الاولى وتسمى هذه العملية العكسية، بحالة ازالة البلزمة (Deplasmolysis).", "page": 28, "pages": [28, 28], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p7", "type": "comparison", "prompt": "قارن بين (4) النقل النشط او الفعال (Active Transport) و(1) الانتشار (Diffusion).", "answer": "(4) النقل النشط او الفعال (Active Transport):\nتمتص الخلايا احيانا بعض المواد من محيطها الخارجي بالرغم من ان تراكيز تلك المواد داخل الخلايا اعلى منها في الخارج، ومن اجل انجاز هذه العملية لابد من وجود مواد حاملة (Carriers) في غشاء الخلية يمكنها التحرك من الخارج الى الداخل وبالعكس، حيث تتحد المادة الحاملة مع مادة اخرى (جزيء أو أيون) تحتاجها الخلية وتتحرك باتجاه السطح الداخلي للغشاء حيث تنفصل المادة المنقولة داخل السايتوبلازم (شكل 1-20) وتحتاج هذه العملية الى صرف طاقة تستمد من ATP في الخلية الحية.\n\n(1) الانتشار (Diffusion):\nيعرف الانتشار بانه حركة الايونات والجزيئات خلال وسط معين من المناطق ذات التركيز العالي الى المناطق ذات التركيز الواطئ.\nوكقاعدة فان الغازات مثل الاوكسجين وثنائي اوكسيد الكاربون، والمواد القابلة للذوبان في الدهون مثل الهيدروكاربونات والكحولات هي المواد المذابة التي يمكنها الانتشار عبر الاغشية الحيوية (غشاء الخلية) بحرية تامة. ويمكن ملاحظة ظاهرة الانتشار بالعين المجردة من خلال وضع بلورات لكبريتات النحاس او برمنغنات البوتاسيوم في اناء زجاجي يحوي ماء، فسوف نلاحظ انتشار المادة الملونة الناتجة من ذوبان البلورات اعلاه في الماء حيث تنتشر المادة الملونة عبر مسافات قصيرة بينما يقل انتشارها عبر المسافات الطويلة وهذا يعود الى ان المسافة التي تقطعها الجزيئات المنتشرة تتناسب طرديا مع زمن الانتشار، ومع مرور الوقت فأن المادة سوف تنتشر في كل اجزاء الماء في الاناء الزجاجي، (شكل 1-17).", "page": 29, "pages": [29, 26], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p8", "type": "comparison", "prompt": "قارن بين (5) البلعمة (Phagocytosis) و(6) الشرب الخلوي (Pinocytosis).", "answer": "(5) البلعمة (Phagocytosis):\nيقصد بالبلعمة الاكل الخلوي وهي طريقة شائعة للتغذية بين الطليعيات مثل الاميبا وهي ايضا الطريقة التي تلتهم بها خلايا الدم البيض بقايا الخلايا والجراثيم التي توجد بالدم وتتم هذه العملية بان يكون غشاء الخلية جيبا يحيط المادة الصلبة، وبعد ذلك ينفصل هذا الجيب او الحوصلة من سطح الخلية ويتحرك داخل السايتوبلازم، حيث تهضم محتوياتها بوساطة الانزيمات المفرزة من الجسيمات الحالة والموجودة ضمن السايتوبلازم (شكل 1-21أ).\n\n(6) الشرب الخلوي (Pinocytosis):\nوهو عملية مشابهة للاكل الخلوي فعند دخول مادة سائلة من خارج الخلية يحدث انبعاج صغير في غشاء الخلية يحيط بالمادة السائلة والتي تصبح داخل حويصلة (Pinocytic Vesicle) حيث تنفصل هذه الحويصلة من غشاء الخلية وتصبح داخل الخلية كما في (الشكل 1-21 ب).", "page": 29, "pages": [29, 30], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-p9", "type": "comparison", "prompt": "قارن بين 1-7-2. الانقسام غير المباشر او الخيطي (Mitosis) و1-7-3. الانقسام الاختزالي (Meiosis).", "answer": "1-7-2. الانقسام غير المباشر او الخيطي (Mitosis):\nيعرف الانقسام الخيطي بانه «عملية انقسام النواة بصورة تضمن تسلم كل من الخليتين البنويتين الجديدتين نفس العدد ونفس النوعية من الكروموسومات الموجودة اصلا في الخلية الام».\nيتطلب الانقسام الخيطي تضاعفا لكل كروموسوم ليتكون كروموسومان متماثلين ومتجاورين اذ يظهران وكأنهما كروموسوم واحد. وعند بدء عملية انقسام الخلية يتباعد الكروموسومان احدهما عن الآخر ويظهران منفصلين في الاطوار المتقدمة. يعقب انقسام النواة الانقسام السايتوبلازمي (Cytokinesis). ولنأخذ مثلا خلية من خلايا جسم الانسان فسنجد انها تحتوي (46) كروموسوما تتضاعف قبل الانقسام فتصبح (92) كروماتيدا وعندما تتم عملية الانقسام يذهب (46) منها الى خلية و(46) الباقية الى الخلية الثانية. ليتشكل منها كروموسومات الخلايا الجديدة، وتستمر هذه العملية في كل مرة.\n\n1-7-3. الانقسام الاختزالي (Meiosis):\nتهدف عملية الانقسام الاختزالي الى الحفاظ على عدد ثابت من الكروموسومات لافراد الانواع المختلفة من الاحياء، خلال عملية تعاقب الاجيال الذي يتم خلاله تكوين الامشاج (Gametes) كالبيوض (Eggs) والنطف (Sperms) في الحيوانات والابواغ (Spores) في بعض النباتات. والانقسام الاختزالي عبارة عن انقسامين متعاقبين للخلية ويتم خلال الانقسام الاختزالي اختزال عدد الكروموسومات الى نصف العدد الكامل لكروموسومات الخلايا الجسمية، ولذلك نجد ان الامشاج تحتوي نصف عدد الكروموسومات الموجود في الخلايا الجسمية، وعند التحام نواتين لخليتين او مشيجين لتكوين اول خلية جنينية فأن الاخيرة تحوي عدد كامل من الكروموسومات.", "page": 34, "pages": [34, 36], "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e0", "type": "enumeration", "prompt": "عدد أسس نظرية الخلية.", "answer": "تستند نظرية الخلية إلى العمل الذي قدمه كل من ماثياس شلايدن (M. Schleidin) وثيودور شوان (T. Schwann)، ويمكن إيجاز أسسها بالآتي:\nأ. جميع الكائنات الحية تتكون من خلايا.\nب. الخلايا هي الوحدات الأساسية التركيبية والوظيفية للكائنات الحية.\nج. الخلايا تنتج من خلايا أخرى من خلال انقسامها.", "page": 9, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e1", "type": "enumeration", "prompt": "عدد المكونات الرئيسية للخلايا حقيقية النوى.", "answer": "تتألف الخلايا حقيقية النوى (شكل 1–5، 1–6) من ثلاث مكونات رئيسية هي:\nأ. جدار الخلية والغشاء البلازمي في الخلية النباتية (Cell Wall and Plasma Membrane)، والغشاء البلازمي فقط في الخلية الحيوانية حيث أنها لا تحتوي على جدار خلوي.\nب. السايتوبلازم (Cytoplasm).\nج. النواة (Nucleus).", "page": 13, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e2", "type": "enumeration", "prompt": "عدد طبقات جدار الخلية.", "answer": "يقتصر وجود جدار الخلية على الخلايا النباتية فقط وهو يتمثل بجدار خارجي سميك يحيط بمكونات الخلية ويغطي الغشاء البلازمي الذي يقع إلى الداخل منه، وجدار الخلية يحقق حماية وإسناد للغشاء البلازمي والسايتوبلازم (شكل 1–5).\nيتركب جدار الخلية من ثلاث طبقات هي:\nالصفيحة الوسطى (Middle Lamella).\nالجدار الابتدائي (Primary Wall).\nالجدار الثانوي (Secondary Wall).", "page": 13, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e3", "type": "enumeration", "prompt": "عدد وظائف جهاز كولجي في الخلايا الحيوانية.", "answer": "يتألف جهاز كولجي من ثلاث ردهات محددة بأغشية ملساء، الأولى تتمثل بعدد (3–10) من الأكياس المسطحة التي يطلق عليها الصهاريج (Cisternae)، والثانية عبارة عن حويصلات (Vesicles)، والثالثة مؤلفة من فجوات (Vacuoles) كبيرة (شكل 1–9)، وجهاز كولجي يخلو من الرايبوسومات.\nيطلق على جهاز كولجي في الخلية النباتية اسم الدكتوسوم (Dictyosome)، وهو يقوم ببناء السيليلوز وبعض مكونات الجدار الخلوي في الخلية النباتية.\nوفي الخلايا الحيوانية ينجز جهاز كولجي عدداً من الوظائف منها:\nبناء وإفراز السكريات المعقدة.\nإفراز البروتين الذي يحصل عليه من الشبكة البلازمية الداخلية أي أنه لا يصنع البروتين.\nإفراز العديد من المواد مثل الهورمونات والأنزيمات وغيرها.", "page": 17, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e4", "type": "enumeration", "prompt": "عدد أنواع البلاستيدات.", "answer": "عضيات خلوية توجد في سايتوبلازم الخلايا النباتية (شكل 1–5)، وتظهر بأشكال وأحجام وألوان مختلفة، فمنها القرصي والكأسي والحلزوني والنجمي وغير ذلك وتكون البلاستيدات على ثلاثة أنواع:\nأ. البلاستيدات الملونة: التي تحوي صبغات مختلفة تعطي ألوان الأزهار والثمار.\nب. البلاستيدات عديمة اللون: تشكل مراكز لتحويل سكر الكلوكوز إلى سكريات متعددة مثل النشاء أو إلى شحوم وبروتينات، فبياض البطاطا على سبيل المثال ناتج عن وجود بلاستيدات عديمة اللون بكميات كبيرة ومليئة بالنشاء.\nج. البلاستيدات الخضر: هي البلاستيدات الشائعة في النباتات.", "page": 18, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e5", "type": "enumeration", "prompt": "عدد وظائف الجسيمات الحالة.", "answer": "تنجز الجسيمات الحالة العديد من الوظائف الخلوية منها:\nأ. تخلص سايتوبلازم الخلية من بعض الدقائق الغذائية وقطع المايتوكوندريا والأحياء المجهرية وغير ذلك من الشوائب.\nب. تؤدي الجسيمات الحالة دوراً مهماً في عملية التحول الشكلي (Metamorphosis)، في الحيوانات وعلى سبيل المثال اختفاء ذنب دعاميص (يرقات) الضفادع عند تحولها إلى ضفادع بالغة، وتتم هذه العملية من خلال تحرر الأنزيمات من الجسيمات الحالة إلى سايتوبلازم الخلية وينتج عن ذلك هضم محتويات السايتوبلازم من الجزيئات الكبيرة وبالتالي موت الخلية، بعملية يطلق عليها التحلل الذاتي (Autolysis)، وتسهم هذه العملية في تحلل أجسام الكائنات الحية بعد موتها.\nج. تعمل على تحطيم الخلايا المكونة لها، عند موت الكائن الحي.\nد. تدوير العناصر في الطبيعة من خلال عملية التحلل الذاتي.", "page": 19, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e6", "type": "enumeration", "prompt": "عدد أشكال المحتويات غير الحية للخلية.", "answer": "هي عادة مكونات مؤقتة في السايتوبلازم يطلق عليها بالمخلفات السايتوبلازمية (Cytoplasmic Deposit) وتتكون هذه المخلفات بشكل رئيس من مواد أيضية أو مخلفات متراكمة ذات طبيعة مختلفة، توجد بعدة أشكال منها:\n1. القطيرات الدهنية (Lipid Droplets) في خلايا النسيج الدهني وخلايا الكبد.\n2. التجمعات الكاربوهيدراتية التي تتمثل بالكلايكوجين (Glycogen)، كما تتضح في خلايا الكبد.\n3. البروتينات التي تخزن في الخلايا الغدية بشكل حبيبات إفرازية (Secretory granules)، وتتحرر هذه الحبيبات بشكل دوري إلى السائل خارج الخلايا.\n4. مخلفات المواد الملونة أو الصبغات (Pigments) إذ تقوم الخلايا بصنع هذه الصبغات كما هو الحال في خلايا الجلد.\n5. الأنزيمات والهورمونات وبعض أنواع الفيتامينات وهذه تأخذ أشكالاً حبيبية كروية أو بيضوية وتكون محاطة بغشاء كما هو الحال في الحبيبات الإفرازية العصبية.", "page": 22, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e7", "type": "enumeration", "prompt": "عدد أصناف الأغشية تبعاً لقدرتها على نفاذية المواد.", "answer": "تمثل ظاهرة تبادل المواد بين الخلية ومحيطها عبر الغشاء البلازمي حيث تستطيع الخلية ان تمتص المواد الغذائية اذا وجدت في وسط غذائي مناسب، ولكن مجرد وجود المواد الغذائية خارج الخلية لايعني بالضرورة انه بامكان الخلية استغلالها فعلى هذه المواد ان تمر اولا خلال الغشاء البلازمي كما يجب ان تتميز بذوبانها في الماء بدرجة معينة حتى يمكنها العبور خلال هذا الغشاء، وبالمثل لابد ان تتميز النواتج الاخراجية ومواد الفضلات بذوبانها في السايتوبلازم حتى تستطيع العبور الى خارج الخلية. وبشكل عام يمكن ان تصنف الاغشية تبعا لقدرتها على نفاذية المواد الى:\nاغشية ذات نفاذية تامة وهي التي تنفذ المواد من خلالها بغض النظر عن طبيعتها او حجم جزيئاتها كما في الجدار الخلوي.\nاغشية شبه نفاذة (Semi Permeable) وهذه لاتسمح بعبور الذائبات بنفس معدلات عبور المذيبات.\nاغشية ذات نفاذية اختيارية (Selectively Permeable) وهي تسمح بعبور المواد اختياريا تبعا لحجم جزيئاتها مثل الغشاء البلازمي.\nاغشية غير نفاذة مثل اغشية النايلون. ولابد من الاشارة الى أن نفوذية الغشاء البلازمي تتأثر بعوامل داخلية وخارجية.", "page": 27, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e8", "type": "enumeration", "prompt": "اذكر أعداد الكروموسومات التي أوردها الكتاب لكل من الذبابة المنزلية والضفدع والحمامة والحصان والإنسان.", "answer": "تظهر الشبكة الكروماتينية بشكل تراكيب خيطية متداخلة غير منتظمة الشكل، وتتضح خيوط الشبكة الكروماتينية اثناء الانقسام الخلوي مكونة عددا محددا من التراكيب العصوية في الغالب وتعرف بالكروموسومات (Chromosomes) وهي تحمل الجينات (المورثات) التي يتم بواسطتها نقل الصفات الوراثية من جيل الى آخر، ولذا اكتسبت الكروموسومات اهمية كبرى بسبب الدور الاساسي الذي تلعبه في الوراثة والتكاثر والتباين والطفرات وغيرها.\nيمكن رؤية الكروموسومات فقط عند انقسام الخلية ويختلف عدد الكروموسومات في الانواع المختلفة من الاحياء اذ ان لكل نوع عددا ثابتا من الكروموسومات ففي خلايا دودة الاسكارس هناك كروموسومان فقط وقد يصل عدد الكروموسومات في خلايا الفراشة الاسبانية الى (380) كروموسوم، وهناك (12) كروموسوم في الذبابة المنزلية و(26) في الضفدع و(80) في الحمامة وفي الحصان يكون العدد (64) كروموسوما اما في الانسان فيكون العدد (46) كروموسوما. ولابد من الاشارة الى ان هذه الاعداد تمثل اعداد الكروموسومات في الخلايا الجسدية وان اعدادها في الامشاج او الخلايا الجنسية يكون نصف العدد اي ان بويضة الانسان أو النطفة تحتوي (23) كروموسوما في حين يكون العدد في الخلايا الجسدية (46 = 2 × 23) وهو ناتج من اندماج نواة خلية البيضة بنواة النطفة وللكروموسومات في كل نوع من انواع الكائنات الحية شكل وحجم ثابت ويتراوح طول الكروموسوم بين (0.2–50) مايكروميتر وعلى سبيل المثال يصل طوله في الانسان من (4–6) مايكروميتر (شكل 1-16).", "page": 24, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c1-e9", "type": "enumeration", "prompt": "عدد النظريات التي تفسر حركة الكروموسومات نحو القطبين.", "answer": "تنفصل في هذا الطور الكروموسومات البنوية الناتجة عن الكروماتيدات الشقيقة في الطور التمهيدي بعضها عن بعض باتجاه القطبين المتعاكسين للخلية (الشكل 1-23). لاتعرف ميكانيكية حركة الكروموسومات نحو القطبين المتعاكسين في الخلية لحد الان بشكل دقيق ولكن هناك نظريات تقترح تفسيراً لذلك وهي:\nأ- يعتقد ان خيوط المغزل تتقلص بوجود ATP وتسحب الكروموسومات نحو القطبين.\nب- يعتقد ان خيوط المغزل تعمل بوضعها طريقاً تنزلق عليه الكروموسومات متجهة نحو القطبين.", "page": 35, "chapter": 1, "chapterTitle": "الخلية"}, {"id": "c2-01", "type": "blank", "prompt": "يعرف العلم الذي يهتم بدراسة الانسجة بعلم _____.", "answer": "الانسجة", "page": 50, "terms": ["الانسجة"], "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-02", "type": "blank", "prompt": "الانسجة المرستيمية التي تستقر في القمم النامية للساق والجذر تسمى بالانسجة المرستيمية _____.", "answer": "القمية", "page": 51, "terms": ["القمية"], "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-03", "type": "blank", "prompt": "تعرف الخلايا البرنكيمية ذات البلاستيدات الخضر بالخلايا _____.", "answer": "الكلورنكيمية", "page": 55, "terms": ["الكلورنكيمية"], "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-04", "type": "blank", "prompt": "الخلايا الصخرية (الحجرية) توجد في بعض الثمار مثل _____.", "answer": "الكمثرى", "page": 56, "terms": ["الكمثرى"], "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-05", "type": "blank", "prompt": "تحتوي الخلية البدينة على _____ الذي يمنع تخثر الدم.", "answer": "الهيبارين", "page": 67, "terms": ["الهيبارين"], "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-06", "type": "blank", "prompt": "قدرت فترة حياة خلايا الدم الحمر في الانسان بنحو (_____) يوما تقريبا.", "answer": "120", "page": 75, "terms": ["120"], "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-07", "type": "blank", "prompt": "كل عصبونة يقابلها (_____) من خلايا الدبق العصبي.", "answer": "50", "page": 81, "terms": ["50"], "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-08", "type": "choice", "prompt": "اين يوجد النسيج المرستيمي القمي؟", "answer": "قمم الجذور والسيقان", "page": 53, "options": ["قمم الجذور والسيقان", "الحبل السري", "ادمة الجلد", "نقي العظم"], "correctIndex": 0, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-09", "type": "choice", "prompt": "اي الانسجة تكون خلاياه ميتة ذات جدران مغلظة؟", "answer": "النسيج السكلرنكيمي", "page": 56, "options": ["النسيج الكولنكيمي", "النسيج البرنكيمي", "النسيج السكلرنكيمي", "النسيج المرستيمي"], "correctIndex": 2, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-10", "type": "choice", "prompt": "ما وظيفة النسيج الظهاري الحرشفي البسيط؟", "answer": "الانتشار والترشيح", "page": 60, "options": ["الحماية والافراز", "الانتشار والترشيح", "الاسناد والتقوية", "خزن الدهون"], "correctIndex": 1, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-11", "type": "choice", "prompt": "اي الانسجة يوجد في بطانة الرغامي؟", "answer": "النسيج الظهاري العمودي المطبق الكاذب", "page": 61, "options": ["النسيج الظهاري المطبق الحرشفي", "النسيج الظهاري العمودي المطبق الكاذب", "النسيج الظهاري المتحول", "النسيج الظهاري المطبق المكعبي"], "correctIndex": 1, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-12", "type": "choice", "prompt": "اي الخلايا مسؤولة عن تكوين الاجسام المضادة؟", "answer": "الخلية البلازمية", "page": 66, "options": ["البلعم الكبير", "الارومة الليفية", "الخلية الدهنية", "الخلية البلازمية"], "correctIndex": 3, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-13", "type": "choice", "prompt": "اي الغضاريف يوجد في صيوان الاذن؟", "answer": "غضروف مطاط", "page": 72, "options": ["غضروف مطاط", "غضروف شفاف", "غضروف ليفي ابيض", "نسيج ضام مخاطاني"], "correctIndex": 0, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-14", "type": "choice", "prompt": "كم تبلغ نسبة بلازما الدم؟", "answer": "55%", "page": 77, "options": ["90%", "10%", "55%", "7–8%"], "correctIndex": 2, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-15", "type": "definition", "prompt": "عرف النسيج كما ورد في الكتاب.", "answer": "يمكن تعريف النسيج (Tissue) بأنه مجموعة من الخلايا المتماثلة بالاضافة الى نواتج خلوية معينة تخصصت لاداء وظيفة معينة. ويعرف العلم الذي يهتم بدراسة الانسجة بعلم الانسجة (Histology).", "page": 50, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-16", "type": "definition", "prompt": "عرف الانسجة النباتية.", "answer": "الانسجة النباتية هي مجموعة من الخلايا تظهر تباينا في الشكل والحجم مقترنة مع بعضها لانجاز وظيفة معينة.", "page": 51, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-17", "type": "definition", "prompt": "عرف النسيج المرستيمي او الانشائي.", "answer": "هو النسيج الذي يتميز بقدرة خلاياه على الانقسام المستمر (شكل 2-1). ويوجد في اجزاء النبات التي تظهر نشاط انقسامي ويؤدي الى:", "page": 52, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-18", "type": "definition", "prompt": "عرف النسيج الاساس.", "answer": "وهو النسيج الذي تتميز خلاياه لتكون الانسجة المستديمة في جسم النبات، ويشكل كتل نسيجية داخلية في الجذور والسيقان والاوراق متمثلة بالقشرة واللب والاشعة اللبية.", "page": 55, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-19", "type": "definition", "prompt": "عرف نسيج البشرة.", "answer": "هو النسيج الذي يغطي النبات، ويكون نسيج البشرة المستديمة، حيث تتكون البشرة عادة من صف واحد من الخلايا المتثخنة التي تغطي جسم النبات الاولي. وتكون خلايا البشرة مسطحة ومتراصة حيث تنعدم المسافات البينية. تتلخص وظيفة نسيج البشرة بالحماية والسيطرة على تبادل الغازات (من خلال ازواج من الخلايا الحارسة) وامتصاص الماء (جدول 2-3).", "page": 56, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-20", "type": "definition", "prompt": "عرف النسيج الضام (الرابط).", "answer": "وهو النسيج الذي يقوم بربط اجزاء الجسم المختلفة واسنادها ولذلك يطلق على النسج الضامة بالنسج الساندة (Supporting Tissues).", "page": 65, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-21", "type": "definition", "prompt": "عرف اللمف.", "answer": "وهو سائل يتجمع من الانسجة ويرجع الى مجرى الدم بوساطة اوعية لمفاوية (Lymphatic Vessels). يشبه اللمف البلازما في التركيب الا ان محتواه البروتيني اقل وعملية التخثر فيه تكون أبطأ والخثرة تكون لينة لاصلبة.", "page": 77, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-22", "type": "comparison", "prompt": "قارن بين الظهاري الحرشفي البسيط والمكعبي البسيط من حيث شكل الخلايا والنواة.", "answer": "أ. يتكون هذا النوع من الانسجة الظهارية من طبقة مفردة من الخلايا المسطحة التي تبدو مضلعة وذات نواة مسطحة مركزية الموقع (شكل 2-7).\nأ. يتكون من طبقة مفردة من الخلايا المكعبة التي تبدو مربعة في مقاطعها، والنواة فيها كروية مركزية الموقع، (شكل 2-8).", "page": 60, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-23", "type": "comparison", "prompt": "قارن بين الظهاري العمودي البسيط والمطبق الكاذب من حيث خلاياه.", "answer": "أ. تكون خلايا هذا النسيج بشكل اعمدة طويلة، وتظهر مستطيلة في مقاطعها، وتكون نوى الخلايا بيضوية وتتخذ موقعا اقرب الى القاعدة (شكل 2-9).\nأ. يتكون هذا النسيج من اكثر من نوع من الخلايا التي تقع انويتها في مستويات مختلفة مما يوحي بأن النسيج مكون من عدة طبقات، الا ان جميع خلاياه تستند الى الغشاء القاعدي والسطح الحر لخلاياه قد يكون مزودا باهداب، وعندئذ يسمى بالنسيج الظهاري المطبق الكاذب المهدب، (شكل 2-10).", "page": 61, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-24", "type": "comparison", "prompt": "قارن بين الظهاري المطبق الحرشفي والمطبق المكعبي من حيث خلاياه.", "answer": "أ. يتكون النسيج الظهاري المطبق الحرشفي من اكثر من طبقة من الخلايا، القاعدية منها تكون عمودية او مكعبة وتستقر على الغشاء القاعدي، والطبقات الوسطى مؤلفة من خلايا متعددة السطوح، اما خلايا الطبقة السطحية فتكون من النوع المسطح الحرشفي (Squamous)، (شكل 2-11) وقد تكون متقرنة كما هو الحال في بشرة الجلد.\nأ. تكون خلايا الطبقة السطحية لهذا النسيج مكعبة الشكل، اما خلايا الطبقتين المتوسطة والقاعدية فهي تشبه الخلايا في النسيج المطبق الحرشفي (شكل 2-12).", "page": 63, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-25", "type": "comparison", "prompt": "قارن بين الظهاري المطبق العمودي والمتحول من حيث خلايا الطبقات.", "answer": "أ. تكون خلايا الطبقة السطحية لهذا النوع من النسج الظهارية عمودية الشكل اما خلايا الطبقتين المتوسطة والقاعدية فتكون متعددة السطوح واصغر حجما عادة (شكل 2-13).\nأ. وهو نسيج ظهاري مطبق خاص، خلايا الطبقة السطحية فيه تكون كبيرة مظلية الشكل وهي تحوي نواة واحدة او نواتين، وتكون خلايا الطبقة المتوسطة متعددة السطوح اما خلايا الطبقة القاعدية فتكون مكعبة في شكلها وتستقر على الغشاء القاعدي (شكل 2-14).", "page": 64, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-26", "type": "comparison", "prompt": "قارن بين الارومة الليفية والبلعم الكبير من حيث الوظيفة.", "answer": "ب. تتلخص وظيفة الارومة الليفية في كونها المسؤولة عن تكوين جميع انواع الالياف في النسيج الضام والتي سيرد ذكرها لاحقا.\nب. تقوم هذه الخلية بالتهام الجزيئات الغريبة ضمن النسيج وبالتالي فأن وظيفتها دفاعية.", "page": 66, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-27", "type": "comparison", "prompt": "قارن بين الليف الابيض والليف الاصفر من حيث الصفات العامة.", "answer": "1. الليف الابيض او الغراوي. أ. يسمى بالابيض لكونه ابيض في حالة الطراوة. ب. يوجد بشكل حزم مؤلفة من عدة الياف وكل ليف يتكون من لييفات. ج. الليف الابيض ذو اهمية ميكانيكية في النسيج الضام كونه يقاوم السحب.\n2. الليف الاصفر او المرن (المطاط). أ. يسمى بالاصفر للونه الاصفر في حالة الطراوة. ب. يوجد بصورة مفردة ولايشكل حزما وتتفرع الالياف الصفر وتكون مرنة سهلة التمدد ولكنها ليست قوية كقوة الالياف البيض.", "page": 67, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-28", "type": "comparison", "prompt": "قارن بين العضلة الملساء والهيكلية والقلبية من حيث النواة والعمل.", "answer": "4. النواة — العضلة الملساء: مفردة مركزية الموقع. العضلة الهيكلية: متعددة الانوية وتكون الانوية محيطية الموقع. العضلة القلبية: مفردة مركزية الموقع.\n5. العمل — العضلة الملساء: لاارادي. العضلة الهيكلية: ارادي. العضلة القلبية: لاارادي.", "page": 80, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-29", "type": "enumeration", "prompt": "عدد ما يؤدي اليه نشاط النسيج المرستيمي.", "answer": "استطالة قمم الجذور والسيقان.\nنمو البراعم.\nتثخن بعض الجذور والسيقان.", "page": 52, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-30", "type": "enumeration", "prompt": "عدد انواع الانسجة المرستيمية.", "answer": "يتمثل النسيج المرستيمي بثلاثة انواع من الانسجة (جدول 2-2) هي: النسيج المرستيمي القمي. النسيج المرستيمي الجانبي. النسيج المرستيمي البيني.", "page": 53, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-31", "type": "enumeration", "prompt": "عدد الانواع الاساسية للانسجة الحيوانية.", "answer": "تتمثل الانسجة الحيوانية بأربعة انواع اساسية هي: النسيج الظهاري (الطلائي) (Epithelial Tissue). النسيج الضام (الرابط) (Connective Tissue). النسيج العضلي (Muscular Tissue). النسيج العصبي (Nervous Tissue).", "page": 59, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-32", "type": "enumeration", "prompt": "مم تتكون النسج الضامة؟", "answer": "تتكون النسج الضامة من: (أ) خلايا (Cells). (ب) الياف (Fibers). (ج) مادة بين خلوية (Intercellular Substance) ويطلق عليها ايضا بالقالب (Matrix).", "page": 65, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-33", "type": "enumeration", "prompt": "عدد انواع النسيج الضام الرخو او المفكك.", "answer": "يصنف النسيج الضام الرخو او المفكك تبعا للخلايا والالياف المكونة له وكالآتي: 1. نسيج ضام هللي (فجوي) (Areolar Connective Tissue). 2. نسيج ضام شحمي (Adipoes Connective Tissue). 3. نسيج ضام متوسط (Mesenchymal Connective Tissue). 4. نسيج ضام شبكي (Reticular Connective Tissue). 5. نسيج ضام مخاطاني (Mucoid Connective Tissue).", "page": 68, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-34", "type": "enumeration", "prompt": "عدد انواع خلايا الدم البيض الحبيبية ونسبها.", "answer": "أ. خلايا الدم البيض العدلة (Neutrophils)، وتؤلف (40–70%) من العدد الكلي لخلايا الدم البيض.\nب. خلايا الدم البيض الحمضة (Acidophils) وتؤلف (1–4%) من العدد الكلي لخلايا الدم البيض.\nج. خلايا الدم البيض القعدة (Basophils) وتؤلف ما يقارب (0.5–1%) من العدد الكلي لخلايا الدم البيض.", "page": 76, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "c2-35", "type": "enumeration", "prompt": "عدد انواع الخلايا العصبية تبعا لعدد البروزات.", "answer": "1. خلية احادية القطب (Monopolar Neuron)، يكون جسمها كروي او بيضوي وذو بروز واحد.\n2. خلية ثنائية القطب (Bipolar Neuron)، ويكون جسمها مغزلي ذو بروزين.\n3. خلية احادية القطب كاذبة (Pseudounipolar Neuron)، لها قطب واحد يتفرع قرب جسم الخلية الى محور وتشجرات.\n4. خلية متعددة الاقطاب (Multipolar Neuron)، ويكون جسمها نجمي الشكل متعدد البروزات.", "page": 81, "chapter": 2, "chapterTitle": "الأنسجة"}, {"id": "ch3-q1", "type": "blank", "prompt": "تتكون النطفة في .......... التي تتألف من اعداد كبيرة من .......... ملتوية.", "answer": "تتكون النطفة (الحيوان المنوي) في الخصية (Testis) التي تتألف من اعداد كبيرة من نبيبات منوية (Seminiferous Tubules) ملتوية. تبطن هذه النبيبات خلايا جرثومية اولية تنقسم انقسامات غير مباشرة متعددة ومتعاقبة وينتج عنها خلايا جديدة تدعى سليفات النطف (Spermatogonia) وتكون ثنائية المجموعة الكروموسومية (2س) تنقسم سليفات النطف انقسامات اعتيادية ينتج عنها تضاعف في اعدادها.", "page": 90, "terms": ["الخصية", "نبيبات منوية"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q2", "type": "blank", "prompt": "تنتظم جزيئات البروتين حول الحامض النووي ويتكون (..........) فيروس جديد في مرحلة الانضاج.", "answer": "تنتظم جزيئات البروتين لتكون اغطية بروتينية حول جزيئات الحامض النووي للفيروس، ويتكون (100-200) فيروس جديد.", "page": 94, "terms": ["100-200"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q3", "type": "blank", "prompt": "تدعى الافراد الصغيرة الناتجة داخل جدار خلية الكلاميدوموناس بالامشاج .......... .", "answer": "1- ينقسم الكلاميدوموناس الذي يكون احادي المجموعة الكروموسومية (س) اعتيادياً عدة انقسامات متتالية ليتكون (16-32) فرداً داخل جدار الخلية الاصلي. وتكون الافراد الناتجة مشابهة للكلاميدوموناس الام ولكنها اصغر منه بكثير وتدعى بالامشاج المتشابهة (Isogametes).", "page": 97, "terms": ["المتشابهة"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q4", "type": "blank", "prompt": "تتكاثر اليوغلينا بالانقسام الثنائي .......... .", "answer": "تتكاثر اليوغلينا بالانقسام الثنائي الطولي ويحصل هذا الانقسام في الطور حر السباحة وفي الطور المتكيس وكالآتي:", "page": 100, "terms": ["الطولي"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q5", "type": "blank", "prompt": "يتكون الجزء الذكري في الزهرة من .......... و .......... الذي يحمله.", "answer": "تمثل الاجزاء الذكرية في الزهرة وتتكون من جزءين هما: المتك (Anther) وهو عبارة عن تركيب كيسي اسطواني او بيضوي الشكل توجد داخله حبوب اللقاح، والجزء الثاني هو الحامل الاسطواني الرفيع او الخيط (Filament) الذي يحمل المتك.", "page": 108, "terms": ["المتك", "الخيط"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q6", "type": "blank", "prompt": "النواتان المركزيتان في الكيس الجنيني تكونان نواتين .......... .", "answer": "اما نوى الطرف المقابل للطرف النقيري ضمن الكيس الجنيني فهي الاخرى تحاط بأغشية خلوية وتكون خلايا سمتية (Antipodals). وتكون النواتان المركزيتان نواتين قطبيتين (Polar Nuclei).", "page": 112, "terms": ["قطبيتين"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q7", "type": "blank", "prompt": "يصل طول النبيبات المنوية في خصية الانسان مجتمعة حوالي .......... متر.", "answer": "تكون الخصية في الانسان بشكل تركيب بيضوي وهي تحتوي على نبيبات منوية (Seminiferous Tubules)، (شكل 3-38)، ويصل طول النبيبات المنوية مجتمعة حوالي 250 متر.", "page": 126, "terms": ["250"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q8", "type": "blank", "prompt": "تتم السيطرة على الدورة المبيضية بهورموني .......... و .......... المحفزين للحويصلات والجسم الاصفر.", "answer": "تتم السيطرة على الدورة المبيضية بوساطة الهورمونات المحفزة للمناسل (Gonadotropic Hormones) والهورمون المحفز للحويصلات (FSH - Follicle Stimulating Hormone) والهورمون المحفز للجسم الاصفر (LH - Luteinizing Hormone) ويمكن ايجاز احداث الدورة المبيضية بالآتي:", "page": 130, "terms": ["FSH", "LH"], "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q9", "type": "choice", "prompt": "كم تستغرق عملية تكاثر البلعم البكتيري كاملة تقريباً؟", "answer": "في هذه المرحلة تقود الفيروسات المتكونة الى تحلل الخلية البكتيرية المضيفة، وتتحرر الفيروسات لتصيب بكتيريا اخرى غير مصابة وتستغرق هذه العملية كاملة مايقرب من 25 دقيقة وبمرور الوقت تكون البلاعم البكتيرية (آكلات البكتيريا) قد قضت على تجمع كبير من البكتيريا.", "page": 94, "options": ["25 دقيقة", "250 دقيقة", "13 دقيقة", "28 دقيقة"], "correctIndex": 0, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q10", "type": "choice", "prompt": "بأي طريقة يتكاثر البراميسيوم لاجنسياً؟", "answer": "يتكاثر البراميسيوم لاجنسياً بالانقسام الثنائي (Binary Fission) المستعرض وكالآتي (شكل 3-7):", "page": 98, "options": ["الانقسام الثنائي الطولي", "الانقسام الثنائي المستعرض", "التبرعم", "الاخصاب الذاتي"], "correctIndex": 1, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q11", "type": "choice", "prompt": "ما المجموعة الكروموسومية لخلايا الطور البوغي؟", "answer": "وهو الطور اللاجنسي الذي تنتج فيه الابواغ وتكون خلاياه ذات عدد كروموسومي كامل (2س) وعندما ينضج هذا الطور تعاني بعض خلاياه وهي الخلايا الام للابواغ عملية انقسام اختزالي وتتكون نتيجة هذا الانقسام ابواغ ذات نصف العدد الكامل من الكروموسومات (س)، وهذه الابواغ هي التي تحدد بدء الطور المشيجي (Gametophyte).", "page": 103, "options": ["س", "3س", "2س", "4س"], "correctIndex": 2, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q12", "type": "choice", "prompt": "كيف يكون تعرق الاوراق في نبات ذي فلقتين؟", "answer": "نبات ذو فلقة واحدة: تعرق الاوراق متوازي. نبات ذو فلقتين: تعرق الاوراق شبكي.", "page": 108, "options": ["متوازي", "اسطواني", "ليفي", "شبكي"], "correctIndex": 3, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q13", "type": "choice", "prompt": "ما الزهرة التي تمتلك اسدية ومدقة؟", "answer": "زهرة تامة (Perfect) ويطلق عليها ايضاً زهرة خنثية (Hermaphrodite)، او ثنائية الجنس (Dioecious): تمتلك اسدية ومدقة.", "page": 109, "options": ["زهرة تامة", "زهرة عقيمة", "زهرة غير تامة", "انتظام الازهار"], "correctIndex": 0, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q14", "type": "choice", "prompt": "اي مما يأتي مثال على الثمار المتجمعة في الكتاب؟", "answer": "هي الثمار المتكونة من كربلات عديدة منفصلة، وتنشأ الثمرة من هذا النوع من زهرة واحدة ترتبط بالثميرات معاً بتخت واحد كما في التوت الاسود.", "page": 117, "options": ["الاناناس", "التوت الاسود", "البرتقال", "الباقلاء"], "correctIndex": 1, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q15", "type": "choice", "prompt": "اين تنضج النطف وتخزن في الجهاز التناسلي الذكري للانسان؟", "answer": "2. البربخ (2) (Epididymis). الوظيفة: تنضج فيه النطف وهو يمثل موقع خزن النطف.", "page": 125, "options": ["القناة القاذفة", "غدة البروستات", "البربخ", "القضيب"], "correctIndex": 2, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q16", "type": "choice", "prompt": "ماذا ينتج عن بيوض نحل العسل غير المخصبة؟", "answer": "يكون التكاثر العذري شائعاً في نحل العسل فأنثى النحل او الملكة تلقح من قبل الذكر مرة واحدة في حياتها، وتحتفظ بالحيوانات المنوية او النطف في كيس خاص متصل بالمسلك التناسلي ويغلق بصمام عضلي. وعندما تضع الملكة بيوضها فأما ان تفتح الصمام لتنطلق النطف فتخصب تلك البيوض او ان تبقيه مغلقاً فتنمو البيوض دون اخصاب، علماً ان البيوض غير المخصبة ينتج عنها ذكوراً. وفي بعض الحالات يكون التكاثر العذري هو النوع الوحيد من التكاثر، فهناك مجتمعات معينة من السحالي السوطية تنتشر في الجنوب الغربي من امريكا، هي سلالات تتكون جميع افرادها من الاناث وهذه الاناث ثنائية المجموعة الكروموسومية، وذلك لان الكروموسومات فيها تضاعف نفسها قبل عملية الانقسام الاختزالي لتصبح رباعية المجموعة الكروموسومية (4س) (Tetraploid) وبعد الانقسام تصبح ثنائية المجموعة الكروموسومية وتنمو البيوض ثنائية المجموعة الكروموسومية بدون اخصاب.", "page": 133, "options": ["الملكات", "العاملات", "البيوض", "الذكور"], "correctIndex": 3, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q17", "type": "definition", "prompt": "عرف الاخصاب كما ورد في الكتاب.", "answer": "عملية التكاثر الجنسي تتم بأتحاد نواتي النطفة والبيضة بعملية تدعى الاخصاب (Fertilization) وينتج عن ذلك اختلاطاً للمادة الوراثية، فيتوارث الابناء صفات تجمع بين الابوين.", "page": 90, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q18", "type": "definition", "prompt": "ما البلازميد او عامل الخصوبة في البكتيريا؟", "answer": "ويحصل الاقتران في البكتيريا ايضاً عندما ينتقل البلازميد (plasmid) او عامل الخصوبة (قطعة دائرية صغيرة من DNA) من الخلية المعطية الى المستلمة التي لاتحتوي البلازميد ويتم النقل عبر جسر الاقتران بين الخليتين وفي النهاية تصبح كلا الخليتين حاوية على عامل الخصوبة (شكل 3-5).", "page": 96, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q19", "type": "definition", "prompt": "عرف الثالوس الاولي في السرخسيات.", "answer": "ج- تنمو الابواغ الى طور مشيجي ممثلاً بالثالوس الاولي (Prothalus) الذي يعرف بأنه تركيب قلبي الشكل اخضر اللون يحمل اركيكونيوم (Archegonium) وهي الحافظة المشيجية الانثوية والانثريديوم (Antheridium) وهي الحافظة المشيجية الذكرية وينمو من طرفه المدبب اشباه الجذور.", "page": 106, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q20", "type": "definition", "prompt": "عرف المبيض في الزهرة.", "answer": "هو جزء المدقة القاعدي الذي يتمثل بتركيب منتفخ تتكون بداخله البويضات (Ovules) المرتبطة بجدار المبيض عن طريق عنق قصير يسمى بالحبل السري (Funiculus).", "page": 108, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q21", "type": "definition", "prompt": "عرف التلقيح.", "answer": "يعرف التلقيح بأنه عملية انتقال حبوب اللقاح من المتك الى الميسم للنوع نفسه من النبات وتحصل نتيجة هذا الانتقال عملية الاخصاب (Fertilization)، وعليه فان التلقيح يعد واحداً من العمليات المؤدية الى تكوين البذور.", "page": 112, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q22", "type": "definition", "prompt": "ما القصرة؟", "answer": "يبدأ تكوين البذرة بعد عملية الاخصاب مباشرة حيث تنقسم نواة السويداء لتكوين نسيج السويداء، ويلي ذلك نمو غلاف او غلافي البويض وتحوله الى غلاف للبذرة الذي يعرف بالقصرة (Testa)، (شكل 3-19).", "page": 115, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q23", "type": "definition", "prompt": "عرف الثمرة كما ورد في الكتاب.", "answer": "لقد عرفت عزيزي الطالب ان الثمرة يمكن ان تعرف على انها مبيض ناضج مع محتوياته واغلفته وتكون بداخله البذور.", "page": 117, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q24", "type": "definition", "prompt": "عرف التكاثر العذري.", "answer": "يعد التكاثر العذري نوع من انواع التكاثر الذي ينمو فيه الجنين من بيضة غير مخصبة. ويحدث التكاثر العذري في بعض الديدان الحلقية والقشريات والحشرات، وفي انواع عديدة من الاسماك والبرمائيات والسحالي الصحراوية.", "page": 133, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q25", "type": "comparison", "prompt": "قارن بين التكاثر اللاجنسي والتكاثر الجنسي من حيث طريقة الانتاج.", "answer": "تستطيع بعض الكائنات الحية انتاج كائنات اخرى من نوعها. ويتم هذا بتحول اجزاء من الكائن الحي الى احياء جديدة شبيهة بالاصل الذي نتجت منه، وقد ينتج عن مثل هذا التكاثر كائناً واحداً او كائنات عديدة.\nيتم التكاثر اللاجنسي في الكائنات الحية بطرق متعددة ممثلة بالانقسام الثنائي والتبرعم وتكوين السبورات والتكاثر الخضري وغيرها.\nتتميز افراد الكثير من النباتات ومعظم الحيوانات الراقية الى ذكور واناث، حيث تنتج الذكور خلايا تكاثرية ذكرية هي النطف (الحيامن) (Sperms) وتنتج الاناث خلايا تكاثرية انثوية هي البيوض (Ova).", "page": 89, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q26", "type": "comparison", "prompt": "قارن بين الخلية المعطية والخلية المستلمة في الاقتران البكتيري.", "answer": "1- تتم عملية الاقتران بين خليتين الاولى هي الخلية المعطية (Donor Cell)، وتحتوي عامل الخصوبة (Fertility Factor) المتمثل بجزيئات من (DNA) في سايتوبلازم الخلية المعطية كما تحوي الخلية زوائد يطلق عليها بالاهلاب (اهلاب الاقتران او الاهلاب الجنسية) وهي تبرز الى السطح وتصبح الخلية البكتيرية خلية ذكرية معطية، اما الخلية الثانية فهي الخلية المستلمة (Reciepient Cell)، وهذه لاتحتوي عادة على عامل الخصوبة ولا على اهلاب الاقتران وتكون بمثابة خلية انثوية.", "page": 96, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q27", "type": "comparison", "prompt": "قارن بين الاخصاب الذاتي والاقتران في البراميسيوم من حيث تبادل الانوية وتماثل العوامل الوراثية.", "answer": "تشبه عملية الاخصاب الذاتي الاقتران المذكور اعلاه، فيما عدا عدم حصول عملية تبادل للانوية، حيث ان النواتين الصغيرتين الاوليتين اللتان تحتويان نصف العدد الكامل من الكروموسومات تتحدان لتكونا معاً نواة مندمجة متماثلة (Synkaryion) اي تكون متماثلة بالعوامل الوراثية (Homozygous) وليست متباينة العوامل الوراثية (Heterozygous)، كما هو الحال في الاقتران.", "page": 100, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q28", "type": "comparison", "prompt": "قارن بين الطور البوغي والطور المشيجي.", "answer": "وهو الطور اللاجنسي الذي تنتج فيه الابواغ وتكون خلاياه ذات عدد كروموسومي كامل (2س) وعندما ينضج هذا الطور تعاني بعض خلاياه وهي الخلايا الام للابواغ عملية انقسام اختزالي وتتكون نتيجة هذا الانقسام ابواغ ذات نصف العدد الكامل من الكروموسومات (س)، وهذه الابواغ هي التي تحدد بدء الطور المشيجي (Gametophyte).\nوهو الطور الجنسي وتنتج فيه الامشاج. وبعد الاخصاب الذي يتم بين الامشاج الذكرية والانثوية يبدأ الطور البوغي وهكذا تتعاقب الاجيال. ولابد من الاشارة الى انه كلما تقدمنا في سلم تطور النبات نجد ان حجم الطور المشيجي يظهر اختزالاً ويصل قمة الاختزال في النباتات الزهرية (شكل 3-12).", "page": 103, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q29", "type": "comparison", "prompt": "قارن بين الاوراق الكأسية والاوراق التويجية.", "answer": "تسمى بمجموعها الكأس (Calyx)، وهي تحمي برعم الزهرة قبل انفتاحه. وتكون الاوراق الكأسية في الغالب خضراء اللون الا انها قد تكون ملونة احياناً، وتبقى متصلة بالتخت.\nتسمى بمجموعها التويج (Corolla)، وتكون متباينة بدرجة كبيرة في حجمها وشكلها ولونها باختلاف النباتات. عدد الاوراق التويجية في الغالب يكون بنفس عدد الاوراق الكأسية او مضاعفاتها فعلى سبيل المثال نجد ان لزهرة السوسن (Iris) ثلاثة اوراق كأسية وثلاثة تويجية في حين يكون عدد الاوراق التويجية في الروز اضعاف مضاعفة لعدد الاوراق الكأسية. وتتلخص اهميتها في كونها جاذبة للحشرات التي تعمل على تلقيح النباتات. وكلا الاوراق الكأسية والتويجية ليس لها دور مباشر في عملية التكاثر الجنسي وتكوين البذور.", "page": 107, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q30", "type": "comparison", "prompt": "قارن بين نبات ذي فلقة واحدة ونبات ذي فلقتين.", "answer": "نبات ذو فلقة واحدة: ذو ورقة جنينية واحدة. نبات ذو فلقتين: ذو ورقتين جنينيتين.\nنبات ذو فلقة واحدة: اجزاء الزهرة ثلاثية او مضاعفات الثلاثة. نبات ذو فلقتين: اجزاء الزهرة رباعية او خماسية او مضاعفات الاربعة او الخمسة.\nنبات ذو فلقة واحدة: حبة اللقاح ذات ثقب واحد. نبات ذو فلقتين: حبة اللقاح ذات ثلاثة ثقوب.\nنبات ذو فلقة واحدة: غالباً عشبية. نبات ذو فلقتين: عشبية او خشبية.\nنبات ذو فلقة واحدة: تعرق الاوراق متوازي. نبات ذو فلقتين: تعرق الاوراق شبكي.\nنبات ذو فلقة واحدة: الجذر ليفي. نبات ذو فلقتين: الجذر وتدي.", "page": 108, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q31", "type": "comparison", "prompt": "قارن بين التلقيح الذاتي والتلقيح الخلطي.", "answer": "يتم التلقيح الذاتي بانتقال حبوب اللقاح من متك زهرة الى ميسم الزهرة نفسها او الى ميسم زهرة اخرى للنبات نفسه، ويحصل مثل هذا النوع من التلقيح في العديد من النباتات مثل الحنطة والشعير والرز والقطن والفاصوليا والبزاليا واشجار الحمضيات وغيرها.\nيتم هذا النوع من التلقيح بانتقال حبوب اللقاح من متك زهرة الى ميسم زهرة اخرى لنبات آخر من النوع نفسه وربما الى انواع اخرى تنتمي الى نفس الجنس. يحدث التلقيح الخلطي في العديد من النباتات وهو اكثر اهمية من التلقيح الذاتي حيث تكون الثمار والبذور الناتجة اكبر حجماً واكثر عدداً واسرع نمواً من تلك الناتجة من التلقيح الذاتي في الكثير من الاحيان.", "page": 112, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q32", "type": "comparison", "prompt": "قارن بين الثمار البسيطة والثمار المتجمعة.", "answer": "هي الثمار الناتجة من زهرة واحدة ذات كربلة واحدة او عدة كربلات ملتحمة، كما هو الحال في الباقلاء والطماطة والخيار والبرتقال والمشمش وغيرها (شكل 3-20).\nهي الثمار المتكونة من كربلات عديدة منفصلة، وتنشأ الثمرة من هذا النوع من زهرة واحدة ترتبط بالثميرات معاً بتخت واحد كما في التوت الاسود.", "page": 117, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q33", "type": "enumeration", "prompt": "عدد مراحل تكوين النطف من سليفات النطف حتى النطفة الناضجة.", "answer": "تتكون النطفة (الحيوان المنوي) في الخصية (Testis) التي تتألف من اعداد كبيرة من نبيبات منوية (Seminiferous Tubules) ملتوية. تبطن هذه النبيبات خلايا جرثومية اولية تنقسم انقسامات غير مباشرة متعددة ومتعاقبة وينتج عنها خلايا جديدة تدعى سليفات النطف (Spermatogonia) وتكون ثنائية المجموعة الكروموسومية (2س) تنقسم سليفات النطف انقسامات اعتيادية ينتج عنها تضاعف في اعدادها.\nتمر سليفات النطف بمرحلة نمو بعد توقف انقساماتها ويكبر حجمها وتسمى الخلايا النطفية الاولية (Primary Spermatocytes).\nتمر الخلايا النطفية الاولية بمرحلة انقسام اختزالي اول ينتج عنه خليتين متساويتين في الحجم احاديتا المجموعة الكروموسومية (س) وتسمى كل منهما بالخلية النطفية الثانوية (Secondary Spermatocyte).\nتمر الخليتان النطفيتان الثانويتان بمرحلة الانقسام الاختزالي الثاني وتنتج عنه اربعة خلايا متساوية الحجم احادية المجموعة الكروموسومية (س)، وتدعى هذه الخلايا الاربع بأرومات النطف (Spermatids).\nتعاني ارومات النطف تغيرات في شكلها وتركيبها مؤدية الى تكوين النطفة الناضجة (Mature Sperm).", "page": 90, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q34", "type": "enumeration", "prompt": "عدد خطوات الاقتران في البراميسيوم.", "answer": "تتم عملية الاقتران في البراميسيوم كالآتي (شكل 3-8):\n1- يتقابل فردان من النوع نفسه ولكنهما من سلالتين مختلفتين ويكون تماسهما من الجهة التي يقع فيها الاخدود الفمي ويبقيان ملتصقين وقتاً قصيراً. فيتكون عندها جسر بروتوبلازمي بينهما وهو وقتي لغرض عبور او تبادل مواد كروموسومية.\n2- تبدأ النواة الصغيرة في الكائنين عملية الانقسام حيث تنقسم انقساماً اختزالياً (Meiosis) ينتج عنه اربعة نوى يحوي كل منها نصف العدد الكامل للكروموسومات (س).\n3- تتحلل وتختفي ثلاثة نوى منها والنواة الرابعة المتبقية تنقسم انقساماً اعتيادياً غير متساوياً الى نواتين اوليتين يحوي كل منهما نصف العدد الكامل للكروموسومات (س) تتماثلان بنواة اولية ذكرية واخرى انثوية.\n4- تتبادل الانوية الذكرية في الكائنين المقترنين وتتحد مع الانوية الانثوية لتتكون النواة المندمجة التي تحوي العدد الكامل من الكروموسومات (2س).\n5- ينفصل الفردان المقترنان، وينقسم كل منهما انقسامين اعتياديين ليتكون من كل منهما اربع براميسيومات بنوية (جديدة).\nشكل (3-8). الاقتران في البراميسيوم.", "page": 99, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q35", "type": "enumeration", "prompt": "عدد اجزاء المدقة، مع وصف كل جزء.", "answer": "تمثل الاجزاء الانثوية في الزهرة وتتألف من ثلاثة اجزاء هي:\nهو جزء المدقة القاعدي الذي يتمثل بتركيب منتفخ تتكون بداخله البويضات (Ovules) المرتبطة بجدار المبيض عن طريق عنق قصير يسمى بالحبل السري (Funiculus).\nيتمثل بتركيب اسطواني رفيع ومجوف عادة يربط المبيض بالجزء العلوي الذي يدعى الميسم.\nيمثل الجزء النهائي او القمي من المدقة ويكون منتفخاً قليلاً وفي اغلب الاحيان يكون ذو اهداب او خشن الملمس واحياناً مغطى بسائل لزج لتسهيل عملية التصاق حبوب اللقاح عليه ولابد من الاشارة الى ان الاجزاء الزهرية المشار اليها في اعلاه لاتتمثل في جميع النباتات الزهرية فهناك اختلاف في ازهار النباتات ذوات الفلقة الواحدة عن تلك من ذوات الفلقتين فضلاً عن وجود تباينات ضمن المجموعة الواحدة فيما يخص تركيب الزهرة والجدولين (3-1، 3-2) يوضحان بعض اوجه التباين المشار اليها في اعلاه.", "page": 108, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q36", "type": "enumeration", "prompt": "عدد مراحل تكوين الجنين في نبات من ذوات الفلقتين.", "answer": "(أ) مرحلة تكوين الزيجة (Zygote Stage)\nيحصل في هذه المرحلة اخصاب مزدوج ينتج عنه تكوين الزيجة والسويداء.\n(ب) مرحلة الجنين الاولي (Proembryo Stage)\nيكون الجنين الاولي متعدد الخلايا وجزئه القاعدي او الوظيفي يكون معلقاً وظيفياً (معلق).\n(ج) مرحلة التكور (Globular Stage)\nيظهر الجنين في هذه المرحلة بشكل كرة صغيرة.\n(د) مرحلة القلب (Heart Stage)\nيكون الجنين بشكل القلب وتظهر الفلقتان.\n(هـ) مرحلة الطوربيد (Torpedo Stage)\nيكون الجنين بشكل الطوربيد (اقرب من الشكل الاسطواني)، وتكون الفلقتان بشكل واضح.\n(و) مرحلة الجنين الناضج (Mature Embryo Stage)\nينضج الجنين حيث يأخذ بالنمو والتمايز الى جنين حقيقي مكون من محور جنيني يتكون من الرويشة والجذير والسويق الفلقي الذي يحمل فلقتين (فلقة واحدة في نباتات ذوات الفلقة الواحدة).\nشكل (3-18). التكوين الجنيني لنبات من ذوات الفلقتين.", "page": 114, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q37", "type": "enumeration", "prompt": "عدد طبقات الثمرة الثلاث.", "answer": "1- الطبقة الخارجية (Exocarp)، ويمكن ان يطلق عليها بالجلد (Skin) او الغطاء.\n2- الطبقة الوسطى (Mesocarp)، ويطلق عليها ايضاً الجزء الطري (Flesh).\n3- الطبقة الداخلية (Endocarp)، ويطلق عليها النواة (Pit).", "page": 117, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q38", "type": "enumeration", "prompt": "عدد اجزاء الجهاز التناسلي الذكري في الحشرات.", "answer": "يتألف الجهاز التناسلي الذكري (شكل 3-33) من الاجزاء والتراكيب التالية:\nخصيتين تقعان فوق القناة الهضمية او على جانبيها والخصية في الحشرات مكونة من مجموعة نبيبات دقيقة تسمى النبيبات المنوية.\nتفتح النبيبات المنوية في قناة صغيرة على نفس الجانب تعرف بالقناة الناقلة للحيامن (Vas Deferens)، وتتصل مقدمة القناة الناقلة للحيامن بالخصية ومؤخرتها بالحويصلة المنوية (Seminal Vesicle) والتي تمثل منطقة متسعة من القناة الناقلة.\nتتحد القناتان الناقلتان للحيامن لتكونان القناة القاذفة (Ejaculatory Duct)، التي تمتد الى القضيب (Penis)، والذي يفتح في نهايته بالفتحة التناسلية التي تطلق منها النطف او الحيامن.\nوالغدد المساعدة (Accessory Glands)، وتفتحان عند بداية القناة القاذفة، وهما تفرزان سائلاً مخاطياً يحيط بالنطف ويشكل تركيب كيسي حولها يدعى كيس النطف.", "page": 119, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q39", "type": "enumeration", "prompt": "عدد اعضاء التكاثر في الجهاز التناسلي الذكري في الانسان ووظيفة كل منها.", "answer": "1. الخصية (2) تقع في كيس الصفن (Scrotum) وهما تتدليان كزائدة من الجسم من اجل الحفاظ على درجة حرارة مناسبة لتكوين النطف. الوظيفة: تنتج النطف والهورمونات الجنسية.\n2. البربخ (2) (Epididymis). الوظيفة: تنضج فيه النطف وهو يمثل موقع خزن النطف.\n3. القناة الناقلة للحيامن (2) (Vas Deferens). الوظيفة: تقوم بالنقل السريع للنطف كما تقوم بخزن النطف.\n4. القناة القاذفة (1) (Ejaculatory Duct). الوظيفة: توصيل النطف الى القضيب.\n5. القضيب (1) (Penis). الوظيفة: عضو الجماع.", "page": 125, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "ch3-q40", "type": "enumeration", "prompt": "عدد مراحل الدورة المبيضية.", "answer": "أ- مرحلة تكون الحوصلة البدائية، حيث تحوي سليفة البيضة التي تكون ثنائية المجموعة الكروموسومية، وتبدأ فيها عملية الانقسام الاختزالي الاول.\nب- مرحلة تكون الحوصلة الاولية حيث تبدأ المنطقة الشفافة (Zona Pellucida) بالتكون حول البيضة.\nج- مرحلة الحوصلة الثانوية ويظهر فيها تجويف الحوصلة المليء بافرازات من الخلايا الحوصلية وبعض مكونات بلازما الدم وبروتينات وغير ذلك.\nد- مرحلة الحوصلة الناضجة وفيها تنضج الحوصلة وتكتمل عملية الانقسام الاختزالي الاول، وتتكون خلية بيضية ثانوية وجسم قطبي اول.\nهـ- مرحلة الاباضة (Ovulation) وفيها تتمزق حوصلة البيضة وتتحرر الخلية البيضية الثانوية والجسم القطبي الاول.\nو- مرحلة تكون الجسم الاصفر (Corpus Luteum) من بقايا الحوصلة الممزقة. (يتحلل الجسم الاصفر عندما لايحصل حمل عند المرأة).", "page": 130, "chapter": 3, "chapterTitle": "التكاثر"}, {"id": "c4-01", "type": "blank", "prompt": "قطر بيضة الانسان لايتجاوز _____ مايكروميتر.", "answer": "100", "page": 141, "terms": ["100"], "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-02", "type": "blank", "prompt": "العالم الذي اسس علم الاجنة الوصفي هو _____.", "answer": "ارسطو", "page": 145, "terms": ["ارسطو"], "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-03", "type": "blank", "prompt": "تنسب نظرية التكوين التراكمي الى العالم _____.", "answer": "وولف", "page": 146, "terms": ["وولف"], "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-04", "type": "blank", "prompt": "حصل سبيمان على جائزة نوبل عام (_____م).", "answer": "1935", "page": 147, "terms": ["1935"], "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-05", "type": "blank", "prompt": "تسمى كرة الخلايا الناتجة من تكرار التفلجات _____.", "answer": "الاريمة", "page": 148, "terms": ["الاريمة"], "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-06", "type": "blank", "prompt": "اعلن العالم ايان ولموت استنساخ النعجة دوللي عام (_____م).", "answer": "1997", "page": 156, "terms": ["1997"], "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-07", "type": "blank", "prompt": "تؤخذ خلايا الحبل السري الجذعية من _____ الحبل السري.", "answer": "دم", "page": 155, "terms": ["دم"], "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-08", "type": "choice", "prompt": "اي طرق النمو مثالها نمو الخلايا العصبية؟", "answer": "نمو الخلايا المفردة", "page": 142, "options": ["النمو الخلالي", "التكاثر الخلوي", "نمو الخلايا المفردة", "التفلج"], "correctIndex": 2, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-09", "type": "choice", "prompt": "اي مستوى تعضٍّ يتضح في مستعمرة الفولفكس؟", "answer": "المستوى الخلوي للتعضي", "page": 143, "options": ["المستوى الخلوي للتعضي", "المستوى البروتوبلازمي للتعضي", "مستوى الجهاز العضوي", "مستوى الانسجة المتعضية"], "correctIndex": 0, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-10", "type": "choice", "prompt": "من بين ان تكوين الفرد الجديد يتطلب وجود امشاج ذكرية وانثوية؟", "answer": "سبالانزاني", "page": 146, "options": ["فون بير", "سبالانزاني", "روكس", "بونت"], "correctIndex": 1, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-11", "type": "choice", "prompt": "من اول من قام بتجربة على بيضة الضفدع في مرحلة التفلج الاول؟", "answer": "روكس", "page": 147, "options": ["دي كراف", "ليفنهوك", "روكس", "ارسطو"], "correctIndex": 2, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-12", "type": "choice", "prompt": "ما اسم القرص الخلوي المستقر على احد اقطاب البيضة في الزواحف والطيور؟", "answer": "قرص جرثومي", "page": 148, "options": ["المعيدة", "قزم جنيني", "المناسل", "قرص جرثومي"], "correctIndex": 3, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-13", "type": "choice", "prompt": "اي التوائم تتكون من بيضة مخصبة واحدة بحيوان منوي واحد؟", "answer": "التوائم المتطابقة", "page": 152, "options": ["التوائم الاخوية", "التوائم المتطابقة", "التوائم المتعددة", "التوائم الطفيلية"], "correctIndex": 1, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-14", "type": "choice", "prompt": "اي الخلايا الجذعية تمتلك قابلية انقسامية غير محدودة؟", "answer": "الخلايا الجذعية الجنينية", "page": 155, "options": ["الخلايا الجذعية الجنينية", "الخلايا الجذعية البالغة", "خلايا الحبل السري الجذعية", "الخلايا المتخصصة"], "correctIndex": 0, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-15", "type": "definition", "prompt": "عرف النمو.", "answer": "يعرف النمو بأنه الزيادة الحاصلة في حجم ووزن الخلايا المكونة للكائن الحي، وحيث ان الانسجة تتكون من عدد هائل من الخلايا الحية يكون لها دور اساس في عملية النمو، ويكون نمو الخلايا بأحد الطرق التالية:", "page": 142, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-16", "type": "definition", "prompt": "عرف التمايز الخلوي.", "answer": "يعرف التمايز الخلوي بأنه قدرة الخلايا الجنينية في المراحل المبكرة من التكوين الجنيني او النماء على اكتساب المقدرة الوظيفية، ويقصد هنا بالمقدرة الوظيفية الخاصة بالخلية او مجموعة الخلايا التي لايمكن للخلايا الاخرى ان تقوم بها، وعلى سبيل المثال عملية التقلص في الخلايا او الالياف العضلية تمثل سمة وظيفية مميزة للخلايا العضلية لاتستطيع غيرها القيام بها وكذلك عملية الافراز التي تحصل في الخلايا الغدية.", "page": 142, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-17", "type": "definition", "prompt": "عرف التكوين الجنيني او النماء.", "answer": "يعرف التكوين الجنيني او النماء بأنه: عملية تكوين الفرد من خلية واحدة تمثل البيضة المخصبة (Zygote) لحين اكتمال تكوينه ليصبح عديد الخلايا معقد التركيب شبيها بابويه.", "page": 144, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-18", "type": "definition", "prompt": "عرف علم الاجنة.", "answer": "وعلم الاجنة (Embryology) هو العلم الذي يبحث في دراسة مراحل التكوين الجنيني (Development) بضمنها النمو (Growth) والتمايز (Differentiation).", "page": 145, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-19", "type": "definition", "prompt": "عرف التفلج.", "answer": "هو سلسلة من الانقسامات الخيطية (الاعتيادية) المتكررة التي تبدأ من البيضة المخصبة حيث تنقسم الى خليتين (فلجتين) (Blastomeres) ثم اربع فلجات ثم الى ثمان فلجات وبتكرار الانقسامات تتحول البيضة المخصبة الى كرة من الخلايا تدعى الاريمة (Blastula) تكون جوفاء سمكها خلية واحدة في حيوان الرميح الذي هو من الحبليات الاولية، او كرة نصف جوفاء سمكها عدة خلايا كما في البرمائيات (الضفدع)، او تصبح مجموعة من الخلايا على شكل قرص جرثومي (Blastodisc) مستقر على احد اقطاب البيضة كما في الزواحف والطيور.", "page": 148, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-20", "type": "definition", "prompt": "عرف التمعد.", "answer": "وهي عملية تنظم الخلايا نتيجة للحركات المكونة للشكل (Morphogenetic Movements) فيصبح الجنين في هذه المرحلة بشكل تركيب خلوي معقد يدعى (المعيدة) (Gastrula) يكون ثنائي الطبقات الجرثومية في اجنة اللافقريات والحبليات الاولية، حيث يتكون الجنين فيها من طبقتي الاديم الظاهر (Ectoderm) والاديم المتوسط الباطن (Mesentoderm)، كما تكون المعيدة ثلاثية الطبقات في اجنة الحبليات الاخرى حيث تتكون اجنتها من طبقة الاديم الظاهر (Ectoderm) والاديم المتوسط (Mesoderm) والاديم الباطن (Endoderm).", "page": 148, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-21", "type": "definition", "prompt": "عرف الاخصاب الصناعي.", "answer": "يمثل الاخصاب الصناعي عملية نقل الحيوانات المنوية بعد تنقيتها وتركيزها في المختبر الى البويضات، ويستعمل هذا الاخصاب في حالات عديدة من اهمها:", "page": 158, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-22", "type": "comparison", "prompt": "قارن بين النمو الخلالي ونمو الخلايا المفردة.", "answer": "2. النمو الخلالي أو البيني، ويقصد بهذا النوع من النمو بأنه النمو الحاصل من زيادة المواد بين الخلوية التي تدخل في بناء الانسجة كالياف الانسجة الضامة والمواد البينية، ومثال ذلك النمو الذي يحصل في الغضروف الزجاجي حيث تنمو خلاياه وتتمايز الى خلايا غضروفية بالغة تقوم بأفراز مواد خلالية (بينية) تشكل المادة الاساس للنسيج الغضروفي الزجاجي وهي تتمثل ببروتين غضروفي مخاطي (Chondromucoprotein) وهكذا فأن الغضروف ينمو بأزدياد مواده الخلالية (البينية).\n3. نمو الخلايا المفردة، وهو نوع نادر الحدوث حيث يحصل فيه نمو في حجم الخلايا، ومثال ذلك نمو الخلايا العصبية حيث انها تزداد في الحجم اضعاف حجمها الاصلي، ويرجع ذلك الى زيادة حجم السايتوبلازم عن طريق تكوين عضيات جديدة وكذلك نمو التشجرات (Dendrites) في الخلية العصبية الذي يزيد من المساحة السطحية للخلية.", "page": 142, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-23", "type": "comparison", "prompt": "قارن بين المستوى البروتوبلازمي والمستوى الخلوي للتعضي.", "answer": "يتضح التعضي البروتوبلازمي في الاحياء وحيدة الخلية مثل الطليعيات، وفيها تنحصر جميع الوظائف الحيوية داخل حدود الخلية الواحدة التي تمثل الوحدة الاساسية للحياة. وتتميز في بروتوبلازم الخلية عضيات قادرة على اداء الوظائف المتخصصة.\nنعني بالتعضي الخلوي ان هناك مجموعة من الخلايا المتمايزة وظيفيا. ويتضح في هذه المرتبة من التعضي تقسيم في العمل اذ تختص بعض الخلايا بالتكاثر والبعض الاخر بالتغذية كما هو الحال في مستعمرة الفولفكس.", "page": 143, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-24", "type": "comparison", "prompt": "قارن بين نظرية قبل التشكل ونظرية التكوين التراكمي.", "answer": "افترض بعض مؤيدي هذه النظرية وجود جنين مصغر داخل البيضة يدعى قزم جنيني (Homunculus) وان اجزاءه تكبر عند التنبيه بالسائل المنوي، وقد تعزز موقف هؤلاء العلماء عندما اوضح العالم بونت (Bonnet) عام (1745م) قابلية بيوض بعض الحشرات مثل حشرة (المن) على النمو عذريا من دون اخصاب بعملية التكوين العذري (Parthenogenesis)، في حين افترض القسم الآخر من مؤيدي نظرية قبل التشكيل ان القزم الجنيني يوجد في رأس النطفة حيث زعموا انهم شاهدوا هذا القزم باستعمال مجهر ليفنهوك داخل رأس الحيوان المنوي (شكل 4-2).\nتفترض هذه النظرية ان الجنين يتكون من مادة حبيبية داخل البيضة تعاني تغيرات متحولة تدريجيا الى جنين وتنسب هذه النظرية الى العالم وولف (wolff).", "page": 146, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-25", "type": "comparison", "prompt": "قارن بين مرحلتي التمايز والتعضي.", "answer": "يتحدد مصير الخلايا في هذه المرحلة لتسلك اتجاهات معينة في عملية التكوين الجنيني فيحدث تمايزا في شكل الخلايا يتناسب مع نوعية الوظيفة التي تؤديها الخلايا، فالخلايا العصبية تختص بنقل السيالات العصبية لذا يحدث فيها تمايز نسيجي (Histological Differentiation) يتمثل بأمتلاكها آلية اداء الوظيفة من خلال المحور (Axon) والتشجرات (Dendrites).\nوهي مرحلة نمو الجنين وانتظام خلاياه بشكل انسجة والانسجة على شكل اعضاء وذلك من خلال حدوث التمايز العضوي خلال فترة التكوين الجنيني حيث تتميز الطبقات الجرثومية الثلاث الى اربعة انواع رئيسة من الانسجة وهي الظهارية، والضامة، والعضلية، والعصبية.", "page": 149, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-26", "type": "comparison", "prompt": "قارن بين التوائم الاخوية والمتطابقة.", "answer": "تتكون التوائم في هذا النوع من بيضتين منفصلتين تنطلقان من المبيض في نفس الوقت وتخصب كل واحدة بحيوان منوي. لاتظهر التوائم الاخوية تشابها وقد تكون اجناسها متشابهة (جميعها ذكور او جميعها اناث)، او تكون مختلفة (الشكل 4-10).\nتتكون التوائم المتطابقة (المتماثلة) من بيضة مخصبة واحدة بحيوان منوي واحد، وتنقسم هذه البيضة المخصبة الى خليتين وتواصل كل خلية نموها وتكوين جنين كامل (الشكل 4-11). تتشابه التوائم المتطابقة بدرجة كبيرة في الشكل والجنس (تكون اما ذكور او اناث).", "page": 152, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-27", "type": "comparison", "prompt": "قارن بين الخلايا الجذعية الجنينية والخلايا الجذعية البالغة.", "answer": "هي نوع اساسي من انواع الخلايا الجذعية فهي تمتلك قابلية انقسامية غير محدودة، وتكون ذات قدرة عالية على التخصص لانواع من الخلايا فهي تستطيع اصلاح واستبدال الخلايا التالفة عند زراعتها في العضو المصاب، ويمكن الحصول عليها من المراحل الجنينية المبكرة بعد الاخصاب، وهي تعد مصدرا مهما للعديد من الانجازات الطبية بسبب صفاتها تلك.\nتوجد هذه الخلايا مع الخلايا المتخصصة في الجسم وتتضمن وظيفتها استبدال وتعويض الخلايا المتضررة او الميتة في الجسم لكنها تختلف عن الخلايا الجذعية الجنينية بما يلي:\nأ. وجودها بكمية قليلة مما يؤدي الى صعوبة عزلها.\nب. يقل عددها مع تقدم العمر.\nج. قد تكون غير سليمة.\nد. ليس لها نفس قدرة الخلايا الجذعية الجنينية (في الانقسام والتخصص).", "page": 155, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-28", "type": "comparison", "prompt": "قارن بين تجميد الاجنة وتجميد البويضة.", "answer": "يتم استخدام هذه التقانة في مراكز الاخصاب الخارجي (اطفال الانابيب) وذلك من خلال تجميد الاجنة الفائضة عن الحاجة بعد اختيار الاجنة المناسبة ونقلها الى رحم الام، وذلك لغرض استعمالها مستقبلا اذا رغب الابوان لحمل آخر لان برنامج الاخصاب عن طريق اطفال الانابيب مكلف اقتصاديا ويحتاج الى استعداد نفسي وصحي، كما ويتم تجميد الاجنة باستخدام النتروجين السائل (−170C) في مراكز علمية خاصة بذلك.\nتتضمن هذه التقانة تجميد اجزاء من المبيض تحتوي على بويضات غير ناضجة في النتروجين السائل (−170C)، وتكون نسبة نجاحها اقل من نسب نجاح تجميد الاجنة لان التجميد قد يؤثر على كروموسومات البويضة. تساعد هذه التقانة احتفاظ المرأة بخصوبتها خاصة اللواتي تعرضن للاشعاعات او العلاجات الكيميائية او امراض معينة.", "page": 159, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-29", "type": "enumeration", "prompt": "عدد طرق نمو الخلايا.", "answer": "1. النمو بطريقة التكاثر الخلوي أو مضاعفة الخلايا، ويتم عن طريق تكوين خلايا جديدة من خلال عملية الانقسام.\n2. النمو الخلالي أو البيني، ويقصد بهذا النوع من النمو بأنه النمو الحاصل من زيادة المواد بين الخلوية التي تدخل في بناء الانسجة كالياف الانسجة الضامة والمواد البينية، ومثال ذلك النمو الذي يحصل في الغضروف الزجاجي حيث تنمو خلاياه وتتمايز الى خلايا غضروفية بالغة تقوم بأفراز مواد خلالية (بينية) تشكل المادة الاساس للنسيج الغضروفي الزجاجي وهي تتمثل ببروتين غضروفي مخاطي (Chondromucoprotein) وهكذا فأن الغضروف ينمو بأزدياد مواده الخلالية (البينية).\n3. نمو الخلايا المفردة، وهو نوع نادر الحدوث حيث يحصل فيه نمو في حجم الخلايا، ومثال ذلك نمو الخلايا العصبية حيث انها تزداد في الحجم اضعاف حجمها الاصلي، ويرجع ذلك الى زيادة حجم السايتوبلازم عن طريق تكوين عضيات جديدة وكذلك نمو التشجرات (Dendrites) في الخلية العصبية الذي يزيد من المساحة السطحية للخلية.", "page": 142, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-30", "type": "enumeration", "prompt": "عدد ما تشمله مرحلة تكوين الخلايا الجنسية والاخصاب.", "answer": "أ. نشأة المناسل (Gonads) وتكوين الخلايا الجنسية فيها حيث تتكون الانثوية (البيضة Ovum) والذكرية (الحيوان المنوي Sperm).\nب. انتاج الخلايا الجنسية عند اكتمال النمو الجنسي للفرد (النضج الجنسي).\nج. اتحاد البيضة بالحيوان المنوي بعملية الاخصاب وانتاج البيضة المخصبة (Zygote).", "page": 148, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-31", "type": "enumeration", "prompt": "اذكر مجموعتي العوامل المؤدية الى التشوهات الخلقية.", "answer": "1. العوامل الوراثية بضمنها شذوذ الكروموسومات الجسمية ومنها التشوه المسبب لمتلازمة داون (Down Syndrome) الذي يظهر تشوه في ملامح الوجه وحدوث تخلف عقلي وتشوهات في القلب.\n2. العوامل البيئية او الخارجية وتتضمن عوامل عديدة اهمها تأثير الاشعاع الذي يسبب تشوهات عديدة ابرزها تشوهات الجهاز العصبي. وان التعرض المباشر للاشعاع يسبب حدوث تشوهات خلقية في الاجيال اللاحقة. علاوة على ان التعرض للاشعاع يؤثر على الانجاب مسببا العقم الجزئي او الكلي معتمدا في ذلك على جرعة الاشعاع وزمن التعرض للاشعاع وعمر الشخص.", "page": 149, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-32", "type": "enumeration", "prompt": "عدد الامور التي يجب على الام الوقاية منها حتى لاتؤثر في الجنين كما وردت في الكتاب.", "answer": "1. الابتعاد عن التدخين لانه يؤثر في وزن الطفل فهو يؤدي الى انخفاض نسبة الاوكسجين وارتفاع نسبة اول اوكسيد الكاربون في دم الام ودم الجنين والمشيمة مما يولد بيئة غير صحية للجنين علاوة على ان التدخين يزيد من حدوث الاجهاض والولادة المبكرة او موت الجنين، ويمتد تأثير التدخين الى مابعد ولادة الجنين مسببا التهابات المجاري التنفسية والربو وغيرها في الاطفال.\n2. التقليل من اخذ الكافايين الموجود في القهوة لان كثرته تسبب الاذى للجنين.\n3. تجنب اخذ الادوية الشعبية والاعشاب وماشابه ذلك دون استشارة المختصين.\n4. الكحول يؤثر في الجنين وقد يسبب له الخلل العصبي والتشوهات الجسمية خصوصا في الوجه اضافة الى حدوث اضطرابات في السلوك، ويسبب الكحول متلازمة الكحول الجنيني (Fetal Alcohol Syndrome) التي تظهر في المجتمعات الاوربية.\n5. تجنب اصابة الام بمرض داء القطط (المقوسات Toxoplasmosis) لانه يسبب تشوهات خطرة على الجنين، وذلك من خلال طهي اللحم جيدا وعدم التعرض الى براز القطط.\n6. على الحامل تناول حبوب حامض الفوليك (Folic Acid) خلال فترة الحمل لانه يقلل من تشوهات الانبوب العصبي وعليها علاج كافة الامراض كالسكري وارتفاع ضغط الدم والصرع تحت اشراف طبي دقيق.", "page": 150, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-33", "type": "enumeration", "prompt": "عدد اختلافات الخلايا الجذعية البالغة عن الجنينية.", "answer": "أ. وجودها بكمية قليلة مما يؤدي الى صعوبة عزلها.\nب. يقل عددها مع تقدم العمر.\nج. قد تكون غير سليمة.\nد. ليس لها نفس قدرة الخلايا الجذعية الجنينية (في الانقسام والتخصص).", "page": 155, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-34", "type": "enumeration", "prompt": "عدد خطوات استنساخ دوللي التي اتبعها ايان ولموت وجماعته.", "answer": "1. تم اخذ خلايا من الغدد اللبنية (الضرع) لنعجة بالغة بعمر ست سنوات. ووضعت الخلايا في وسط زرعي، وقد تم تحضير الوسط الزرعي بصيغة تحفظ نوى الخلايا في حالة مستقرة.\n2. تم اخذ بويضات (خلية بيضة ناضجة) من نعجة اخرى وازيلت انويتها (فرغت من انويتها).\n3. حصلت عملية دمج للخلية المعطية (خلية الغدة اللبنية) مع الخلية المفرغة من نواتها بوساطة وضع الخليتين معا وتعريضهما لنبضة كهربائية ادت الى ادماجهما، كما ادت نبضة كهربائية اخرى الى تنشيط البيضة لبدء عملية التكوين الجنيني.\n4. تم نقل الاجنة الناتجة الى رحم نعجة اخرى.\n5. بعد انقضاء فترة الحمل والتي مداها خمسة اشهر ولدت النعجة دوللي (Dolly) وهي تشبه تماما النعجة التي اخذت من ضرعها الخلية الجسدية.\n6. تحليل الحامض النووي منقوص الاوكسجين (DNA) اكد ان نوى خلايا النعجة دوللي مشتقة او ناتجة من نفس نواة الخلية المعطية.", "page": 156, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c4-35", "type": "enumeration", "prompt": "عدد اهم الحالات التي يستعمل فيها الاخصاب الصناعي.", "answer": "1. وجود اسباب تتعلق في عملية التبويض او قناتي البيض او بطانة الرحم في الانثى.\n2. وجود اسباب تتعلق بالجهاز التناسلي الذكري تؤدي الى قلة نسبة الحيوانات المنوية مما يحدث خللا في عملية اخصاب البويضة، كما تشير الدراسات الى ان تناول الكحول والتدخين يقللان من انتاج الحيوانات المنوية وحيويتها.\n3. وجود خلل هورموني يؤثر في عملية انتاج البيوض والحيوانات المنوية.\n4. اسباب مكتسبة نتيجة التعرض الى حوادث معينة او اجراء جراحات معينة او استعمال بعض العقاقير او التعرض الى الاشعاع.", "page": 158, "chapter": 4, "chapterTitle": "التكوين الجنيني"}, {"id": "c5-1", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: يعرف ........ (Genetics) بأنه ذلك الفرع من علم الحياة الذي يهتم بدراسة التغايرات الموروثة لكائن حي أو لمجموعة من الكائنات وكذلك كيفية تعبير المورثات المسؤولة عن تلك التغايرات.", "answer": "يعرف علم الوراثة (Genetics) بأنه ذلك الفرع من علم الحياة الذي يهتم بدراسة التغايرات الموروثة لكائن حي أو لمجموعة من الكائنات وكذلك كيفية تعبير المورثات المسؤولة عن تلك التغايرات.", "page": 165, "terms": ["علم الوراثة"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-2", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: 1. .........", "answer": "1. قصر دورة حياته.", "page": 170, "terms": ["قصر دورة حياته"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-3", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: ........: رسم هندسي يشبه رقعة الشطرنج توضع في يساره وبصورة عمودية الأمشاج الذكرية بينما توضع في أعلاه وبصورة أفقية الأمشاج الأنثوية أو بالعكس، الشكل (5–8).", "answer": "مربع بونيت: رسم هندسي يشبه رقعة الشطرنج توضع في يساره وبصورة عمودية الأمشاج الذكرية بينما توضع في أعلاه وبصورة أفقية الأمشاج الأنثوية أو بالعكس، الشكل (5–8).", "page": 178, "terms": ["مربع بونيت"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-4", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: هي وجود بدائل أو حلائل أو أليلات مختلفة لنفس المورثة تحدث نتيجة لعملية الطفرة الحاصلة في جزيء المادة الوراثية DNA والتي تؤدي إلى حصول تغاير في المظهر، علماً بأنها تحتل ........ على الكروموسوم المعين. ومن الأمثلة على الصفات متعددة الأليلات ما يأتي:", "answer": "هي وجود بدائل أو حلائل أو أليلات مختلفة لنفس المورثة تحدث نتيجة لعملية الطفرة الحاصلة في جزيء المادة الوراثية DNA والتي تؤدي إلى حصول تغاير في المظهر، علماً بأنها تحتل نفس الموقع الوراثي على الكروموسوم المعين. ومن الأمثلة على الصفات متعددة الأليلات ما يأتي:", "page": 194, "terms": ["نفس الموقع الوراثي"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-5", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: 2. rRNA الرايبي الرايبوسومي (Ribosomal RNA): وهو جزء من تركيب ........ حيث يشترك مع البروتين في تكوينها.", "answer": "2. rRNA الرايبي الرايبوسومي (Ribosomal RNA): وهو جزء من تركيب الرايبوسومات حيث يشترك مع البروتين في تكوينها.", "page": 216, "terms": ["الرايبوسومات"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-6", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: الشفرة الوراثية (Genetic code): تشير إلى تتابع القواعد النتروجينية في الـ mRNA، حيث إن ثلاث نيوكليوتيدات متجاورة تمثل ........ وتحدد حامضاً أمينياً أو تشير إلى بداية (Initiation) أو إيقاف (Stop) الترجمة.", "answer": "الشفرة الوراثية (Genetic code): تشير إلى تتابع القواعد النتروجينية في الـ mRNA، حيث إن ثلاث نيوكليوتيدات متجاورة تمثل كودون وتحدد حامضاً أمينياً أو تشير إلى بداية (Initiation) أو إيقاف (Stop) الترجمة.", "page": 216, "terms": ["كودون"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-7", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: 1. تفصل إنزيمات ........ (Helicase) سلسلتي الـ DNA حيث تنتقل هذه الإنزيمات على طول هذا الجزيء لغرض فك الأواصر الهيدروجينية بين القواعد المتممة. تنتج عن انفصال هاتين السلسلتين منطقة تشبه شكل الحرف Y والتي يطلق عليها شوكة التضاعف (Replication fork)، شكل (5–39).", "answer": "1. تفصل إنزيمات الهيليكيز (Helicase) سلسلتي الـ DNA حيث تنتقل هذه الإنزيمات على طول هذا الجزيء لغرض فك الأواصر الهيدروجينية بين القواعد المتممة. تنتج عن انفصال هاتين السلسلتين منطقة تشبه شكل الحرف Y والتي يطلق عليها شوكة التضاعف (Replication fork)، شكل (5–39).", "page": 217, "terms": ["الهيليكيز"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-8", "type": "blank", "prompt": "املأ الفراغ بما يناسبه: هي ........ تستخدم للتعرف على تتابعات معينة من القواعد النتروجينية لجزيء الـ DNA وتقطعها (شكل 5–42)، كما تعمل هذه الإنزيمات على كسر الآصرة الفوسفاتية الداخلية للـ DNA.", "answer": "هي بروتينات بكتيرية تستخدم للتعرف على تتابعات معينة من القواعد النتروجينية لجزيء الـ DNA وتقطعها (شكل 5–42)، كما تعمل هذه الإنزيمات على كسر الآصرة الفوسفاتية الداخلية للـ DNA.", "page": 222, "terms": ["بروتينات بكتيرية"], "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-9", "type": "choice", "prompt": "أول من أطلق مصطلح Genetics على علم الوراثة هو:", "answer": "إن أول من أطلق مصطلح (Genetics) على هذا العلم هو الباحث الإنكليزي بيتسون (Bateson) عام (1906م). وفيما يلي نبذة تاريخية مختصرة عن أهم الدراسات الوراثية التي ساعدت في تقدم هذا العلم:", "page": 165, "options": ["بيتسون", "مندل", "وايزمان", "كريك"], "correctIndex": 0, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-10", "type": "choice", "prompt": "المستضدان A وB يظهران معاً على خلايا دم الفرد ذي المجموعة:", "answer": "AB: المستضدان A، B؛ الطراز الوراثي IᴬIᴮ.", "page": 195, "options": ["A", "B", "AB", "O"], "correctIndex": 2, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-11", "type": "choice", "prompt": "في التهجين الأحادي بين فردين هجينين مع سيادة تامة تكون النسبة المظهرية المتوقعة:", "answer": "لاحظ سهولة استخراج النسبة الوراثية (1:2:1) والنسبة المظهرية (3:1) لأفراد الجيل الثاني في التهجين الوارد في الشكل (5–8).", "page": 178, "options": ["1:1", "3:1", "1:2:1", "9:3:3:1"], "correctIndex": 1, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-12", "type": "choice", "prompt": "أي قاعدة نتروجينية توجد في RNA فقط؟", "answer": "3. اليوراسيل (Uracil، U) يوجد في الـ RNA فقط.", "page": 214, "options": ["الثايمين", "الأدنين", "الكوانين", "اليوراسيل"], "correctIndex": 3, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-13", "type": "choice", "prompt": "الأليل المميت في الفئران الصفراء يكون في الحالة النقية:", "answer": "مثال (3): الأليل السائد للفئران الصفراء: وهذه تشبه الحالة السابقة، فعند تضريب فئران صفراء هجينة مع بعضها ينتج موت ربع الأجنة الصفراء والتي هي نقية في الأليل المميت YY مما يؤدي إلى تحور النسبة المظهرية 3:1 إلى 2/3 صفراء هجينة:1/3 رمادية. إذن الفئران الصفراء تكون دائماً هجينة أي حاملة للجين المميت ولكنها غير متأثرة به. وللجين المميت أهمية في تصميم بعض التجارب الوراثية وفيما يلي تضريب لفردين هجينين لهذا الأليل المميت:", "page": 191, "options": ["Yy", "yy", "YY", "RhRh"], "correctIndex": 2, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-14", "type": "choice", "prompt": "الأنزيم الذي يربط الثغرات أثناء تضاعف DNA هو:", "answer": "لاحظ من اتجاه السهمين في هذا الشكل وعند شوكة التضاعف بأن بناء الـ DNA يكون باتجاه معاكس في كل سلسلة مما يؤدي ذلك إلى إحداث ثغرات في السلسلة التي يتم بناؤها حديثاً غير أن هذه الثغرات تربط فيما بينها بوساطة أنزيم لاحم يطلق عليه (DNA Ligase).", "page": 217, "options": ["Helicase", "DNA Ligase", "RNA Polymerase", "Eco RI"], "correctIndex": 1, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-15", "type": "choice", "prompt": "كودون البدء في mRNA هو:", "answer": "1. طور البدء (Initiation): يرتبط الـ tRNA مع mRNA والوحدتين البنائيتين للرايبوسوم بعضها مع البعض الآخر. وترتبط جزيئات معينة لحامض أميني ميثيونين عند إحدى طرفي الـ tRNA وذلك وفقاً لكودون البدء AUG في الـ mRNA والذي يزدوج بالكودون المضاد UAC في الطرف الآخر للـ tRNA، شكل (5–41). يعتبر الميثيونين الحامض الأميني الأول في جميع عديد الببتيد تقريباً غير أنه قد يزال لاحقاً.", "page": 220, "options": ["UAA", "UAG", "AUG", "UGA"], "correctIndex": 2, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-16", "type": "choice", "prompt": "عدد أزواج الكروموسومات الجسمية في الإنسان هو:", "answer": "يطلق على الكروموسومات التي ليس لها علاقة مباشرة بتعيين الجنس في الإنسان بالكروموسومات الجسمية (الجسدية) (Autosomes) وعددها 22 زوجاً أما الزوج المتبقي فهو كما نعلم يمثل كروموسومي الجنس (أي زوج واحد يعين الجنس).", "page": 208, "options": ["23", "22", "46", "21"], "correctIndex": 1, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-17", "type": "definition", "prompt": "عرّف الحليل (البديل) أو الأليل (Allele)؟", "answer": "هو إحدى حالات الطفرات المحتملة للعامل الوراثي (الجين) والذي يتميز عن الأليلات أو الحلائل الأخرى من خلال تأثيراته المظهرية. فإذن الأليل هو شكل آخر للجين أو متغاير الجين.", "page": 173, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-18", "type": "definition", "prompt": "عرّف التعبير الجيني (Gene expression)؟", "answer": "هي عملية استخدام معلومات الـ DNA من قبل الخلايا وذلك لتصنيع بروتين معين.", "page": 173, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-19", "type": "definition", "prompt": "عرّف الطراز الوراثي أو الجيني (Genotype، G)؟", "answer": "هو يعكس التركيب أو البنية الوراثية للفرد ويعبر عنه برموز وراثية وذلك للإشارة إلى اتحاد الأليلات في فرد معين.", "page": 173, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-20", "type": "definition", "prompt": "عرّف الطراز المظهري (Phenotype، P) أو الفئة المظهرية؟", "answer": "هو يشير إلى الخصائص أو العلامات المشاهدة للكائن الحي والمسيطر عليها وراثياً. فمثلاً صفتي طول الساق وقصره في نبات البزاليا يشار إليهما كتعبيرات طبيعية للمعلومات الموجودة في العوامل الوراثية.", "page": 173, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-21", "type": "definition", "prompt": "عرّف التهجين الأحادي (Monohybrid Cross)؟", "answer": "هو تهجين وراثي بين فردين ويتضمن زوج من الصفات المتضادة التي ترجع إلى نفس الموقع الوراثي (مثل AA × aa). وبذلك فهو يكشف عن كيفية انتقال طرز هذه الصفات عبر الأجيال.", "page": 175, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-22", "type": "definition", "prompt": "عرّف التضريب الرجعي (Back Cross)؟", "answer": "هو تضريب يجرى بين أفراد هجينة من الجيل الأول مع أحد الأبوين أو مع فرد يماثل أحدهما. ويمكن الرجوع إلى الفقرة السابقة (5.3.7) لملاحظة نتائج التضريب مع الأب المتنحي في الصفة. أما نتائج التضريب الرجعي مع الأب السائد النقي في الصفة فيمكن مشاهدته في هذا المثال:", "page": 180, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-23", "type": "definition", "prompt": "عرّف مربع بونيت (Punnett Square)؟", "answer": "مربع بونيت: رسم هندسي يشبه رقعة الشطرنج توضع في يساره وبصورة عمودية الأمشاج الذكرية بينما توضع في أعلاه وبصورة أفقية الأمشاج الأنثوية أو بالعكس، الشكل (5–8).", "page": 178, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-24", "type": "definition", "prompt": "عرّف الطفرات (Mutations)؟", "answer": "الطفرة هي تغير مفاجئ في تتابع القواعد النتروجينية لجين أو لجزء من الـ DNA، علماً بأن هذا التغير قد يكون مصحوباً بظهور طراز وراثي ومظهري جديد (شكل 5–27) وعلى مستوى نوعية الخلايا هناك طفرات تحدث في الخلايا التناسلية (Germ cells) والمتمثلة بأمشاج الكائن الحي، علماً أن طفرات الخلايا التناسلية لا تؤثر في الكائن الحي نفسه، إلا أنها يمكن أن تنتقل إلى أولاده. وهناك طفرات تحدث في الخلايا الجسمية (Somatic Cells) للكائن وبذلك تؤثر فيه، مثلاً بعض أنواع سرطان الجلد وسرطان الدم لدى الإنسان علماً أن هذا النوع من الطفرات لا يورث.", "page": 199, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-25", "type": "comparison", "prompt": "قارن بين الطراز الوراثي والطراز المظهري.", "answer": "هو يعكس التركيب أو البنية الوراثية للفرد ويعبر عنه برموز وراثية وذلك للإشارة إلى اتحاد الأليلات في فرد معين.\nهو يشير إلى الخصائص أو العلامات المشاهدة للكائن الحي والمسيطر عليها وراثياً. فمثلاً صفتي طول الساق وقصره في نبات البزاليا يشار إليهما كتعبيرات طبيعية للمعلومات الموجودة في العوامل الوراثية.", "page": 173, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-26", "type": "comparison", "prompt": "قارن بين DNA وRNA من حيث السكر والقواعد وعدد السلاسل.", "answer": "1. يحتوي الـ RNA على سكر الرايبوز C₅H₁₀O₅ بدلاً من سكر الرايبوز منقوص الأوكسجين C₅H₁₀O₄ الموجود في الـ DNA.\n2. يحتوي على القاعدة النتروجينية يوراسيل بدلاً من القاعدة ثايمين الموجودة في الـ DNA.\n3. يتكون عادة من سلسلة واحدة وليس من سلسلتين كما في الـ DNA. إلا أن بعض أجزاء الـ RNA قد تنثني ليصبح ثنائية السلسلة وفيها يرتبط اليوراسيل مع الأدنين والسايتوسين مع الكوانين.", "page": 216, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-27", "type": "comparison", "prompt": "قارن بين السيادة غير التامة والسيادة المشاركة.", "answer": "السيادة غير التامة (Incomplete dominance) وفيها يكون الطراز المظهري للفرد الهجين مختلفاً عن طرز الأبوين حيث يتخذ طرازاً وسطاً بينهما، أي بين الطرازين المظهريين لصفتين متضادتين نقيتين بسبب اختلاط تعبير الأليلين لهاتين الصفتين. وهذه الحالة تعتبر مختلفة عن حالة السيادة التامة للصفات التي درسها مندل.\nهي الحالة التي يتم فيها التعبير عن الأليلين معاً في الطراز المظهري للفرد الهجين. ففي هذا النوع من السيادة لا يحدث أي اختلاط بين الأليلين في الطراز المظهري، كما أن أياً منهما لا يكون سائد أو متنحياً.", "page": 187, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-28", "type": "comparison", "prompt": "قارن بين rRNA وtRNA من حيث الوظيفة.", "answer": "2. rRNA الرايبي الرايبوسومي (Ribosomal RNA): وهو جزء من تركيب الرايبوسومات حيث يشترك مع البروتين في تكوينها.\n3. tRNA الناقل (Transfer RNA): ويقوم بنقل الأحماض الأمينية إلى الرايبوسوم لبناء البروتين. حيث لوحظ أن الأحماض الأمينية ترتبط بهذا الحامض tRNA قبل أن يوصلها إلى الرايبوسوم.", "page": 216, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-29", "type": "comparison", "prompt": "قارن بين طفرة الحذف وطفرة الإضافة.", "answer": "طفرة الحذف: وفيها يتم فقد نيوكليوتيدة واحدة من جين معين. وقد يؤدي هذا الفقد إلى تشكيل غير صحيح للكودونات (Codons) المتبقية ويسمى هذا بطفرة الإزاحة (Frame shift mutation) وهي التي تؤدي إلى تغير جميع الأحماض الأمينية التي تقع بعدها (شكل 5–30). هذه الطفرة يمكن أن تؤدي إلى تأثيرات خطيرة في وظيفة البروتين.\n2. طفرة الإضافة (Insertion Mutation): ويتم فيها إدخال نيوكليوتيد واحد إلى جين معين مما قد يؤدي إلى طفرة الإزاحة أيضاً.", "page": 201, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-30", "type": "comparison", "prompt": "قارن بين التعدد الكروموسومي غير الحقيقي والتعدد الكروموسومي التام.", "answer": "أ. التعدد الكروموسومي غير الحقيقي (Aneuploidy) وفي هذه الحالة يوجد كروموسوم واحد مفقود (ثنائي المجموعة الكروموسومية – كروموسوم واحد) أو كروموسوم واحد زائد (ثنائي المجموعة الكروموسومية + كروموسوم واحد).\nب. تعدد كروموسومي تام (Polyploidy) وهو زيادة مجموعة كروموسومية كاملة فيكون الفرد ثلاثي المجموعة الكروموسومية.", "page": 200, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-31", "type": "comparison", "prompt": "قارن بين التضريب الاختباري والتضريب الرجعي من حيث الغرض والأبوين.", "answer": "إن الهدف من هذا التضريب هو التعرف على الطراز الوراثي للفرد الذي يحمل الصفة السائدة المجهولة النقاوة، حيث يتم تضريبه مع فرد آخر متنحي لتلك الصفة فإذا كان جميع أفراد النسل يحملون الطراز السائد فإن ذلك الفرد يكون نقياً في تلك الصفة، أما إذا كان 50% من أفراد النسل سائد و50% متنحي فيعني ذلك أن الفرد هجين في الصفة. ويمكن توضيح ذلك كالآتي:\nهو تضريب يجرى بين أفراد هجينة من الجيل الأول مع أحد الأبوين أو مع فرد يماثل أحدهما. ويمكن الرجوع إلى الفقرة السابقة (5.3.7) لملاحظة نتائج التضريب مع الأب المتنحي في الصفة. أما نتائج التضريب الرجعي مع الأب السائد النقي في الصفة فيمكن مشاهدته في هذا المثال:", "page": 179, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-32", "type": "comparison", "prompt": "قارن بين النفاذ الجيني والتعبيرية.", "answer": "النفاذ الجيني: هو احتمالية فرد يرث أليل ما ويمتلك الطراز المظهري الذي له علاقة بذلك الأليل.\nأما التعبيرية: فهي تعني وجود أليل بإمكانه إنتاج مدى متغاير من الطرز المظهرية.", "page": 191, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-33", "type": "enumeration", "prompt": "عدد الاعتبارات الواجب مراعاتها عند استخدام كائن لإجراء الدراسات الوراثية.", "answer": "1. قصر دورة حياته.\n2. إنتاجه أعداد كبيرة من النسل.\n3. امتلاكه إمكانية حصول تغايرات وطفرات وراثية عند تعرضه لظروف بيئية غير مناسبة كالإشعاع والمواد الكيميائية.\n4. إمكانية التحكم بالتلقيح أو التزاوج في ذلك الكائن.\n5. سهولة تربيته.\n6. إمكانية إنتاجه تراكيب جديدة نتيجة للتكاثر الجنسي أو الاقتران أو التوصيل (Transduction) والذي يحدث بوساطة الرواشح (Viruses).", "page": 170, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-34", "type": "enumeration", "prompt": "عدد أسباب نجاح مندل في تجاربه.", "answer": "1. اختياره نموذج (Model) رائع في التصميم والتحليل لتجاربه الوراثية والتي أجريت على نبات البزاليا الذي يتسم بتغايره الوراثي وقدرته على النمو بسهولة وقابليته للتهجين بصورة اصطناعية (الشكل 5–4).\n2. لقد حدد فحوصاته على زوج واحد من الصفات أو عدد قليل جداً منها في كل تجربة (الشكل 5–5).\n3. حفظ سجلات مضبوطة والتي اعتمد عليها في التحليل الإحصائي لتجاربه.", "page": 171, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-35", "type": "enumeration", "prompt": "عدد فرضيات مندل الثلاث المستخلصة من التهجين الأحادي.", "answer": "1. تكون العوامل زوجية (Unit Factors in Pairs) أي أن كل صفة يحملها الفرد مسيطر عليها من قبل زوج من العوامل. وعادة يحتوي الفرد الثنائي (Diploid) واحد من ثلاث طرز وراثية تعين الصفة وهي (AA أو Aa أو aa).\n2. الصفة السائدة والمتنحية (Dominant and recessive) عندما يوجد اثنين من العوامل غير المتماثلة (Aa) والمسؤولة عن صفة واحدة في فرد معين فإن أحد هذه العوامل (A) يكون سائد على الآخر المتنحي (a)، علماً بأن العامل المتنحي يكون مسؤول عن إظهار الصفة المتنحية وذلك عندما يكون بحالة زوجية (aa).\n3. الانعزال (Segregation) خلال عملية تكوين الأمشاج، تنفصل أو تنعزل أزواج العوامل غير المتماثلة (Aa) بصورة عشوائية ولهذا فإن كل مشيج سوف يستلم أحد هذين العاملين وباحتمالية متكافئة (شكل 5–7).", "page": 177, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-36", "type": "enumeration", "prompt": "عدد أنواع RNA مع وظيفة كل منها.", "answer": "1. mRNA المراسل (Messenger RNA): وهو جزيء ينقل رسالة وراثية من الـ DNA الموجود في النواة إلى الرايبوسومات الموجودة في السايتوبلازم وذلك في خلايا حقيقية النواة.\n2. rRNA الرايبي الرايبوسومي (Ribosomal RNA): وهو جزء من تركيب الرايبوسومات حيث يشترك مع البروتين في تكوينها.\n3. tRNA الناقل (Transfer RNA): ويقوم بنقل الأحماض الأمينية إلى الرايبوسوم لبناء البروتين. حيث لوحظ أن الأحماض الأمينية ترتبط بهذا الحامض tRNA قبل أن يوصلها إلى الرايبوسوم.", "page": 216, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-37", "type": "enumeration", "prompt": "عدد أنواع الطفرات الاستبدالية.", "answer": "أ. الطفرة الاستبدالية المؤثرة (Missense Mutation).\nب. الطفرة الاستبدالية الكامنة (المحايدة) (Neutral Mutation).\nج. الطفرة الاستبدالية الصامتة (Silent Mutation).\nد. الطفرة الاستبدالية المثبطة (Nonsense Mutation).", "page": 202, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-38", "type": "enumeration", "prompt": "عدد أنواع كروموسومات الإنسان بحسب موضع السنترومير.", "answer": "أ. الكروموسوم وسطي السنترومير (Metacentric chromosome).\nب. الكروموسومات ذات السنتروميرات القريبة من الوسط (Submetacentric Chromosomes).\nج. الكروموسومات ذات السنتروميرات القريبة من الطرف (Acrocentric chromosomes).\nد. كروموسومات طرفية السنترومير (Telocentric Chromosomes).", "page": 208, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-39", "type": "enumeration", "prompt": "عدد الحالات التي يمكن فيها طلب الاستشارة الوراثية.", "answer": "1. معرفة مدى إصابة بعض أفراد العائلة بأحد الأمراض الوراثية.\n2. معرفة ما يؤول إليه زواج أبناء العمومة من أمراض وراثية محتملة.\n3. معرفة سبب عدم انتظام التكوين الجنسي أو تأخر النضج الجنسي.\n4. تقديم الاستشارة في حالة الإجهاضات المتكررة.\n5. في حالة الرغبة في تعيين الأبوة.\n6. في حالة الرغبة بمعرفة مخاطر الأدوية والإشعاع.", "page": 210, "chapter": 5, "chapterTitle": "علم الوراثة"}, {"id": "c5-40", "type": "enumeration", "prompt": "عدد المستلزمات الأساسية لتقنية الهندسة الوراثية.", "answer": "1. طريقة لتقطيع جزيئات الـ DNA الذي يحمل المورث المراد نقله وذلك بوساطة إحدى الإنزيمات القاطعة (Restriction Enzymes).\n2. ناقل مناسب يحمل القطعة الجديدة من الـ DNA ويتم ذلك من خلال اتحادها مع DNA الناقل بمساعدة إنزيم لاحم (DNA Ligase) بحيث تمتاز القطعة المهجنة (rDNA) بقابليتها على التضاعف داخل خلية المضيف.\n3. وسيلة لإدخال القطعة المهجنة (rDNA) (وبضمنها القطعة الحاملة للمورث المراد نقله) إلى خلية المضيف.\n4. طريقة للكشف عن خلية المضيف وأجيالها الحاملة للقطعة المهجنة المرغوبة وعزلها عن بقية أفراد المستعمرة أو العشيرة والتي لا تحتوي على تلك القطعة.", "page": 221, "chapter": 5, "chapterTitle": "علم الوراثة"}];
